window.H=window.H||{};H[31]={"31회-2차-083":{"한줄":"여객자동차터미널·자동차운전학원·폐차장 등 자동차 관련 독립 시설물 부지는 잡종지에 해당하므로(영 제58조제28호다목) ②가 옳다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제28호다목","원문":"여객자동차터미널, 자동차운전학원 및 폐차장 등 자동차와 관련된 독립적인 시설물을 갖춘 부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제6호","원문":"광천지: 지하에서 온수ㆍ약수ㆍ석유류 등이 용출되는 용출구(湧出口)와 그 유지(維持)에 사용되는 부지. 다만, 온수ㆍ약수ㆍ석유류 등을 일정한 장소로 운송하는 송수관ㆍ송유관 및 저장시설의 부지는 제외한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제5호","원문":"임야: 산림 및 원야(原野)를 이루고 있는 수림지(樹林地)ㆍ죽림지ㆍ암석지ㆍ자갈땅ㆍ모래땅ㆍ습지ㆍ황무지 등의 토지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제13호","원문":"창고용지: 물건 등을 보관하거나 저장하기 위하여 독립적으로 설치된 보관시설물의 부지와 이에 접속된 부속시설물의 부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제24호","원문":"유원지: 일반 공중의 위락ㆍ휴양 등에 적합한 시설물을 종합적으로 갖춘 수영장ㆍ유선장(遊船場)ㆍ낚시터ㆍ어린이놀이터ㆍ동물원ㆍ식물원ㆍ민속촌ㆍ경마장ㆍ야영장 등의 토지와 이에 접속된 부속시설물의 부지. 다만, 이들 시설과의 거리 등으로 보아 독립적인 것으로 인정되는 숙식시설 및 유기장(遊技場)의 부지와 하천ㆍ구거 또는 유지[공유(公有)인 것으로 한정한다]로 분류되는 것은 제외한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"변전소·송신소·수신소는 잡종지(나목)지만, 지하에서 석유류 등이 용출되는 용출구와 유지에 사용되는 부지는 광천지다(영 제58조제6호)."},{"번호":2,"판정":"옳음","설명":"여객자동차터미널, 자동차운전학원, 폐차장 등 자동차와 관련된 독립적인 시설물을 갖춘 부지는 잡종지다(영 제58조제28호다목)."},{"번호":3,"판정":"틀림","설명":"갈대밭과 실외 물건 적치장은 잡종지(가목)지만, 산림 및 원야를 이루고 있는 암석지·자갈땅·모래땅·황무지는 임야다(영 제58조제5호)."},{"번호":4,"판정":"틀림","설명":"공항·항만시설 부지는 잡종지(라목)지만, 독립적으로 설치된 보관시설물의 부지는 창고용지다(영 제58조제13호)."},{"번호":5,"판정":"틀림","설명":"도축장·쓰레기처리장·오물처리장은 잡종지(마목)지만, 위락·휴양 시설물을 종합적으로 갖춘 야영장·식물원은 유원지다(영 제58조제24호)."}],"개념":[{"종류":"표","제목":"잡종지에 해당하는 토지(영 제58조제28호)","머리":["목","토지"],"행":[["가","갈대밭, 실외에 물건을 쌓아두는 곳, 돌을 캐내는 곳, 흙을 파내는 곳, 야외시장 및 공동우물"],["나","변전소, 송신소, 수신소 및 송유시설 등의 부지"],["다","여객자동차터미널, 자동차운전학원 및 폐차장 등 자동차와 관련된 독립적인 시설물을 갖춘 부지"],["라","공항시설 및 항만시설 부지"],["마","도축장, 쓰레기처리장 및 오물처리장 등의 부지"],["바","그 밖에 다른 지목에 속하지 않는 토지"]]}],"함정":"각 선지의 앞부분은 잡종지가 맞고 뒷부분에 다른 지목의 토지를 섞어 놓았다. 광천지·임야·창고용지·유원지 중 어느 것이 끼었는지를 찾는다."},"31회-2차-087":{"한줄":"일정한 궤도 등의 설비와 형태를 갖추어 이용되는 토지는 철도용지이므로(영 제58조제15호) 도로로 정할 수 없는 것은 ⑤다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제14호","원문":"도로: 다음 각 목의 토지. 다만, 아파트ㆍ공장 등 단일 용도의 일정한 단지 안에 설치된 통로 등은 제외한다. 가. 일반 공중(公衆)의 교통 운수를 위하여 보행이나 차량운행에 필요한 일정한 설비 또는 형태를 갖추어 이용되는 토지 나. 「도로법」 등 관계 법령에 따라 도로로 개설된 토지 다. 고속도로의 휴게소 부지 라. 2필지 이상에 진입하는 통로로 이용되는 토지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제15호","원문":"철도용지: 교통 운수를 위하여 일정한 궤도 등의 설비와 형태를 갖추어 이용되는 토지와 이에 접속된 역사(驛舍)ㆍ차고ㆍ발전시설 및 공작창(工作廠) 등 부속시설물의 부지"}],"선지":[{"번호":1,"판정":"옳음","설명":"일반 공중의 교통 운수를 위하여 보행이나 차량운행에 필요한 일정한 설비 또는 형태를 갖추어 이용되는 토지는 도로다(영 제58조제14호가목)."},{"번호":2,"판정":"옳음","설명":"도로법 등 관계 법령에 따라 도로로 개설된 토지는 도로다(영 제58조제14호나목)."},{"번호":3,"판정":"옳음","설명":"고속도로의 휴게소 부지는 도로다(영 제58조제14호다목)."},{"번호":4,"판정":"옳음","설명":"2필지 이상에 진입하는 통로로 이용되는 토지는 도로다(영 제58조제14호라목)."},{"번호":5,"판정":"틀림","설명":"일정한 궤도 등의 설비와 형태를 갖추어 이용되는 토지는 철도용지다(영 제58조제15호)."}],"개념":[{"종류":"표","제목":"도로의 범위(영 제58조제14호)","머리":["목","도로로 정하는 토지"],"행":[["가","일반 공중의 교통 운수를 위하여 보행이나 차량운행에 필요한 일정한 설비 또는 형태를 갖추어 이용되는 토지"],["나","도로법 등 관계 법령에 따라 도로로 개설된 토지"],["다","고속도로의 휴게소 부지"],["라","2필지 이상에 진입하는 통로로 이용되는 토지"],["제외","아파트·공장 등 단일 용도의 일정한 단지 안에 설치된 통로 등"]]},{"종류":"비교","제목":"도로와 철도용지","왼쪽":{"이름":"도로","항목":["보행·차량운행에 필요한 설비 또는 형태","고속도로 휴게소 부지 포함","2필지 이상 진입 통로 포함"]},"오른쪽":{"이름":"철도용지","항목":["일정한 궤도 등의 설비와 형태","접속된 역사·차고·발전시설·공작창 등 부속시설물의 부지"]}}],"함정":"⑤는 도로 가목과 같은 교통 운수 문구를 쓰지만 궤도가 있으면 철도용지다. ③ 휴게소 부지, ④ 진입 통로는 도로에 들어가는 항목이다."},"31회-2차-081":{"한줄":"지적공부를 청사 밖으로 반출하려면 천재지변 등을 피하는 경우가 아닌 한 시·도지사 또는 대도시 시장의 승인을 받아야 하므로(법 제69조제1항제2호) 국토교통부장관이라고 한 ②가 틀리다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제69조제1항","원문":"지적소관청은 해당 청사에 지적서고를 설치하고 그 곳에 지적공부(정보처리시스템을 통하여 기록ㆍ저장한 경우는 제외한다. 이하 이 항에서 같다)를 영구히 보존하여야 하며, 다음 각 호의 어느 하나에 해당하는 경우 외에는 해당 청사 밖으로 지적공부를 반출할 수 없다. 1. 천재지변이나 그 밖에 이에 준하는 재난을 피하기 위하여 필요한 경우 2. 관할 시ㆍ도지사 또는 대도시 시장의 승인을 받은 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제65조제1항","원문":"법 제69조제1항에 따른 지적서고는 지적사무를 처리하는 사무실과 연접(連接)하여 설치하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제66조제1항","원문":"부책(簿冊)으로 된 토지대장ㆍ임야대장 및 공유지연명부는 지적공부 보관상자에 넣어 보관하고, 카드로 된 토지대장ㆍ임야대장ㆍ공유지연명부ㆍ대지권등록부 및 경계점좌표등록부는 100장 단위로 바인더(binder)에 넣어 보관하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제66조제2항","원문":"일람도ㆍ지번색인표 및 지적도면은 지번부여지역별로 도면번호순으로 보관하되, 각 장별로 보호대에 넣어야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제67조제1항","원문":"지적소관청이 법 제69조제1항에 따라 지적공부를 그 시ㆍ군ㆍ구의 청사 밖으로 반출하려는 경우에는 시ㆍ도지사 또는 대도시 시장에게 지적공부 반출사유를 적은 별지 제62호서식의 승인신청서를 제출해야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지적소관청은 해당 청사에 지적서고를 설치하고 지적공부를 영구히 보존한다(법 제69조제1항)."},{"번호":2,"판정":"틀림","설명":"반출 승인권자는 관할 시·도지사 또는 대도시 시장이다. 국토교통부장관이 아니다(법 제69조제1항제2호, 규칙 제67조제1항)."},{"번호":3,"판정":"옳음","설명":"지적서고는 지적사무를 처리하는 사무실과 연접하여 설치한다(규칙 제65조제1항)."},{"번호":4,"판정":"옳음","설명":"지적도면은 지번부여지역별로 도면번호순으로 보관하고 각 장별로 보호대에 넣는다(규칙 제66조제2항)."},{"번호":5,"판정":"옳음","설명":"카드로 된 토지대장·임야대장·공유지연명부·대지권등록부 및 경계점좌표등록부는 100장 단위로 바인더에 넣어 보관한다(규칙 제66조제1항)."}],"개념":[{"종류":"표","제목":"지적공부의 보존과 반출","머리":["구분","내용","근거"],"행":[["보존","해당 청사에 지적서고를 설치하고 영구 보존","법 제69조제1항"],["반출 사유 1","천재지변이나 그 밖에 이에 준하는 재난을 피하기 위하여 필요한 경우","법 제69조제1항제1호"],["반출 사유 2","관할 시·도지사 또는 대도시 시장의 승인을 받은 경우","법 제69조제1항제2호"],["승인 절차","지적공부 반출사유를 적은 승인신청서 제출, 시·도지사 또는 대도시 시장이 심사 후 승인 여부 통지","규칙 제67조"],["보관","부책은 보관상자, 카드는 100장 단위로 바인더, 지적도면은 도면번호순으로 보호대","규칙 제66조"],["정보처리시스템 기록분","지적정보관리체계에 영구 보존","법 제69조제2항"]]},{"종류":"표","제목":"지적서고의 설치기준(규칙 제65조)","머리":["항목","기준"],"행":[["위치","지적사무를 처리하는 사무실과 연접하여 설치"],["골조·면적","철근콘크리트 이상의 강질, 면적은 별표 7의 기준면적"],["바닥과 벽","2중, 영구적인 방수설비"],["창문과 출입문","2중, 바깥쪽 문은 반드시 철제, 안쪽 문은 곤충·쥐 등을 막는 철망 등"],["온도·습도","자동조절장치. 연중 평균온도 섭씨 20±5도, 연중평균습도 65±5퍼센트"],["전기시설","단독퓨즈, 소화장비"],["관리","제한구역 지정, 출입자는 지적사무담당공무원, 인화물질 반입 금지"],["보관상자","벽에서 15센티미터 이상 띄우고 높이 10센티미터 이상 깔판 위에 올림"]]}],"함정":"반출 승인권자를 국토교통부장관으로 바꾼 문장이다. 승인권자는 시·도지사 또는 대도시 시장이고 천재지변 반출은 승인이 필요 없다."},"31회-2차-082":{"한줄":"토지대장·임야대장·공유지연명부·대지권등록부에는 모두 토지소유자가 변경된 날과 그 원인을 등록하므로(규칙 제68조제2항제4호, 제3항제3호, 제4항제5호) ⑤가 옳다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제68조제2항제4호","원문":"토지소유자가 변경된 날과 그 원인"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제68조제3항제3호","원문":"토지소유자가 변경된 날과 그 원인"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제68조제4항제5호","원문":"토지소유자가 변경된 날과 그 원인"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제72조","원문":"지적도 및 임야도에는 다음 각 호의 사항을 등록하여야 한다. 1. 토지의 소재 2. 지번 3. 지목 4. 경계 5. 그 밖에 국토교통부령으로 정하는 사항"}],"선지":[{"번호":1,"판정":"틀림","설명":"경계는 지적도·임야도의 등록사항이다. 토지대장에는 면적이 있고 경계는 없다(법 제71조제1항, 제72조제4호)."},{"번호":2,"판정":"틀림","설명":"건축물 및 구조물 등의 위치는 지적도면의 등록사항이다. 임야대장에는 없다(규칙 제69조제2항제6호)."},{"번호":3,"판정":"틀림","설명":"소유권 지분은 공유지연명부의 등록사항이지만 토지의 이동사유는 토지대장·임야대장의 등록사항이다(규칙 제68조제2항제3호)."},{"번호":4,"판정":"틀림","설명":"대지권 비율은 대지권등록부의 등록사항이지만 지목은 토지대장·임야대장과 지적도면의 등록사항이다(법 제71조제1항제3호, 제72조제3호)."},{"번호":5,"판정":"옳음","설명":"토지소유자가 변경된 날과 그 원인은 네 가지 공부 모두의 등록사항이다(규칙 제68조제2항제4호, 제3항제3호, 제4항제5호)."}],"개념":[{"종류":"표","제목":"지적공부별 등록사항(법 제71조~제73조, 규칙 제68조·제69조·제71조)","머리":["공부","등록사항"],"행":[["토지대장·임야대장","토지의 소재, 지번, 지목, 면적, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 지적도 또는 임야도의 번호와 필지별 장번호 및 축척, 토지의 이동사유, 토지소유자가 변경된 날과 그 원인, 토지등급 또는 기준수확량등급과 설정·수정 연월일, 개별공시지가와 그 기준일"],["공유지연명부","토지의 소재, 지번, 소유권 지분, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 필지별 공유지연명부의 장번호, 토지소유자가 변경된 날과 그 원인"],["대지권등록부","토지의 소재, 지번, 대지권 비율, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 전유부분의 건물표시, 건물의 명칭, 집합건물별 대지권등록부의 장번호, 토지소유자가 변경된 날과 그 원인, 소유권 지분"],["경계점좌표등록부","토지의 소재, 지번, 좌표, 토지의 고유번호, 지적도면의 번호, 필지별 경계점좌표등록부의 장번호, 부호 및 부호도"],["지적도·임야도","토지의 소재, 지번, 지목, 경계, 지적도면의 색인도, 지적도면의 제명 및 축척, 도곽선과 그 수치, 좌표에 의하여 계산된 경계점 간의 거리(경계점좌표등록부 시행지역), 삼각점 및 지적기준점의 위치, 건축물 및 구조물 등의 위치"]]},{"종류":"표","제목":"공부 사이 공통 등록사항","머리":["비교","공통 등록사항"],"행":[["공유지연명부와 대지권등록부","토지의 소재, 지번, 소유권 지분, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 토지소유자가 변경된 날과 그 원인"],["토지대장과 공유지연명부","토지의 소재, 지번, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 토지소유자가 변경된 날과 그 원인"],["대지권등록부와 경계점좌표등록부","토지의 소재, 지번, 토지의 고유번호"],["대지권에만 있는 사항","대지권 비율, 전유부분의 건물표시, 건물의 명칭, 집합건물별 대지권등록부의 장번호"],["토지대장·임야대장에만 있는 사항","지목, 면적, 지도 번호와 축척, 토지의 이동사유, 토지등급, 개별공시지가"]]}],"함정":"①은 경계, ②는 건축물 위치, ③은 이동사유, ④는 지목이 각각 다른 공부의 항목이다. 네 장부 모두에 있는 항목은 변경일과 원인이다."},"31회-2차-085":{"한줄":"복구자료는 규칙 제72조에 열거된 일곱 가지뿐이며 개별공시지가 자료와 측량신청서 및 측량 준비도는 포함되지 않으므로 ③이 틀리다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제74조","원문":"지적소관청(제69조제2항에 따른 지적공부의 경우에는 시ㆍ도지사, 시장ㆍ군수 또는 구청장)은 지적공부의 전부 또는 일부가 멸실되거나 훼손된 경우에는 대통령령으로 정하는 바에 따라 지체 없이 이를 복구하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제61조제1항","원문":"지적소관청이 법 제74조에 따라 지적공부를 복구할 때에는 멸실ㆍ훼손 당시의 지적공부와 가장 부합된다고 인정되는 관계 자료에 따라 토지의 표시에 관한 사항을 복구하여야 한다. 다만, 소유자에 관한 사항은 부동산등기부나 법원의 확정판결에 따라 복구하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제72조","원문":"영 제61조제1항에 따른 지적공부의 복구에 관한 관계 자료(이하 \"복구자료\"라 한다)는 다음 각 호와 같다. 1. 지적공부의 등본 2. 측량 결과도 3. 토지이동정리 결의서 4. 토지(건물)등기사항증명서 등 등기사실을 증명하는 서류 5. 지적소관청이 작성하거나 발행한 지적공부의 등록내용을 증명하는 서류 6. 법 제69조제3항에 따라 복제된 지적공부 7. 법원의 확정판결서 정본 또는 사본"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제73조제2항","원문":"지적소관청은 제1항에 따라 조사된 복구자료 중 토지대장ㆍ임야대장 및 공유지연명부의 등록 내용을 증명하는 서류 등에 따라 별지 제70호서식의 지적복구자료 조사서를 작성하고, 지적도면의 등록 내용을 증명하는 서류 등에 따라 복구자료도를 작성하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제73조제3항","원문":"제2항에 따라 작성된 복구자료도에 따라 측정한 면적과 지적복구자료 조사서의 조사된 면적의 증감이 영 제19조제1항제2호가목의 계산식에 따른 허용범위를 초과하거나 복구자료도를 작성할 복구자료가 없는 경우에는 복구측량을 하여야 한다. 이 경우 같은 계산식 중 A는 오차허용면적, M은 축척분모, F는 조사된 면적을 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지적소관청은 지적공부의 전부 또는 일부가 멸실되거나 훼손된 경우 지체 없이 복구한다. 정보처리시스템 기록분은 시·도지사, 시장·군수 또는 구청장이 복구한다(법 제74조)."},{"번호":2,"판정":"옳음","설명":"토지의 표시는 멸실·훼손 당시의 지적공부와 가장 부합되는 관계 자료로 복구하고, 소유자는 부동산등기부나 법원의 확정판결에 따라 복구한다(영 제61조제1항)."},{"번호":3,"판정":"틀림","설명":"지적공부의 등본과 법원의 확정판결서 정본 또는 사본은 복구자료지만, 개별공시지가 자료와 측량신청서 및 측량 준비도는 규칙 제72조에 없다(규칙 제72조)."},{"번호":4,"판정":"옳음","설명":"토지대장·임야대장·공유지연명부는 지적복구자료 조사서, 지적도면은 복구자료도를 작성한다(규칙 제73조제2항)."},{"번호":5,"판정":"옳음","설명":"복구자료도 측정면적과 조사서 면적의 증감이 허용범위를 초과하거나 복구자료도를 작성할 복구자료가 없으면 복구측량을 한다(규칙 제73조제3항)."}],"개념":[{"종류":"표","제목":"지적공부의 복구자료(규칙 제72조)","머리":["호","복구자료"],"행":[["1","지적공부의 등본"],["2","측량 결과도"],["3","토지이동정리 결의서"],["4","토지(건물)등기사항증명서 등 등기사실을 증명하는 서류"],["5","지적소관청이 작성하거나 발행한 지적공부의 등록내용을 증명하는 서류"],["6","법 제69조제3항에 따라 복제된 지적공부"],["7","법원의 확정판결서 정본 또는 사본"]]},{"종류":"흐름","제목":"지적공부의 복구 절차(영 제61조, 규칙 제73조)","단계":[{"이름":"자료 조사","설명":"멸실·훼손 당시의 지적공부와 가장 부합된다고 인정되는 관계 자료(복구자료)를 조사(영 제61조제1항, 규칙 제73조제1항)"},{"이름":"조사서·복구자료도 작성","설명":"토지대장·임야대장·공유지연명부는 지적복구자료 조사서, 지적도면은 복구자료도로 작성(규칙 제73조제2항)"},{"이름":"면적 판단","설명":"복구자료도 측정면적과 조사서 면적의 증감이 영 제19조의 허용범위를 초과하거나 복구자료도를 만들 자료가 없으면 복구측량, 허용범위 이내이면 조사된 면적이 복구면적(규칙 제73조제3항·제4항)"},{"이름":"게시","설명":"복구하려는 토지의 표시 등을 시·군·구 게시판 및 인터넷 홈페이지에 15일 이상 게시(규칙 제73조제6항)"},{"이름":"이의신청","설명":"게시기간 내에 이의가 있는 자는 지적소관청에 이의신청, 이유 있으면 시정 조치(규칙 제73조제7항)"},{"이름":"복구","설명":"조사서, 복구자료도, 복구측량 결과도 등에 따라 토지대장·임야대장·공유지연명부 또는 지적도면을 복구(규칙 제73조제8항)"}]}],"함정":"③은 지적공부의 등본과 확정판결서 사이에 복구자료가 아닌 개별공시지가 자료, 측량신청서 및 측량 준비도를 끼워 넣었다. 측량 결과도는 복구자료이지만 측량신청서와 측량 준비도는 아니다."},"31회-2차-084":{"한줄":"축척변경 시행공고에는 목적·시행지역·시행기간, 세부계획, 청산방법, 토지소유자 등의 협조 사항을 담는다. 시행자 선정 및 평가방법은 공고사항이 아니다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제71조제1항","원문":"지적소관청은 법 제83조제3항에 따라 시ㆍ도지사 또는 대도시 시장으로부터 축척변경 승인을 받았을 때에는 지체 없이 다음 각 호의 사항을 20일 이상 공고하여야 한다. 1. 축척변경의 목적, 시행지역 및 시행기간 2. 축척변경의 시행에 관한 세부계획 3. 축척변경의 시행에 따른 청산방법 4. 축척변경의 시행에 따른 토지소유자 등의 협조에 관한 사항"}],"선지":[{"번호":1,"판정":"옳음","설명":"축척변경의 목적, 시행지역 및 시행기간은 제1호 공고사항이다."},{"번호":2,"판정":"옳음","설명":"축척변경의 시행에 관한 세부계획은 제2호 공고사항이다."},{"번호":3,"판정":"틀림","설명":"축척변경의 시행자 선정 및 평가방법은 공고사항이 아니다. 축척변경은 지적소관청이 시행한다."},{"번호":4,"판정":"옳음","설명":"축척변경의 시행에 따른 청산방법은 제3호 공고사항이다."},{"번호":5,"판정":"옳음","설명":"토지소유자 등의 협조에 관한 사항은 제4호 공고사항이다."}],"개념":[{"종류":"표","제목":"축척변경 시행공고(영 제71조)","머리":["구분","내용"],"행":[["공고 시기","시·도지사 또는 대도시 시장의 승인을 받았을 때 지체 없이"],["공고 기간","20일 이상"],["공고 사항","축척변경의 목적·시행지역·시행기간 / 시행에 관한 세부계획 / 시행에 따른 청산방법 / 시행에 따른 토지소유자 등의 협조에 관한 사항"],["공고 방법","시·군·구(자치구가 아닌 구 포함) 및 시행지역 동·리의 게시판에 게시"],["경계점표지 설치","시행공고일부터 30일 이내, 시행공고일 현재 점유하고 있는 경계에 설치"]]},{"종류":"흐름","제목":"축척변경 절차에서 시행공고의 위치","단계":[{"이름":"신청 또는 직권","설명":"지적도가 일정한 사유에 해당하면 토지소유자의 신청 또는 지적소관청의 직권으로 일정 지역의 축척을 변경한다(법 제83조제2항)."},{"이름":"동의·의결·승인","설명":"축척변경 시행지역 토지소유자 3분의 2 이상의 동의, 축척변경위원회의 의결, 시·도지사 또는 대도시 시장의 승인(법 제83조제3항)."},{"이름":"시행공고","설명":"승인을 받으면 지체 없이 20일 이상 공고(영 제71조제1항). 토지소유자·점유자는 공고일부터 30일 이내에 경계점표지를 설치(영 제71조제3항)."},{"이름":"측량과 조서","설명":"새 축척으로 측량하고 시행공고일 현재의 면적과 측량 후 면적을 비교한 축척변경 지번별 조서를 작성(영 제72조, 제73조)."},{"이름":"청산금 산정·공고","설명":"지번별 제곱미터당 금액은 위원회 의결로 정하고, 청산금 결정을 15일 이상 공고(영 제75조)."},{"이름":"납부고지·이의신청","설명":"공고일부터 20일 이내에 납부고지·수령통지(영 제76조제1항). 이의신청은 통지를 받은 날부터 1개월 이내, 지적소관청은 1개월 이내에 위원회 의결을 거쳐 결정(영 제77조)."},{"이름":"확정공고","설명":"청산금의 납부 및 지급이 완료되면 지체 없이 확정공고하고 확정된 사항을 지적공부에 등록한다. 확정공고일에 토지의 이동이 있는 것으로 본다(영 제78조)."}]}],"함정":"공고사항은 목적·세부계획·청산방법·협조사항 네 가지다. 축척변경은 지적소관청이 하는 절차여서 시행자를 선정하거나 평가한다는 공고사항이 없다."},"31회-2차-086":{"한줄":"등록전환할 때 임야대장의 면적과 등록전환될 면적의 차이가 허용범위를 초과하면 지적소관청이 임야대장의 면적 또는 임야도의 경계를 직권으로 정정해야 한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제19조제1항제1호 나목","원문":"나. 임야대장의 면적과 등록전환될 면적의 차이가 가목의 계산식에 따른 허용범위 이내인 경우에는 등록전환될 면적을 등록전환 면적으로 결정하고, 허용범위를 초과하는 경우에는 임야대장의 면적 또는 임야도의 경계를 지적소관청이 직권으로 정정하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"허용범위를 초과하면 지적소관청이 임야대장의 면적 또는 임야도의 경계를 직권으로 정정해야 한다(영 제19조제1항제1호 나목)."},{"번호":2,"판정":"틀림","설명":"시·도지사의 승인을 받아 초과 면적을 등록전환 면적으로 결정하는 절차는 없다."},{"번호":3,"판정":"틀림","설명":"지적측량수행자가 지적소관청의 승인을 받아 결정하는 절차는 없다. 정정 주체는 지적소관청이다."},{"번호":4,"판정":"틀림","설명":"토지소유자와의 합의로 면적을 결정하는 규정은 없다."},{"번호":5,"판정":"틀림","설명":"지적측량수행자는 직권정정의 주체가 아니다. 임야대장의 면적 또는 임야도의 경계는 지적소관청이 정정한다."}],"개념":[{"종류":"표","제목":"등록전환·분할 시 면적 오차의 처리(영 제19조제1항)","머리":["구분","허용범위 이내","허용범위 초과"],"행":[["등록전환","등록전환될 면적을 등록전환 면적으로 결정","지적소관청이 임야대장의 면적 또는 임야도의 경계를 직권으로 정정"],["분할","오차를 분할 후 각 필지의 면적에 따라 나눔","지적공부상의 면적 또는 경계를 정정"],["경계점좌표등록부 시행지역의 분할","분할 전 면적에 증감이 없도록 끝자리를 올리거나 버려서 정함","같음(영 제19조제2항)"]]},{"종류":"표","제목":"등록전환을 신청할 수 있는 경우(영 제64조제1항)","머리":["호","사유"],"행":[["1","산지전용허가·신고, 건축허가·신고, 그 밖의 개발행위 허가 등을 받은 경우"],["2","대부분의 토지가 등록전환되어 나머지 토지를 임야도에 계속 존치하는 것이 불합리한 경우"],["3","임야도에 등록된 토지가 사실상 형질변경되었으나 지목변경을 할 수 없는 경우"],["4","도시·군관리계획선에 따라 토지를 분할하는 경우"]]}],"함정":"허용범위를 넘으면 측량수행자도, 토지소유자와의 합의도 아니고 지적소관청의 직권정정으로 처리한다. 선지 ②~⑤는 모두 근거 없는 절차다."},"31회-2차-089":{"한줄":"도시개발사업 등의 착수·변경·완료 사실은 지적소관청에 신고하며(법 제86조제1항) 그 사유가 발생한 날부터 15일 이내에 해야 한다(영 제83조제2항).","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제86조제1항","원문":"「도시개발법」에 따른 도시개발사업, 「농어촌정비법」에 따른 농어촌정비사업, 그 밖에 대통령령으로 정하는 토지개발사업의 시행자는 대통령령으로 정하는 바에 따라 그 사업의 착수ㆍ변경 및 완료 사실을 지적소관청에 신고하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제83조제2항","원문":"법 제86조제1항에 따른 도시개발사업 등의 착수ㆍ변경 또는 완료 사실의 신고는 그 사유가 발생한 날부터 15일 이내에 하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"신고 상대방은 시·도지사가 아니라 지적소관청이고 기한도 15일이다."},{"번호":2,"판정":"틀림","설명":"신고 상대방이 시·도지사가 아니고 기한도 30일이 아니다."},{"번호":3,"판정":"틀림","설명":"신고 상대방이 시·도지사가 아니고 기한도 60일이 아니다."},{"번호":4,"판정":"옳음","설명":"지적소관청에 신고하고(ㄱ), 사유가 발생한 날부터 15일 이내(ㄴ)에 해야 한다."},{"번호":5,"판정":"틀림","설명":"상대방은 지적소관청이 맞으나 기한이 30일이 아니라 15일이다."}],"개념":[{"종류":"비교","제목":"도시개발사업 등 시행지역의 신고와 토지이동 신청","왼쪽":{"이름":"사업의 착수·변경·완료 신고","항목":["신고인: 사업의 시행자","상대방: 지적소관청","기한: 사유가 발생한 날부터 15일 이내","첨부서류: 사업인가서, 지번별 조서, 사업계획도(착수·변경)"]},"오른쪽":{"이름":"토지의 이동 신청","항목":["신청인: 해당 사업의 시행자","상대방: 지적소관청","토지의 이동은 공사가 준공된 때 이루어진 것으로 봄","환지를 수반하는 경우 사업완료 신고로 갈음 가능"]}},{"종류":"표","제목":"신청·신고 기한 비교","머리":["대상","기한"],"행":[["도시개발사업 등의 착수·변경·완료 신고","15일 이내"],["신규등록·등록전환·지목변경·합병(의무 신청)","60일 이내"],["바다로 된 토지의 등록말소","통지받은 날부터 90일 이내"],["축척변경 경계점표지 설치","시행공고일부터 30일 이내"]]}],"함정":"기한 15일과 신청 기한 60일을 혼동하면 ㄴ에서 틀린다. 상대방은 시·도지사가 아니라 지적소관청이다."},"31회-2차-090":{"한줄":"등록사항 정정 대상토지에 대한 대장을 열람하게 하거나 등본을 발급하는 때에는 '등록사항 정정 대상토지'라고 적은 부분을 흑백의 반전으로 표시하거나 붉은색으로 적어야 한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제94조제2항","원문":"제1항에 따른 등록사항 정정 대상토지에 대한 대장을 열람하게 하거나 등본을 발급하는 때에는 \"등록사항 정정 대상토지\"라고 적은 부분을 흑백의 반전(反轉)으로 표시하거나 붉은색으로 적어야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"'지적불부합지'가 아니라 '등록사항 정정 대상토지'라고 적는다."},{"번호":2,"판정":"틀림","설명":"문구와 표시방법 모두 다르다. 굵은 고딕체가 아니라 붉은색이다."},{"번호":3,"판정":"틀림","설명":"문구가 틀렸고 담당자의 자필로 적는다는 규정도 없다."},{"번호":4,"판정":"옳음","설명":"'등록사항 정정 대상토지'라고 적은 부분을 흑백의 반전으로 표시하거나 붉은색으로 적는다(규칙 제94조제2항)."},{"번호":5,"판정":"틀림","설명":"문구는 맞으나 굵은 고딕체가 아니라 붉은색으로 적는다."}],"개념":[{"종류":"흐름","제목":"등록사항 정정 대상토지의 처리(규칙 제94조)","단계":[{"이름":"잘못 발견","설명":"지적소관청이 토지의 표시가 잘못되었음을 발견한다."},{"이름":"서류 작성","설명":"등록사항 정정에 필요한 서류와 등록사항 정정 측량성과도를 작성하고 토지이동정리 결의서를 작성한다."},{"이름":"대장 기재","설명":"대장의 사유란에 등록사항정정 대상토지라고 적는다."},{"이름":"소유자 통지","설명":"토지소유자에게 정정 신청을 할 수 있도록 사유를 통지한다. 직권으로 정정할 수 있는 경우는 통지하지 않을 수 있다."},{"이름":"열람·등본 발급","설명":"'등록사항 정정 대상토지'라고 적은 부분을 흑백의 반전으로 표시하거나 붉은색으로 적는다."}]},{"종류":"표","제목":"등록사항의 정정(법 제84조)","머리":["항","내용"],"행":[["제1항","토지소유자의 정정 신청"],["제2항","지적소관청의 직권 조사·측량 후 정정"],["제3항","인접 토지의 경계가 변경되면 인접 토지소유자의 승낙서 또는 확정판결서 정본 제출"],["제4항","토지소유자에 관한 사항은 등기필증, 등기완료통지서, 등기사항증명서 또는 등기전산정보자료에 따라 정정"]]}],"함정":"문구는 '등록사항 정정 대상토지'이고 표시는 흑백 반전 또는 붉은색이다. 지적불부합지는 다른 개념이므로 ①~③이 걸러진다."},"31회-2차-091":{"한줄":"청산금의 납부 및 지급이 완료되었을 때 지적소관청은 지체 없이 축척변경의 확정공고를 해야 한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제78조","원문":"청산금의 납부 및 지급이 완료되었을 때에는 지적소관청은 지체 없이 축척변경의 확정공고를 하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제78조제2항","원문":"지적소관청은 제1항에 따른 확정공고를 하였을 때에는 지체 없이 축척변경에 따라 확정된 사항을 지적공부에 등록하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제78조제3항","원문":"축척변경 시행지역의 토지는 제1항에 따른 확정공고일에 토지의 이동이 있는 것으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"청산금의 납부 및 지급이 완료되었을 때 확정공고를 한다(영 제78조제1항)."},{"번호":2,"판정":"틀림","설명":"측량이 완료되면 축척변경 지번별 조서를 작성한다(영 제73조). 확정공고 시기가 아니다."},{"번호":3,"판정":"틀림","설명":"필지별 증감면적의 산정은 청산금 산정 단계다(영 제75조). 확정공고 시기가 아니다."},{"번호":4,"판정":"틀림","설명":"지번별 조서 작성은 측량 완료 후의 절차다(영 제73조). 확정공고 시기가 아니다."},{"번호":5,"판정":"틀림","설명":"확정된 사항의 지적공부 등록은 확정공고 후에 한다(영 제78조제2항)."}],"개념":[{"종류":"흐름","제목":"축척변경 확정공고까지의 순서","단계":[{"이름":"측량 완료","설명":"축척변경 지번별 조서를 작성한다(영 제73조)."},{"이름":"청산금 산정","설명":"지번별 제곱미터당 금액을 위원회 의결로 정하고 청산금을 산정한다(영 제75조)."},{"이름":"청산금 공고","설명":"청산금 조서를 작성하고 15일 이상 공고한다(영 제75조제4항)."},{"이름":"납부고지·수령통지","설명":"공고한 날부터 20일 이내(영 제76조제1항)."},{"이름":"청산금 납부·지급 완료","설명":"납부고지를 받은 자는 6개월 이내 납부, 지적소관청은 수령통지를 한 날부터 6개월 이내 지급(영 제76조제2항·제3항)."},{"이름":"확정공고","설명":"청산금의 납부 및 지급이 완료되었을 때 지체 없이(영 제78조제1항)."},{"이름":"지적공부 등록","설명":"확정된 사항을 지체 없이 지적공부에 등록. 확정공고일에 토지의 이동이 있는 것으로 봄(제2항·제3항)."}]},{"종류":"표","제목":"확정공고 전후의 효과","머리":["시점","효과","근거"],"행":[["시행기간 중","지적공부정리와 경계복원측량을 확정공고일까지 정지(경계점표지 설치를 위한 측량은 제외)","영 제74조"],["확정공고","확정된 사항을 지적공부에 등록","영 제78조제2항"],["확정공고일","축척변경 시행지역의 토지에 토지의 이동이 있는 것으로 봄","영 제78조제3항"]]}],"함정":"확정공고 시기는 지적공부 등록이 아니라 청산금 정리 완료 시점이다. ⑤는 순서를 뒤집은 선지로, 지적공부 등록은 확정공고 뒤에 이어진다."},"31회-2차-088":{"한줄":"지적재조사 기본계획의 수립 및 변경은 중앙지적재조사위원회의 심의·의결사항이고 중앙지적위원회의 소관이 아니므로 ③이 틀리다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제28조제1항","원문":"다음 각 호의 사항을 심의ㆍ의결하기 위하여 국토교통부에 중앙지적위원회를 둔다."},{"법령":"지적재조사에 관한 특별법","조문":"법 제28조제2항제1호","원문":"기본계획의 수립 및 변경"}],"선지":[{"번호":1,"판정":"옳음","설명":"지적기술자의 양성에 관한 사항은 중앙지적위원회 소관이다(법 제28조제1항제4호)."},{"번호":2,"판정":"옳음","설명":"지적측량기술의 연구·개발 및 보급은 중앙지적위원회 소관이다(법 제28조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"지적재조사 기본계획의 수립 및 변경은 중앙지적재조사위원회가 심의·의결한다(지적재조사에 관한 특별법 제28조제2항제1호)."},{"번호":4,"판정":"옳음","설명":"지적 관련 정책 개발 및 업무 개선 등은 중앙지적위원회 소관이다(법 제28조제1항제1호)."},{"번호":5,"판정":"옳음","설명":"지적기술자의 업무정지 처분 및 징계요구는 중앙지적위원회 소관이다(법 제28조제1항제5호)."}],"개념":[{"종류":"표","제목":"중앙지적위원회 심의·의결 사항(법 제28조제1항)","머리":["호","사항"],"행":[["1","지적 관련 정책 개발 및 업무 개선 등에 관한 사항"],["2","지적측량기술의 연구·개발 및 보급에 관한 사항"],["3","지적측량 적부심사에 대한 재심사"],["4","측량기술자 중 지적분야 측량기술자(지적기술자)의 양성에 관한 사항"],["5","지적기술자의 업무정지 처분 및 징계요구에 관한 사항"]]},{"종류":"표","제목":"중앙지적재조사위원회(지적재조사에 관한 특별법 제28조)","머리":["구분","내용"],"행":[["소속","국토교통부장관 소속"],["심의·의결","기본계획의 수립 및 변경, 관계 법령의 제정·개정 및 제도의 개선, 위원장이 회의에 부치는 사항"],["구성","위원장 및 부위원장 각 1명을 포함한 15명 이상 20명 이하"],["위원장","국토교통부장관"]]}],"함정":"위원회 이름이 비슷하다. 지적재조사사업의 정책(기본계획)은 중앙지적재조사위원회이고 중앙지적위원회는 지적측량 적부심사 재심사와 기술자 관련 사항을 맡는다. 법 제28조제1항의 다섯 가지 사항을 외워 둔다."},"31회-2차-092":{"한줄":"지적삼각점성과는 시·도지사 또는 지적소관청에, 지적삼각보조점성과와 지적도근점성과는 지적소관청에 열람·등본발급을 신청하므로 ①이 옳다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제27조","원문":"시ㆍ도지사나 지적소관청은 지적기준점성과(지적기준점에 의한 측량성과를 말한다. 이하 같다)와 그 측량기록을 보관하고 일반인이 열람할 수 있도록 하여야 한다. ② 지적기준점성과의 등본이나 그 측량기록의 사본을 발급받으려는 자는 국토교통부령으로 정하는 바에 따라 시ㆍ도지사나 지적소관청에 그 발급을 신청하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"시행규칙 제26조제1항","원문":"법 제27조에 따라 지적측량기준점성과 또는 그 측량부를 열람하거나 등본을 발급받으려는 자는 지적삼각점성과에 대해서는 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다) 또는 지적소관청에 신청하고, 지적삼각보조점성과 및 지적도근점성과에 대해서는 지적소관청에 신청하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지적삼각점성과는 시·도지사 또는 지적소관청에 신청한다(시행규칙 제26조제1항)."},{"번호":2,"판정":"틀림","설명":"지적삼각보조점성과는 지적소관청에 신청한다. 시·도지사가 아니다(시행규칙 제26조제1항)."},{"번호":3,"판정":"틀림","설명":"지적삼각보조점성과는 지적소관청에 신청한다. 한국국토정보공사에 신청하는 규정은 없다."},{"번호":4,"판정":"틀림","설명":"지적도근점성과는 지적소관청에 신청한다. 시·도지사나 한국국토정보공사가 아니다."},{"번호":5,"판정":"틀림","설명":"지적도근점성과는 지적소관청에 신청한다. 한국국토정보공사에 신청하는 규정은 없다."}],"개념":[{"종류":"표","제목":"지적기준점성과의 열람·등본 발급 신청 기관(시행규칙 제26조제1항)","머리":["지적기준점성과","신청 기관"],"행":[["지적삼각점성과","시·도지사 또는 지적소관청"],["지적삼각보조점성과","지적소관청"],["지적도근점성과","지적소관청"]]},{"종류":"표","제목":"지적기준점성과의 보관(법 제27조)","머리":["구분","내용"],"행":[["보관·열람","시·도지사나 지적소관청이 지적기준점성과와 그 측량기록을 보관하고 일반인이 열람할 수 있게 함"],["등본·사본 발급","시·도지사나 지적소관청에 신청"]]}],"함정":"지적삼각점만 시·도지사에게도 신청할 수 있고 삼각보조점과 도근점은 지적소관청에만 한다. 한국국토정보공사는 신청 기관이 아니다. 법 제27조는 보관 주체를 시·도지사나 지적소관청으로 정한다."},"31회-2차-094":{"한줄":"매도인 甲이 사망한 경우 단독상속인 丙은 포괄승계인으로서 등기의무자가 되어 甲과 乙의 매매를 원인으로 한 이전등기를 신청할 수 있으므로 ④가 옳다.","근거":[{"법령":"부동산등기법","조문":"법 제27조","원문":"등기원인이 발생한 후에 등기권리자 또는 등기의무자에 대하여 상속이나 그 밖의 포괄승계가 있는 경우에는 상속인이나 그 밖의 포괄승계인이 그 등기를 신청할 수 있다."},{"법령":"부동산등기법","조문":"법 제76조제1항","원문":"등기관이 「민법」 제348조에 따라 저당권부채권(抵當權附債權)에 대한 질권의 등기를 할 때에는 제48조에서 규정한 사항 외에 다음 각 호의 사항을 기록하여야 한다."},{"법령":"부동산등기법","조문":"법 제4조제2항","원문":"등기의 순서는 등기기록 중 같은 구(區)에서 한 등기 상호간에는 순위번호에 따르고, 다른 구에서 한 등기 상호간에는 접수번호에 따른다."},{"법령":"부동산등기법","조문":"법 제26조제1항","원문":"종중(宗中), 문중(門中), 그 밖에 대표자나 관리인이 있는 법인 아닌 사단(社團)이나 재단(財團)에 속하는 부동산의 등기에 관하여는 그 사단이나 재단을 등기권리자 또는 등기의무자로 한다."},{"법령":"부동산등기법","조문":"법 제41조제3항","원문":"구분건물로서 그 대지권의 변경이나 소멸이 있는 경우에는 구분건물의 소유권의 등기명의인은 1동의 건물에 속하는 다른 구분건물의 소유권의 등기명의인을 대위하여 그 등기를 신청할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"저당권부채권에 대한 질권의 설정등기를 할 수 있다(법 제76조제1항)."},{"번호":2,"판정":"틀림","설명":"다른 구에서 한 등기 상호간의 순위는 접수번호에 따른다. 순위번호에 따르는 것은 같은 구에서 한 등기 상호간이다(법 제4조제2항)."},{"번호":3,"판정":"틀림","설명":"대표자가 있는 법인 아닌 재단의 부동산은 그 재단을 등기권리자 또는 등기의무자로 한다(법 제26조제1항). 대표자가 아니다."},{"번호":4,"판정":"옳음","설명":"등기원인이 발생한 후 상속이 있으면 상속인이 등기를 신청할 수 있다(법 제27조)."},{"번호":5,"판정":"틀림","설명":"대지권의 변경이나 소멸이 있으면 구분건물의 소유권 등기명의인이 1동의 다른 구분건물의 소유권 등기명의인을 대위하여 변경등기를 신청할 수 있다(법 제41조제3항)."}],"개념":[{"종류":"표","제목":"등기신청 관련 규정","머리":["구분","내용","조문"],"행":[["공동신청","등기권리자와 등기의무자가 공동으로 신청","법 제23조제1항"],["포괄승계인의 신청","등기원인 발생 후 상속·포괄승계가 있으면 상속인·포괄승계인이 신청","법 제27조"],["법인 아닌 사단·재단","그 사단·재단을 등기권리자·의무자로 하고 대표자·관리인이 신청","법 제26조"],["권리의 순위","같은 구는 순위번호, 다른 구는 접수번호","법 제4조제2항"],["저당권부채권에 대한 질권","질권 설정등기 가능","법 제76조"],["구분건물 대지권 변경·소멸","구분건물 소유권 등기명의인이 다른 구분건물 명의인을 대위하여 신청 가능","법 제41조제3항"]]}],"함정":"④는 등기원인 후 상속이 있는 경우의 포괄승계인 신청이다. 등기의무자 지위를 상속인이 이어받으므로 매도인이 죽어도 공동신청 구조가 유지된다. ②는 같은 구와 다른 구의 순위 기준을 바꿔 적었다."},"31회-2차-022":{"한줄":"운영규정 위반 거래정보사업자와 보고의무 위반 거래정보사업자는 국토교통부장관이, 등록증 미게시 개업공인중개사는 등록관청이 과태료를 부과하므로 ㄱ, ㄴ, ㄷ이 바르게 연결됐다.","근거":[{"법령":"공인중개사법","조문":"법 제51조제2항제1호의5","원문":"제24조제3항을 위반하여 운영규정의 승인 또는 변경승인을 얻지 아니하거나 운영규정의 내용을 위반하여 부동산거래정보망을 운영한 자"},{"법령":"공인중개사법","조문":"법 제51조제2항제6호","원문":"제37조제1항에 따른 보고, 자료의 제출, 조사 또는 검사를 거부ㆍ방해 또는 기피하거나 그 밖의 명령을 이행하지 아니하거나 거짓으로 보고 또는 자료제출을 한 거래정보사업자"},{"법령":"공인중개사법","조문":"법 제51조제3항제1호","원문":"제17조를 위반하여 중개사무소등록증 등을 게시하지 아니한 자"},{"법령":"공인중개사법","조문":"법 제51조제3항제6호","원문":"제35조제3항 또는 제4항을 위반하여 공인중개사자격증을 반납하지 아니하거나 공인중개사자격증을 반납할 수 없는 사유서를 제출하지 아니한 자 또는 거짓으로 공인중개사자격증을 반납할 수 없는 사유서를 제출한 자"},{"법령":"공인중개사법","조문":"법 제51조제3항제7호","원문":"제38조제4항을 위반하여 중개사무소등록증을 반납하지 아니한 자"},{"법령":"공인중개사법","조문":"법 제51조제5항제1호","원문":"제2항제1호의2ㆍ제1호의3ㆍ제1호의5, 제6호부터 제8호까지, 제8호의2 및 제9호의 경우: 국토교통부장관"},{"법령":"공인중개사법","조문":"법 제51조제5항제2호","원문":"제2항제5호의2 및 제3항제6호의 경우: 시ㆍ도지사"},{"법령":"공인중개사법","조문":"법 제51조제5항제4호","원문":"제2항제1호ㆍ제1호의4ㆍ제1호의6, 제3항제1호ㆍ제2호ㆍ제2호의2, 제3호부터 제5호까지 및 제7호의 경우: 등록관청"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄴ도 바르게 연결돼 있어 ㄱ, ㄷ만 고르면 부족하다."},{"번호":2,"판정":"옳음","설명":"ㄱ, ㄴ, ㄷ만 부과기관이 맞게 연결됐다."},{"번호":3,"판정":"틀림","설명":"ㄹ과 ㅁ은 부과기관이 틀리다. ㄱ, ㄷ도 빠졌다."},{"번호":4,"판정":"틀림","설명":"ㄹ은 시·도지사가 부과하는 사항이다. ㄱ, ㄴ, ㄷ에 ㄹ을 더하면 틀린다."},{"번호":5,"판정":"틀림","설명":"ㄹ과 ㅁ이 틀리므로 다섯 보기를 모두 고르면 맞지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"운영규정의 내용을 위반하여 부동산거래정보망을 운영한 거래정보사업자는 국토교통부장관이 과태료를 부과한다(법 제51조제2항제1호의5, 제5항제1호)."},{"기호":"ㄴ","판정":"옳음","설명":"보고의무를 위반한 거래정보사업자는 국토교통부장관이 과태료를 부과한다(법 제51조제2항제6호, 제5항제1호)."},{"기호":"ㄷ","판정":"옳음","설명":"중개사무소등록증을 게시하지 않은 개업공인중개사는 등록관청이 과태료를 부과한다(법 제51조제3항제1호, 제5항제4호)."},{"기호":"ㄹ","판정":"틀림","설명":"공인중개사자격증을 반납하지 않은 자는 시·도지사가 과태료를 부과한다(법 제51조제3항제6호, 제5항제2호). 등록관청이 아니다."},{"기호":"ㅁ","판정":"틀림","설명":"중개사무소등록증을 반납하지 않은 자는 등록관청이 과태료를 부과한다(법 제51조제3항제7호, 제5항제4호). 시·도지사가 아니다."}],"개념":[{"종류":"표","제목":"과태료 부과기관(법 제51조제5항)","머리":["부과기관","대상 위반행위"],"행":[["국토교통부장관","거래정보사업자의 운영규정 승인·변경승인 미이행 및 운영규정 위반(제2항제1호의5), 거래정보사업자의 보고·자료제출·조사·검사 거부 등(제2항제6호), 공제사업 운용실적 미공시(제2항제7호), 공제업무 개선명령 불이행(제2항제8호) 등"],["시·도지사","연수교육을 정당한 사유 없이 받지 않은 자(제2항제5호의2), 공인중개사자격증을 반납하지 않거나 사유서를 제출하지 않은 자(제3항제6호)"],["등록관청","부당한 표시·광고(제2항제1호), 등록증 등 미게시(제3항제1호), 명칭 위반(제3항제2호), 이전신고 미이행(제3항제3호), 휴업·폐업 신고 미이행(제3항제4호), 손해배상책임 설명·증서 교부 미이행(제3항제5호), 중개사무소등록증 미반납(제3항제7호) 등"]]}],"함정":"자격증 미반납(ㄹ)은 시·도지사, 등록증 미반납(ㅁ)은 등록관청이 부과한다. 보기 ㄹ과 ㅁ은 이 둘을 바꿔 적었다. 거래정보사업자를 대상으로 하는 과태료는 국토교통부장관이 부과한다."},"31회-2차-012":{"한줄":"시행규칙 제10조는 사업자등록증(제5호)과 분사무소설치신고확인서 원본(제1호)을 게시 대상으로 정하므로 ③과 ⑤가 해당한다.","근거":[{"법령":"공인중개사법","조문":"법 제17조","원문":"개업공인중개사는 중개사무소등록증ㆍ중개보수표 그 밖에 국토교통부령으로 정하는 사항을 해당 중개사무소 안의 보기 쉬운 곳에 게시하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제10조제1호","원문":"중개사무소등록증 원본(법인인 개업공인중개사의 분사무소의 경우에는 분사무소설치신고확인서 원본을 말한다)"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제10조제3호","원문":"개업공인중개사 및 소속공인중개사의 공인중개사자격증 원본(해당되는 자가 있는 경우로 한정한다)"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제10조제5호","원문":"「부가가치세법 시행령」 제11조에 따른 사업자등록증"}],"선지":[{"번호":1,"판정":"틀림","설명":"개업공인중개사의 실무교육 수료확인증은 시행규칙 제10조의 게시 사항에 없다."},{"번호":2,"판정":"틀림","설명":"소속공인중개사의 실무교육 수료확인증도 게시 사항에 없다."},{"번호":3,"판정":"옳음","설명":"사업자등록증은 게시 사항이다(시행규칙 제10조제5호)."},{"번호":4,"판정":"틀림","설명":"게시하는 것은 소속공인중개사의 공인중개사자격증 원본이다(시행규칙 제10조제3호). 사본이 아니다."},{"번호":5,"판정":"옳음","설명":"분사무소는 중개사무소등록증 대신 분사무소설치신고확인서 원본을 게시한다(시행규칙 제10조제1호)."}],"개념":[{"종류":"표","제목":"중개사무소 안에 게시할 사항(시행규칙 제10조)","머리":["호","게시 사항"],"행":[["1","중개사무소등록증 원본(분사무소는 분사무소설치신고확인서 원본)"],["2","중개보수·실비의 요율 및 한도액표"],["3","개업공인중개사 및 소속공인중개사의 공인중개사자격증 원본(해당자가 있는 경우)"],["4","보증의 설정을 증명할 수 있는 서류"],["5","부가가치세법 시행령 제11조에 따른 사업자등록증"],["제재","게시 위반은 100만원 이하 과태료(법 제51조제3항제1호), 등록관청이 부과"]]}],"함정":"게시 사항 다섯 가지에 실무교육 수료확인증은 없다. ④는 자격증 원본을 사본으로 바꿨다. ③은 공식 정답에서 빠졌지만 제10조제5호가 사업자등록증을 게시 대상으로 정하고 있어 현행 조문으로는 정답이 ③과 ⑤ 둘이다.","개정":"현행 시행규칙 제10조제5호가 사업자등록증을 게시 사항으로 정하고 있어 ③도 게시 대상이다. 공식 정답은 ⑤ 하나였으나 현행 기준 정답은 ③, ⑤ 둘이다. ⑤의 「신고필증」은 시행규칙 제10조제1호에서 「분사무소설치신고확인서」로 바뀐 용어(2021.1.12 개정)를 반영했다."},"31회-2차-034":{"한줄":"중개업무 처리상황 통지의무(2주일에 1회 이상 문서 통지)는 전속중개계약서에만 있으므로 일반·전속 서식의 공통 사항이 아니다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별지 제15호서식(전속중개계약서) 1. 을의 의무사항","원문":"① 을은 갑에게 계약체결 후 2주일에 1회 이상 중개업무 처리상황을 문서로 통지하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별지 제14호서식(일반중개계약서) 1. 을의 의무사항","원문":"을은 중개대상물의 거래가 조속히 이루어지도록 성실히 노력하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별지 제14호서식·제15호서식 3. 유효기간","원문":"이 계약의 유효기간은 년 월 일까지로 한다. ※ 유효기간은 3개월을 원칙으로 하되, 갑과 을이 합의하여 별도로 정한 경우에는 그 기간에 따른다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별지 제14호서식·제15호서식 5. 을의 손해배상 책임","원문":"을이 다음의 행위를 한 경우에는 갑에게 그 손해를 배상하여야 한다. 1) 중개보수 또는 실비의 과다수령: 차액 환급 2) 중개대상물의 확인ㆍ설명을 소홀히 하여 재산상의 피해를 발생하게 한 경우: 손해액 배상"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별지 제14호서식·제15호서식 첨부서류","원문":"중개보수 요율표(「공인중개사법」 제32조제4항 및 같은 법 시행규칙 제20조에 따른 요율표를 수록합니다)"}],"선지":[{"번호":1,"판정":"옳음","설명":"중개보수 요율표는 두 서식 모두 첨부서류다."},{"번호":2,"판정":"옳음","설명":"계약의 유효기간(3개월 원칙)은 두 서식 모두 기재한다."},{"번호":3,"판정":"틀림","설명":"처리상황 통지의무는 전속중개계약서 1. 을의 의무사항에만 있다. 일반중개계약서에는 없다."},{"번호":4,"판정":"옳음","설명":"확인·설명 의무 협조와 확인·설명 소홀 시 손해배상(5. 2))이 두 서식에 모두 있다."},{"번호":5,"판정":"옳음","설명":"중개보수 과다 수령 시 차액 환급이 두 서식의 5. 1)에 모두 있다."}],"개념":[{"종류":"비교","제목":"일반중개계약서와 전속중개계약서","왼쪽":{"이름":"일반중개계약서(별지 제14호서식)","항목":["갑은 다른 개업공인중개사에게도 중개를 의뢰할 수 있음","을의 의무: 거래가 조속히 이루어지도록 성실히 노력","처리상황 통지·정보 공개 의무 없음","위약금 규정 없음"]},"오른쪽":{"이름":"전속중개계약서(별지 제15호서식)","항목":["을의 의무: 계약 후 2주일에 1회 이상 처리상황을 문서로 통지","계약 후 7일 이내 부동산거래정보망 또는 일간신문에 정보 공개(갑이 비공개를 요청하면 제외)","갑이 다른 개업공인중개사에게 의뢰하는 등 위반 시 중개보수에 해당하는 금액을 위약금으로 지급","확인·설명의무를 성실하게 이행"]}},{"종류":"표","제목":"두 서식의 공통 기재 사항","머리":["항목","내용"],"행":[["유효기간","3개월 원칙, 합의하면 그 기간"],["중개보수","거래가액의 몇 퍼센트 또는 얼마. 뒤쪽 별표 요율을 넘지 않음. 실비는 별도"],["을의 손해배상 책임","보수·실비 과다수령은 차액 환급. 확인·설명 소홀은 손해액 배상"],["확인·설명","갑은 확인·설명의무 이행에 협조"],["첨부서류","중개보수 요율표"]]}],"함정":"전속중개계약서에만 있는 의무(처리상황 통지, 정보 공개, 위약금)와 두 서식에 공통인 항목(유효기간, 중개보수, 손해배상, 요율표)을 구별한다. ③이 전속 서식에만 있는 의무라는 점이 쟁점이다."},"31회-2차-019":{"한줄":"금지행위인 직접거래는 중개의뢰인과 직접 거래하는 행위이므로, 다른 개업공인중개사가 중개한 임차는 금지행위에 해당하지 않는다.","근거":[{"법령":"공인중개사법","조문":"법 제33조제1항제6호","원문":"중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위"},{"법령":"공인중개사법","조문":"법 제33조제1항제2호","원문":"제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 영위하는 자인 사실을 알면서 그를 통하여 중개를 의뢰받거나 그에게 자기의 명의를 이용하게 하는 행위"},{"법령":"공인중개사법","조문":"법 제33조제1항제8호","원문":"부당한 이익을 얻거나 제3자에게 부당한 이익을 얻게 할 목적으로 거짓으로 거래가 완료된 것처럼 꾸미는 등 중개대상물의 시세에 부당한 영향을 주거나 줄 우려가 있는 행위"},{"법령":"공인중개사법","조문":"법 제33조제1항제9호","원문":"단체를 구성하여 특정 중개대상물에 대하여 중개를 제한하거나 단체 구성원 이외의 자와 공동중개를 제한하는 행위"}],"선지":[{"번호":1,"판정":"옳음","설명":"무등록 중개업자인 줄 알면서 그에게 중개를 의뢰받는 행위는 금지행위다(법 제33조제1항제2호)."},{"번호":2,"판정":"틀림","설명":"다른 개업공인중개사가 중개하므로 중개의뢰인과 직접 거래한 것이 아니다. 법 제33조제1항제6호의 직접거래에 해당하지 않는다."},{"번호":3,"판정":"옳음","설명":"중개의뢰인과 직접 거래를 하는 행위는 금지행위다(법 제33조제1항제6호)."},{"번호":4,"판정":"옳음","설명":"제3자에게 부당한 이익을 얻게 할 목적으로 거래가 완료된 것처럼 꾸며 시세에 부당한 영향을 주는 행위는 금지행위다(법 제33조제1항제8호)."},{"번호":5,"판정":"옳음","설명":"단체를 구성하여 단체 구성원 이외의 자와 공동중개를 제한하는 행위는 금지행위다(법 제33조제1항제9호)."}],"개념":[{"종류":"표","제목":"개업공인중개사등의 금지행위(법 제33조제1항)와 제재","머리":["호","금지행위","제재"],"행":[["1","중개대상물의 매매를 업으로 하는 행위","1년 이하 징역·1천만원 이하 벌금(법 제49조제1항제10호)"],["2","무등록 중개업자인 사실을 알면서 그에게 중개를 의뢰받거나 자기 명의를 이용하게 하는 행위","1년 이하 징역·1천만원 이하 벌금"],["3","보수·실비를 초과하여 금품을 받는 행위","1년 이하 징역·1천만원 이하 벌금"],["4","거래상 중요사항에 관하여 거짓된 언행으로 중개의뢰인의 판단을 그르치게 하는 행위","1년 이하 징역·1천만원 이하 벌금"],["5","관계 법령에서 양도·알선 등이 금지된 부동산의 분양·임대 등과 관련 있는 증서 등의 매매·교환 등을 중개하거나 매매를 업으로 하는 행위","3년 이하 징역·3천만원 이하 벌금(법 제48조제3호)"],["6","중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위","3년 이하 징역·3천만원 이하 벌금"],["7","탈세 등 관계 법령을 위반할 목적으로 미등기 부동산이나 전매 등이 제한된 부동산의 매매를 중개하는 등 투기를 조장하는 행위","3년 이하 징역·3천만원 이하 벌금"],["8","부당한 이익을 얻거나 제3자에게 얻게 할 목적으로 거짓으로 거래가 완료된 것처럼 꾸미는 등 시세에 부당한 영향을 주는 행위","3년 이하 징역·3천만원 이하 벌금"],["9","단체를 구성하여 특정 중개대상물에 대한 중개를 제한하거나 단체 구성원 이외의 자와 공동중개를 제한하는 행위","3년 이하 징역·3천만원 이하 벌금"]]},{"종류":"표","제목":"금지행위 위반의 행정처분","머리":["대상","처분","조문"],"행":[["개업공인중개사","등록취소 가능","법 제38조제2항제9호"],["소속공인중개사","자격정지 6월","법 제36조제1항제7호, 시행규칙 별표 3"]]}],"함정":"직접거래 금지는 중개의뢰인을 상대방으로 하는 거래를 막는 규정이다. 다른 개업공인중개사가 중개하는 거래는 중개의뢰인과 직접 거래한 것이 아니다. ①은 무등록 중개업자인 줄 알면서 의뢰받는 경우이고 ⑤는 공동중개 제한이라 모두 열거된 금지행위다."},"31회-2차-037":{"한줄":"매수신청대리 업무정지기간은 1월 이상 2년 이하인데 1월 이상 6월 이하라고 한 ⑤가 틀리다.","근거":[{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"규칙 제22조제3항","원문":"제1항 또는 제2항의 업무정지기간은 1월 이상 2년 이하로 한다."},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"규칙 제2조제3호","원문":"「민사집행법」 제114조의 규정에 따른 차순위매수신고"},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"규칙 제14조제3항","원문":"개업공인중개사는 제2조의 규정에 따른 대리행위를 함에 있어서 매각장소 또는 집행법원에 직접 출석하여야 한다."},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"규칙 제17조제5항","원문":"보수의 지급시기는 매수신청인과 매수신청대리인의 약정에 따르며, 약정이 없을 때에는 매각대금의 지급기한일로 한다."},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"규칙 제18조제4항제1호","원문":"중개사무소를 이전한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"매수신청대리의 위임을 받으면 민사집행법에 따른 차순위매수신고를 할 수 있다(규칙 제2조제3호)."},{"번호":2,"판정":"옳음","설명":"대리행위를 할 때는 매각장소 또는 집행법원에 직접 출석해야 한다(규칙 제14조제3항)."},{"번호":3,"판정":"옳음","설명":"보수 지급시기는 약정에 따르고 약정이 없으면 매각대금의 지급기한일이다(규칙 제17조제5항)."},{"번호":4,"판정":"옳음","설명":"중개사무소를 이전한 경우 그 날부터 10일 이내에 지방법원장에게 신고한다(규칙 제18조제4항제1호)."},{"번호":5,"판정":"틀림","설명":"업무정지기간은 1월 이상 2년 이하다(규칙 제22조제3항). 6월 이하가 아니다."}],"개념":[{"종류":"표","제목":"매수신청대리인의 의무와 신고(규칙 제14조·제17조·제18조)","머리":["구분","내용"],"행":[["대리행위 방식","각 대리행위마다 대리권 증명 문서 제출, 매각장소·집행법원에 직접 출석"],["보수 지급시기","약정에 따르고 약정이 없으면 매각대금의 지급기한일"],["신고 사유(10일 이내 지방법원장)","사무소 이전, 휴업·폐업, 자격 취소·정지, 개설등록 취소, 중개업무 정지, 분사무소 설치"],["금지행위","이중 등록신청, 사건 매수신청인으로서 매수신청, 이해관계가 다른 2인 이상의 대리, 명의대여, 허위기재 등"]]},{"종류":"표","제목":"업무정지(규칙 제22조)","머리":["구분","내용"],"행":[["제1항(해야 하는 경우)","휴업, 자격정지, 중개업무정지(법 제39조), 규칙 제21조제2항 일부 사유"],["제2항(명할 수 있는 경우)","민사집행법 제108조제1호~제3호 해당, 등록증 미게시, 사건카드·확인설명서·영수증의 서명날인 규정 위반, 사무소 이전 등 미신고, 법원 명칭·휘장 표시 등"],["정지 기간","1월 이상 2년 이하(제3항)"]]}],"함정":"업무정지기간의 상한은 개업공인중개사 업무정지(법 제39조, 6개월)와 다르다. 매수신청대리 업무정지는 2년까지 가능하다. 두 제도의 기간을 섞어 6월로 쓴 것이 ⑤다."},"31회-1차-041":{"한줄":"강제집행을 면할 목적의 허위 근저당 설정은 통정허위표시로 무효일 뿐 반사회질서 법률행위가 아니어서 3이 틀렸다.","근거":[{"법령":"민법","조문":"제103조","원문":"선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다."},{"법령":"민법","조문":"제108조","원문":"①상대방과 통정한 허위의 의사표시는 무효로 한다. ②전항의 의사표시의 무효는 선의의 제삼자에게 대항하지 못한다."},{"법령":"민법","조문":"제138조","원문":"무효인 법률행위가 다른 법률행위의 요건을 구비하고 당사자가 그 무효를 알았더라면 다른 법률행위를 하는 것을 의욕하였으리라고 인정될 때에는 다른 법률행위로서 효력을 가진다."},{"판례":"대법원 판례(허위 근저당)","요지":"강제집행을 면할 목적으로 허위의 근저당권을 설정한 행위는 허위표시로 무효이지만, 그것이 반사회질서 법률행위는 아니다."},{"판례":"대법원 판례(반사회적 동기)","요지":"법률행위의 동기가 반사회적이고 그 동기가 상대방에게 표시되거나 알려진 경우에는 그 법률행위가 무효다."},{"판례":"대법원 판례(증언의 대가)","요지":"소송에서 증언할 것을 조건으로 통상 용인되는 수준을 넘는 대가를 지급하기로 한 약정은 반사회질서 법률행위로 무효다."}],"선지":[{"번호":1,"판정":"옳음","설명":"불공정한 법률행위도 무효라서 무효행위 전환이 적용될 수 있다(제138조)."},{"번호":2,"판정":"옳음","설명":"경매에는 제104조가 적용되지 않는다."},{"번호":3,"판정":"틀림","설명":"허위 근저당 설정은 통정허위표시로 무효다(제108조제1항). 반사회질서가 아니다."},{"번호":4,"판정":"옳음","설명":"표시되거나 알려진 동기가 반사회적이면 법률행위가 무효다."},{"번호":5,"판정":"옳음","설명":"통상 용인되는 수준을 넘는 증언 대가 약정은 제103조로 무효다."}],"개념":[{"종류":"표","제목":"무효 법리 정리","머리":["법리","내용","조문"],"행":[["일부무효","일부가 무효면 전부 무효. 무효부분 없이도 했을 것이면 나머지는 유효","제137조"],["무효행위 전환","다른 법률행위의 요건을 갖추고 당사자가 그 의욕을 했으리라 인정되면 그 효력","제138조"],["무효행위 추인","추인해도 효력 없음. 무효임을 알고 추인하면 새로운 법률행위","제139조"],["허위표시","당사자 사이 무효, 선의 제3자에게 대항 불가","제108조"],["반사회질서","무효, 선의 제3자 보호 규정 없음","제103조"]]}],"함정":"강제집행 면탈 목적이라는 점이 불법적이라 반사회질서로 보기 쉽다. 판례는 허위표시 무효로만 처리하고 반사회질서로 보지 않는다."},"31회-1차-042":{"한줄":"변제 전 채무자는 가장양도된 채권의 양수인과 이해관계를 새로 맺은 자가 아니어서 제108조제2항의 제3자가 아니다.","근거":[{"법령":"민법","조문":"제108조제2항","원문":"전항의 의사표시의 무효는 선의의 제삼자에게 대항하지 못한다."},{"판례":"대법원 판례(통정허위표시의 제3자)","요지":"제3자는 허위표시의 당사자와 포괄승계인 외의 자로서 허위표시에 기초해 새로운 법률상 이해관계를 맺은 자다. 가장채권의 양수인·가압류채권자·가장전세권의 저당권자·파산관재인은 이에 해당한다."},{"판례":"대법원 판례(가장양도된 채권의 채무자)","요지":"채권이 가장양도된 경우 양도 전부터 채무를 지고 있던 채무자는 양도로 새 이해관계를 맺은 것이 아니므로 제3자에 해당하지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"가압류는 가장채권 자체를 기초로 한 이해관계 취득이어서 제3자에 해당한다."},{"번호":2,"판정":"옳음","설명":"가장 전세권 위에 저당권을 취득한 자는 허위표시에서 생긴 권리를 기초로 새 이해관계를 맺었다. 제3자에 해당한다."},{"번호":3,"판정":"틀림","설명":"변제 전 채무자는 원래부터 채무자였을 뿐 양도를 계기로 새 이해관계를 맺지 않았다. 제3자에 해당하지 않는다. 이 선지가 정답이다."},{"번호":4,"판정":"옳음","설명":"파산관재인은 파산채권자 전체의 이익을 위해 선임된 자로서 제3자에 해당한다."},{"번호":5,"판정":"옳음","설명":"가장채무의 보증인이 보증계약을 맺고 이행하여 구상권을 얻은 경우도 제3자로 본다."}],"개념":[{"종류":"표","제목":"통정허위표시와 제3자 해당 여부","머리":["구분","제3자 해당","근거 요지"],"행":[["가장채권 양수인","해당","허위표시 목적물에 새 이해관계"],["가장채권 압류·가압류채권자","해당","가장채권을 책임재산으로 파악"],["가장 저당권·전세권의 저당권자","해당","가장 권리 위에 권리 취득"],["파산관재인","해당","파산채권자 전체의 이익 대표"],["가장채무의 보증인","해당","보증계약으로 새 이해관계"],["변제 전 채무자","비해당","양도 전부터 채무자"],["단순 일반채권자","비해당","허위표시 목적물에 이해관계 없음"]]},{"종류":"비교","제목":"제108조제2항과 제107조제2항·제109조제2항","왼쪽":{"이름":"통정허위표시(제108조)","항목":["무효","제3자 보호: 선의면 족함(무과실 불요)"]},"오른쪽":{"이름":"비진의표시·착오·사기강박","항목":["제107조: 무효, 선의 제3자 보호","제109조: 취소, 선의 제3자 보호","제110조: 취소, 선의 제3자 보호"]}}],"함정":"'제3자'라는 낱말만 보고 채권 관계에 선 사람을 모두 보호 대상으로 고르기 쉽다. 허위표시를 기초로 새 이해관계를 맺었는지가 기준이고, 채무자는 지위가 전과 같아서 빠진다."},"31회-1차-043":{"한줄":"ㄱ(하자담보와 착오취소의 경합)과 ㄷ(상대방이 알고 이용한 착오)이 옳다.","근거":[{"법령":"민법","조문":"제109조제1항","원문":"의사표시는 법률행위의 내용의 중요부분에 착오가 있는 때에는 취소할 수 있다. 그러나 그 착오가 표의자의 중대한 과실로 인한 때에는 취소하지 못한다."},{"판례":"대법원 판례(착오와 하자담보책임)","요지":"매매 목적물에 하자가 있어 하자담보책임이 성립해도 착오 요건을 갖추었다면 매수인은 착오를 이유로 취소할 수 있다."},{"판례":"대법원 판례(해제 후 착오취소)","요지":"매도인이 매수인의 채무불이행을 이유로 계약을 적법하게 해제한 뒤에도 매수인은 착오를 이유로 계약을 취소할 수 있다."},{"판례":"대법원 판례(착오취소와 손해배상)","요지":"착오로 취소한 표의자는 경과실이면 상대방에게 불법행위 책임을 지지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ은 옳고 ㄴ은 틀려서 조합이 어긋난다."},{"번호":2,"판정":"옳음","설명":"ㄱ·ㄷ 모두 옳다."},{"번호":3,"판정":"틀림","설명":"ㄹ이 틀려서 조합이 어긋난다."},{"번호":4,"판정":"틀림","설명":"ㄴ·ㄷ 중 ㄴ이 틀리다."},{"번호":5,"판정":"틀림","설명":"ㄴ·ㄹ 모두 틀리다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"하자담보책임과 착오취소는 요건이 달라 경합한다. 매수인이 선택해 취소할 수 있다."},{"기호":"ㄴ","판정":"틀림","설명":"경과실로 착오에 빠진 표의자가 취소해도 불법행위 책임이 생기지 않는다."},{"기호":"ㄷ","판정":"옳음","설명":"상대방이 착오를 알고 이용했다면 표의자의 중과실은 취소를 막지 못한다."},{"기호":"ㄹ","판정":"틀림","설명":"적법한 해제 뒤에도 매수인은 착오를 이유로 취소할 수 있다."}],"개념":[{"종류":"표","제목":"착오취소 쟁점 모음","머리":["쟁점","결론","근거"],"행":[["취소 요건","내용의 중요부분 착오 + 표의자 무중대과실","제109조제1항"],["상대방이 착오를 알고 이용","중과실이어도 취소 가능","판례"],["하자담보책임과 경합","경합 인정, 취소 가능","판례"],["적법한 해제 후 취소","가능","판례"],["경과실 착오 취소자의 배상","불법행위 책임 없음","판례"],["제3자 보호","선의 제3자에게 대항 불가","제109조제2항"],["취소권 행사기간","추인할 수 있는 날부터 3년, 행위일부터 10년","제146조"]]}],"함정":"ㄴ에서 착오 취소를 하면 상대방에게 배상해야 한다고 생각하기 쉽다. 경과실 착오는 불법행위가 되지 않는다. ㄹ은 해제로 계약이 끝났으니 취소할 대상이 없다고 단정하기 쉬운데, 판례는 취소를 허용한다."},"31회-1차-044":{"한줄":"대리인이 대금을 수령하면 대금지급의무는 소멸한다.","근거":[{"법령":"민법","조문":"제114조제1항","원문":"대리인이 그 권한내에서 본인을 위한 것임을 표시한 의사표시는 직접 본인에게 대하여 효력이 생긴다."},{"법령":"민법","조문":"제116조제1항","원문":"의사표시의 효력이 의사의 흠결, 사기, 강박 또는 어느 사정을 알았거나 과실로 알지 못한 것으로 인하여 영향을 받을 경우에 그 사실의 유무는 대리인을 표준하여 결정한다."},{"법령":"민법","조문":"제120조","원문":"대리권이 법률행위에 의하여 부여된 경우에는 대리인은 본인의 승낙이 있거나 부득이한 사유있는 때가 아니면 복대리인을 선임하지 못한다."},{"법령":"민법","조문":"제117조","원문":"대리인은 행위능력자임을 요하지 아니한다."},{"판례":"대법원 판례(불공정한 법률행위와 대리)","요지":"경솔·무경험은 대리인을 기준으로, 궁박은 본인을 기준으로 판단한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"궁박은 본인 기준이다. 경솔·무경험만 대리인 기준이다."},{"번호":2,"판정":"틀림","설명":"승낙이나 부득이한 사유 없이 복대리인을 선임하지 못한다(제120조)."},{"번호":3,"판정":"옳음","설명":"매매 대리인에게는 대금 수령권이 있어 수령한 때 변제가 된다."},{"번호":4,"판정":"틀림","설명":"별도 수권이 없으면 해제권은 없다."},{"번호":5,"판정":"틀림","설명":"대리인은 행위능력자일 필요가 없어(제117조) 본인은 취소하지 못한다."}],"개념":[{"종류":"표","제목":"대리에서 누구를 기준으로 하는가","머리":["쟁점","기준","근거"],"행":[["의사의 흠결·사기·강박·악의·과실","대리인","제116조제1항"],["불공정행위의 경솔·무경험","대리인","판례"],["불공정행위의 궁박","본인","판례"],["대리인의 행위능력","불요","제117조"]]}],"함정":"1번이 가장 헷갈린다. 경솔·무경험과 궁박의 기준이 갈린다는 점을 잡아야 한다."},"31회-1차-045":{"한줄":"권한을 넘은 표현대리에서 기본대리권은 월권행위와 같은 종류일 필요가 없다.","근거":[{"법령":"민법","조문":"제126조","원문":"대리인이 그 권한외의 법률행위를 한 경우에 제삼자가 그 권한이 있다고 믿을 만한 정당한 이유가 있는 때에는 본인은 그 행위에 대하여 책임이 있다."},{"법령":"민법","조문":"제128조","원문":"법률행위에 의하여 수여된 대리권은 전조의 경우외에 그 원인된 법률관계의 종료에 의하여 소멸한다. 법률관계의 종료전에 본인이 수권행위를 철회한 경우에도 같다."},{"법령":"민법","조문":"제119조","원문":"대리인이 수인인 때에는 각자가 본인을 대리한다. 그러나 법률 또는 수권행위에 다른 정한 바가 있는 때에는 그러하지 아니하다."},{"판례":"대법원 판례(기본대리권)","요지":"권한을 넘은 표현대리의 기본대리권은 표현대리행위와 같은 종류일 필요가 없다."},{"판례":"대법원 판례(대리인의 사기)","요지":"대리인이 기망하여 체결한 계약은 본인이 몰랐어도 상대방이 사기를 이유로 취소할 수 있다. 대리인은 제110조제2항의 제3자가 아니다."}],"선지":[{"번호":1,"판정":"틀림","설명":"원인된 법률관계가 끝나기 전에도 본인은 수권행위를 철회할 수 있다(제128조 후단)."},{"번호":2,"판정":"옳음","설명":"기본대리권은 동종·유사할 필요가 없다는 것이 판례다."},{"번호":3,"판정":"틀림","설명":"복대리인은 본인의 대리인이다(제123조)."},{"번호":4,"판정":"틀림","설명":"수인의 대리인은 각자대리가 원칙이다(제119조)."},{"번호":5,"판정":"틀림","설명":"대리인은 상대방의 입장에서 제3자가 아니라 본인과 같이 보아 취소할 수 있다."}],"개념":[{"종류":"표","제목":"표현대리 요건","머리":["유형","요건","상대방"],"행":[["수권표시(제125조)","수권 표시 + 범위 내 행위","선의·무과실"],["권한초과(제126조)","기본대리권 + 정당한 이유","정당한 이유"],["소멸 후(제129조)","과거 대리권 + 소멸 후 행위","선의·무과실"]]},{"종류":"비교","제목":"각자대리와 공동대리","왼쪽":{"이름":"각자대리(원칙)","항목":["대리인 각자가 본인을 대리","제119조 본문"]},"오른쪽":{"이름":"공동대리(예외)","항목":["법률 또는 수권행위로 정함","제119조 단서"]}}],"함정":"기본대리권이 같은 종류여야 한다고 외운 사람이 있다. 판례는 종류를 묻지 않고 기본대리권의 존재만 요구한다."},"31회-1차-046":{"한줄":"ㄱ과 ㄴ이 옳다. 무권대리인이 본인을 단독상속하면 추인 거절은 신의칙에 반하고, 최고를 받은 본인이 기간 내 확답하지 않으면 추인을 거절한 것으로 본다.","근거":[{"법령":"민법","조문":"제130조","원문":"제130조(무권대리) 대리권없는 자가 타인의 대리인으로 한 계약은 본인이 이를 추인하지 아니하면 본인에 대하여 효력이 없다."},{"법령":"민법","조문":"제131조","원문":"제131조(상대방의 최고권) 대리권없는 자가 타인의 대리인으로 계약을 한 경우에 상대방은 상당한 기간을 정하여 본인에게 그 추인여부의 확답을 최고할 수 있다. 본인이 그 기간내에 확답을 발하지 아니한 때에는 추인을 거절한 것으로 본다."},{"판례":"대법원 판례(무권대리인의 본인 단독상속)","요지":"무권대리인이 본인을 단독상속한 경우 본인 지위에서 추인을 거절하는 것은 신의성실의 원칙에 반해 허용되지 않는다."},{"판례":"대법원 판례(유권대리 주장과 표현대리 주장)","요지":"유권대리 주장 속에는 표현대리 주장이 당연히 포함되지 않는다. 표현대리는 별개의 주장으로 당사자가 따로 해야 하고, 법원이 직권으로 판단할 수 없다."},{"판례":"대법원 판례(등기의 추정력과 입증책임)","요지":"등기에는 적법추정이 있으므로, 무권대리를 이유로 등기 말소를 청구하는 본인이 대리권 없음을 증명해야 한다. 등기명의자에게 대리권 증명책임을 지우지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ과 ㄴ이 모두 옳아 조합이 맞다."},{"번호":2,"판정":"틀림","설명":"ㄷ이 틀렸다. 유권대리 주장에 표현대리 주장은 포함되지 않는다."},{"번호":3,"판정":"틀림","설명":"ㄷ과 ㄹ이 틀렸다. 유권대리 주장에 표현대리 주장은 포함되지 않고, 말소를 청구하는 본인이 무권대리를 증명한다."},{"번호":4,"판정":"틀림","설명":"ㄹ이 틀려서 ㄴ까지 맞아도 ㄱ, ㄴ, ㄹ 조합은 성립하지 않는다."},{"번호":5,"판정":"틀림","설명":"ㄷ, ㄹ이 틀려 이 조합은 성립하지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"무권대리인이 본인을 단독상속하고도 추인을 거절하면 신의칙에 반한다(판례)."},{"기호":"ㄴ","판정":"옳음","설명":"본인이 최고 기간 내에 확답하지 않으면 추인을 거절한 것으로 본다(제131조)."},{"기호":"ㄷ","판정":"틀림","설명":"유권대리 주장은 표현대리 주장을 포함하지 않는다(판례). 표현대리는 따로 주장해야 한다."},{"기호":"ㄹ","판정":"틀림","설명":"등기의 추정력 때문에 말소를 청구하는 본인이 무권대리를 증명해야 한다(판례)."}],"개념":[{"종류":"표","제목":"무권대리에서 상대방·본인·무권대리인의 수단","머리":["구분","내용","조문"],"행":[["본인의 추인·거절","추인하면 계약 시로 소급해 유효, 추인하지 않으면 본인에게 효력 없음","제130조, 제133조"],["상대방의 최고권","상당한 기간을 정해 추인 여부 확답 최고, 확답 없으면 거절 간주","제131조"],["상대방의 철회권","본인이 추인하기 전까지 철회 가능, 계약 당시 대리권 없음을 안 상대방은 불가","제134조"],["추인·거절의 상대방","상대방에게 하지 않으면 상대방에게 대항 불가, 상대방이 안 때는 예외","제132조"],["무권대리인의 책임","상대방 선택에 따라 계약 이행 또는 손해배상, 상대방 악의·과실이나 무권대리인이 제한능력자면 면책","제135조"]]}],"함정":"ㄷ에서 유권대리를 주장하면 표현대리 주장도 한 것으로 보기 쉽다. 판례는 두 주장을 별개로 보므로 표현대리는 따로 주장해야 한다. ㄹ에서 등기명의자가 대리권을 증명해야 한다고 보기 쉽지만, 등기에 추정력이 있어 말소를 구하는 본인이 부담한다."},"31회-1차-050":{"한줄":"무권대리 처분행위를 본인이 추인하면 제133조에 따라 계약 시로 소급해 효력이 생긴다. 새로운 법률행위로 보는 것은 무효행위 추인(제139조)이다.","근거":[{"법령":"민법","조문":"제130조","원문":"제130조(무권대리) 대리권없는 자가 타인의 대리인으로 한 계약은 본인이 이를 추인하지 아니하면 본인에 대하여 효력이 없다."},{"법령":"민법","조문":"제133조","원문":"제133조(추인의 효력) 추인은 다른 의사표시가 없는 때에는 계약시에 소급하여 그 효력이 생긴다. 그러나 제삼자의 권리를 해하지 못한다."},{"법령":"민법","조문":"제139조","원문":"제139조(무효행위의 추인) 무효인 법률행위는 추인하여도 그 효력이 생기지 아니한다. 그러나 당사자가 그 무효임을 알고 추인한 때에는 새로운 법률행위로 본다."},{"법령":"민법","조문":"제214조","원문":"제214조(소유물방해제거, 방해예방청구권) 소유자는 소유권을 방해하는 자에 대하여 방해의 제거를 청구할 수 있고 소유권을 방해할 염려있는 행위를 하는 자에 대하여 그 예방이나 손해배상의 담보를 청구할 수 있다."},{"법령":"민법","조문":"제741조","원문":"제741조(부당이득의 내용) 법률상 원인없이 타인의 재산 또는 노무로 인하여 이익을 얻고 이로 인하여 타인에게 손해를 가한 자는 그 이익을 반환하여야 한다."},{"판례":"대법원 판례(무권리자·무권대리 처분행위의 추인)","요지":"권한 없는 자의 처분행위를 권리자가 추인하면 제133조 법리에 따라 처분 시로 소급해 효력이 생긴다."}],"선지":[{"번호":1,"판정":"옳음","설명":"乙에게 대리권이 없어 甲에게 효력이 없다(제130조). 乙과 丙의 공모로 대출계약도 효력이 없다."},{"번호":2,"판정":"옳음","설명":"설정계약이 甲에게 효력이 없으므로 그에 기한 근저당권설정등기는 원인 없는 무효 등기다."},{"번호":3,"판정":"옳음","설명":"甲은 소유자로서 무효 등기를 한 丙에게 방해제거를 청구할 수 있다(제214조)."},{"번호":4,"판정":"틀림","설명":"추인은 다른 의사표시가 없으면 계약 시에 소급해 효력이 생긴다(제133조). 새로운 법률행위로 보는 것은 당사자가 무효임을 알고 추인한 무효행위 추인이다(제139조)."},{"번호":5,"판정":"옳음","설명":"甲에게 갚을 채무가 없는데 변제했으므로 대출금을 받아 쓴 乙에게 부당이득 반환을 구할 수 있다(제741조). 채무 있다고 믿고 갚은 것이라 비채변제(제742조)가 아니다."}],"개념":[{"종류":"비교","제목":"추인의 효과 비교","왼쪽":{"이름":"무권대리 추인(제133조)","항목":["본인이 추인하면 계약 시로 소급해 유효","다른 의사표시가 있으면 그에 따름","제3자의 권리는 해하지 못함","무권리자의 처분행위 추인도 같은 법리"]},"오른쪽":{"이름":"무효행위 추인(제139조)","항목":["무효인 행위는 추인해도 유효가 되지 않음","무효임을 알고 추인하면 새로운 법률행위로 봄","추인한 때부터 효력, 소급하지 않음","통정허위표시, 불공정 행위 등"]}},{"종류":"표","제목":"추인 종류별 시점","머리":["종류","추인의 효과","조문"],"행":[["무권대리 추인","계약 시로 소급","제133조"],["무효행위 추인","추인 시부터 새 법률행위","제139조"],["취소할 수 있는 행위 추인","취소권 소멸, 확정적 유효","제143조"],["법정추인","추인한 것으로 간주","제145조"]]}],"함정":"위조된 계약이 무효라는 점에 끌려 추인하면 새로운 법률행위가 된다고 고르기 쉽다. 이 사안은 본인이 효력을 받아들이는 무권대리 추인이라 소급효가 있고, 제139조의 무효행위 추인과 구별해야 한다."},"31회-1차-048":{"한줄":"처음부터 허가를 잠탈할 목적으로 체결한 토지거래계약은 확정적 무효라 추인해도 유효가 되지 않는다.","근거":[{"법령":"민법","조문":"제130조","원문":"제130조(무권대리) 대리권없는 자가 타인의 대리인으로 한 계약은 본인이 이를 추인하지 아니하면 본인에 대하여 효력이 없다."},{"법령":"민법","조문":"제139조","원문":"제139조(무효행위의 추인) 무효인 법률행위는 추인하여도 그 효력이 생기지 아니한다. 그러나 당사자가 그 무효임을 알고 추인한 때에는 새로운 법률행위로 본다."},{"법령":"민법","조문":"제143조","원문":"제143조(추인의 방법, 효과)\n①취소할 수 있는 법률행위는 제140조에 규정한 자가 추인할 수 있고 추인후에는 취소하지 못한다.\n②전조의 규정은 전항의 경우에 준용한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제11조제6항","원문":"⑥ 제1항에 따른 허가를 받지 아니하고 체결한 토지거래계약은 그 효력이 발생하지 아니한다."},{"판례":"대법원 1991. 12. 24. 선고 90다12243 전원합의체 판결","요지":"허가를 잠탈할 목적으로 체결한 계약은 처음부터 확정적 무효이고, 이후 허가를 받아도 유효가 되지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"통정허위표시는 무효이나 당사자가 알고 추인하면 새로운 법률행위로 인정된다(제139조 단서)."},{"번호":2,"판정":"옳음","설명":"강박으로 체결한 계약은 취소할 수 있고 추인하면 확정적으로 유효가 된다(제110조, 제143조)."},{"번호":3,"판정":"옳음","설명":"무권대리 계약은 본인의 추인으로 계약 시로 소급해 유효가 된다(제130조, 제133조)."},{"번호":4,"판정":"옳음","설명":"미성년자가 단독으로 한 계약은 취소할 수 있고, 법정대리인이 추인할 수 있다(제143조, 제144조제2항)."},{"번호":5,"판정":"틀림","설명":"허가를 잠탈할 목적의 토지거래계약은 확정적 무효라 추인할 수 없다(판례)."}],"개념":[{"종류":"표","제목":"추인 가능성 정리","머리":["행위 유형","추인 가능 여부","효과","조문"],"행":[["취소할 수 있는 행위","가능","확정적 유효, 취소권 소멸","제143조"],["무효행위(허위표시 등)","알고 추인하면 가능","추인한 때부터 새 법률행위","제139조"],["무권대리 행위","본인이 추인 가능","계약 시로 소급","제130조, 제133조"],["유동적 무효(허가 전)","허가로 유효 가능","소급해 확정적 유효","거래신고법 제11조제6항"],["확정적 무효(허가 잠탈 목적)","불가","추인해도 무효","판례"]]}],"함정":"무효이거나 효력이 없는 행위는 모두 추인으로 살린다고 보기 쉽다. 확정적 무효는 추인으로 유효가 되지 않고, 허위표시는 추인하면 새 법률행위로서 효력이 생긴다."},"31회-1차-049":{"한줄":"상대방의 사기로 체결한 계약은 취소할 수 있다(제110조제1항). 나머지는 모두 무효 사유다.","근거":[{"법령":"민법","조문":"제110조","원문":"제110조(사기, 강박에 의한 의사표시)\n①사기나 강박에 의한 의사표시는 취소할 수 있다.\n②상대방있는 의사표시에 관하여 제삼자가 사기나 강박을 행한 경우에는 상대방이 그 사실을 알았거나 알 수 있었을 경우에 한하여 그 의사표시를 취소할 수 있다.\n③전2항의 의사표시의 취소는 선의의 제삼자에게 대항하지 못한다."},{"법령":"민법","조문":"제104조","원문":"제104조(불공정한 법률행위) 당사자의 궁박, 경솔 또는 무경험으로 인하여 현저하게 공정을 잃은 법률행위는 무효로 한다."},{"법령":"민법","조문":"제151조","원문":"제151조(불법조건, 기성조건)\n①조건이 선량한 풍속 기타 사회질서에 위반한 것인 때에는 그 법률행위는 무효로 한다.\n②조건이 법률행위의 당시 이미 성취한 것인 경우에는 그 조건이 정지조건이면 조건없는 법률행위로 하고 해제조건이면 그 법률행위는 무효로 한다.\n③조건이 법률행위의 당시에 이미 성취할 수 없는 것인 경우에는 그 조건이 해제조건이면 조건없는 법률행위로 하고 정지조건이면 그 법률행위는 무효로 한다."},{"법령":"민법","조문":"제535조","원문":"제535조(계약체결상의 과실)\n①목적이 불능한 계약을 체결할 때에 그 불능을 알았거나 알 수 있었을 자는 상대방이 그 계약의 유효를 믿었음으로 인하여 받은 손해를 배상하여야 한다. 그러나 그 배상액은 계약이 유효함으로 인하여 생길 이익액을 넘지 못한다.\n②전항의 규정은 상대방이 그 불능을 알았거나 알 수 있었을 경우에는 적용하지 아니한다."},{"판례":"대법원 판례(강박과 무효)","요지":"강박으로 의사결정의 자유가 완전히 박탈된 상태에서 한 행위는 취소가 아니라 무효다."}],"선지":[{"번호":1,"판정":"틀림","설명":"불공정한 법률행위는 취소가 아니라 무효다(제104조)."},{"번호":2,"판정":"틀림","설명":"불법조건이 붙은 법률행위는 무효다(제151조제1항)."},{"번호":3,"판정":"틀림","설명":"강행법규(효력규정)에 위반한 법률행위는 무효다."},{"번호":4,"판정":"옳음","설명":"사기에 의한 의사표시는 취소할 수 있다(제110조제1항)."},{"번호":5,"판정":"틀림","설명":"원시적·객관적 전부 불능인 계약은 무효이고 신뢰이익 배상 문제가 생긴다(제535조)."}],"개념":[{"종류":"표","제목":"사기·강박에 의한 의사표시(제110조)","머리":["상황","효과","조문"],"행":[["당사자의 사기·강박","취소할 수 있음","제110조제1항"],["제3자의 사기·강박","상대방이 알았거나 알 수 있었을 때만 취소","제110조제2항"],["취소와 제3자","선의의 제3자에게 대항 불가","제110조제3항"],["강박으로 의사결정의 자유 완전 박탈","무효","판례"]]}],"함정":"무효와 취소를 섞어 외우면 불공정 법률행위나 불법조건을 취소 사유로 고르게 된다. 취소 사유는 제한능력, 착오, 사기·강박이고 나머지는 무효다."},"31회-1차-047":{"한줄":"기한이익 상실특약은 특별한 사정이 없으면 정지조건부가 아니라 형성권적 특약으로 추정된다.","근거":[{"법령":"민법","조문":"제151조제3항","원문":"조건이 법률행위의 당시에 이미 성취할 수 없는 것인 경우에는 그 조건이 해제조건이면 조건없는 법률행위로 하고 정지조건이면 그 법률행위는 무효로 한다."},{"법령":"민법","조문":"제151조제2항","원문":"조건이 법률행위의 당시 이미 성취한 것인 경우에는 그 조건이 정지조건이면 조건없는 법률행위로 하고 해제조건이면 그 법률행위는 무효로 한다."},{"법령":"민법","조문":"제152조제2항","원문":"종기있는 법률행위는 기한이 도래한 때로부터 그 효력을 잃는다."},{"판례":"대법원 판례(조건의 존재 증명)","요지":"법률행위에 조건이 붙어 있다는 사실은 그 조건의 존재를 주장하는 자가 증명해야 한다."},{"판례":"대법원 판례(기한이익 상실특약)","요지":"기한이익 상실특약은 특별한 사정이 없으면 채권자의 청구가 있어야 상실하는 형성권적 특약으로 추정한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"불능조건이 정지조건이면 무효다(제151조제3항)."},{"번호":2,"판정":"옳음","설명":"기성조건이 해제조건이면 무효다(제151조제2항)."},{"번호":3,"판정":"옳음","설명":"조건의 존재를 주장하는 자가 증명한다."},{"번호":4,"판정":"틀림","설명":"형성권적 기한이익 상실특약으로 추정한다. 정지조건부로 추정하지 않는다. 이 선지가 정답이다."},{"번호":5,"판정":"옳음","설명":"종기 있는 법률행위는 기한이 도래한 때부터 효력을 잃는다(제152조제2항)."}],"개념":[{"종류":"표","제목":"조건·기한 증명책임과 특약 추정","머리":["쟁점","결론","근거"],"행":[["조건이 붙어 있다는 사실","조건의 존재를 주장하는 자가 증명","판례"],["정지조건의 성취","권리 취득을 주장하는 자가 증명","판례"],["해제조건의 성취","권리 소멸을 주장하는 자가 증명","판례"],["기한이익 상실특약","형성권적 특약으로 추정","판례"],["시기 도래","도래한 때부터 효력 발생","제152조제1항"],["종기 도래","도래한 때부터 효력 상실","제152조제2항"]]}],"함정":"선지 1·2에서 기성-해제 무효, 불능-정지 무효를 놓치면 옳은 선지를 틀린 것으로 고르게 된다. 정답 선지 4는 정지조건부로 읽는 순간 틀리고, 청구가 있어야 상실한다는 형성권적 특약으로 외운다."},"31회-1차-053":{"한줄":"미등기 건물을 매수해 대금을 지급하고 점유하는 자는 사실상 처분권을 가지므로 건물 철거 청구의 상대방이 된다.","근거":[{"법령":"민법","조문":"제214조","원문":"소유자는 소유권을 방해하는 자에 대하여 방해의 제거를 청구할 수 있고 소유권을 방해할 염려있는 행위를 하는 자에 대하여 그 예방이나 손해배상의 담보를 청구할 수 있다."},{"법령":"민법","조문":"제356조","원문":"저당권자는 채무자 또는 제삼자가 점유를 이전하지 아니하고 채무의 담보로 제공한 부동산에 대하여 다른 채권자보다 자기채권의 우선변제를 받을 권리가 있다."},{"법령":"민법","조문":"제370조","원문":"제214조, 제321조, 제333조, 제340조, 제341조 및 제342조의 규정은 저당권에 준용한다."},{"법령":"민법","조문":"제162조제2항","원문":"채권 및 소유권 이외의 재산권은 20년간 행사하지 아니하면 소멸시효가 완성한다."},{"판례":"대법원 판례(미등기 건물 매수인과 철거)","요지":"타인 토지에 무단 신축된 미등기 건물을 매수하고 대금을 지급해 점유하는 자는 사실상 처분권을 가지므로 철거 청구의 상대방이 된다."},{"판례":"대법원 판례(저당권자의 반환 청구)","요지":"저당권은 점유를 이전하지 않는 권리이므로 목적물에서 분리·반출된 물건은 저당권자가 자신에게 인도하라고 청구할 수 없고 원래 있던 장소로 반환하라고 청구할 수 있다."},{"판례":"대법원 판례(전보배상 부정)","요지":"소유자가 말소등기의무자에 의해 소유권을 잃어 말소를 구할 수 없게 되어도, 물권적 청구권의 이행불능을 이유로 한 전보배상청구권은 생기지 않는다."},{"판례":"대법원 판례(허무인 명의 등기)","요지":"허무인 명의로 등기한 행위자를 상대로 소유자가 등기 말소를 구할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"소유권에 기한 물권적 청구권은 소멸시효에 걸리지 않는다(제162조제2항)."},{"번호":2,"판정":"옳음","설명":"사실상 처분권을 가진 매수·점유자는 철거 청구의 상대방이다."},{"번호":3,"판정":"틀림","설명":"허무인 명의 등기를 한 행위자를 상대로 소유자는 말소를 구할 수 있다."},{"번호":4,"판정":"틀림","설명":"저당권자는 분리·반출물을 자신에게 인도하라고 청구하지 못한다. 원래 장소로 반환을 구한다(제356조, 제370조)."},{"번호":5,"판정":"틀림","설명":"물권적 청구권이 소멸한 경우 이행불능에 의한 전보배상청구권은 생기지 않는다."}],"개념":[{"종류":"표","제목":"권리자별 물권적 청구권","머리":["권리자","청구 가능","특징"],"행":[["소유자","반환·방해제거·방해예방","제213조·제214조"],["지상권자·전세권자","같음","제290조·제319조 준용"],["저당권자","방해제거·방해예방","제370조, 반환청구는 점유 이전 없어 원래 장소로"],["점유자","점유회수·보유·보전","제204조~제206조, 1년 제한"],["미등기 건물 매수·점유자","철거 청구의 상대방","처분권 근거"],["소유권 상실한 자","물권적 청구권 소멸","전보배상 부정"]]}],"함정":"소유권에 기한 청구권도 채권처럼 10년 시효에 걸린다는 오해로 선지 1을 옳다고 본다. 선지 4는 저당권자에게 점유권이 없다는 점에서 자신에게 인도하라는 청구가 막힌다. 선지 5는 책임을 물을 길이 열려 있어야 한다는 직관 때문에 옳아 보이지만 판례는 부정한다."},"31회-1차-051":{"한줄":"이행판결로는 확정만으로 물권이 변동하지 않고 등기해야 하므로 확정판결 때 변동한다는 2번이 틀렸다.","근거":[{"법령":"민법","조문":"제187조","원문":"상속, 공용징수, 판결, 경매 기타 법률의 규정에 의한 부동산에 관한 물권의 취득은 등기를 요하지 아니한다. 그러나 등기를 하지 아니하면 이를 처분하지 못한다."},{"법령":"민사집행법","조문":"제135조","원문":"매수인은 매각대금을 다 낸 때에 매각의 목적인 권리를 취득한다."},{"판례":"대법원 판례","요지":"제187조의 판결은 형성판결이며 이행판결에 기한 물권변동은 등기를 해야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"관습상 법정지상권은 법률 규정에 의한 취득으로 설정등기가 필요 없다(제187조)."},{"번호":2,"판정":"틀림","설명":"이행판결에 기한 물권변동은 판결 확정 때가 아니라 등기 때다."},{"번호":3,"판정":"옳음","설명":"상속인은 상속 개시 때 등기 없이 소유권을 취득한다(제187조)."},{"번호":4,"판정":"옳음","설명":"경매의 매수인은 매각대금을 다 낸 때 권리를 취득한다(민사집행법 제135조)."},{"번호":5,"판정":"옳음","설명":"건물 신축자는 보존등기 없이 소유권을 원시취득한다."}],"개념":[{"종류":"표","제목":"제187조 판결 해당 여부","머리":["판결·조서","등기 없이 취득"],"행":[["공유물분할 판결(형성판결)","○"],["이행판결(이전등기 명령)","×"],["확인판결","×"],["화해조서·인낙조서","×"]]}],"함정":"판결이면 확정 때 효력이 생긴다고 읽기 쉽다. 판결의 종류가 형성판결인지가 갈림길이다."},"31회-1차-052":{"한줄":"중간생략 합의가 없으면 乙의 이전등기청구권 양도에는 甲의 동의가 필요하다는 것이 판례라서 5번이 틀렸다.","근거":[{"법령":"민법","조문":"제449조제1항","원문":"채권은 양도할 수 있다. 그러나 채권의 성질이 양도를 허용하지 아니하는 때에는 그러하지 아니하다."},{"판례":"대법원 판례","요지":"부동산 매수인의 소유권이전등기청구권은 그 양도에 채무자인 매도인의 동의나 승낙이 필요하다."},{"판례":"대법원 판례","요지":"3자 합의가 있으면 최종 매수인은 최초 매도인에게 직접 이전등기를 청구할 수 있다. 중간 매수인의 청구권은 소멸하지 않고, 최초 매도인의 대금채권 행사도 제한되지 않는다."},{"판례":"대법원 판례","요지":"토지거래허가구역에서는 중간생략 합의가 있어도 최종 매수인이 최초 매도인에게 허가신청절차 협력을 직접 구할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"3자 합의가 있으면 丙이 甲에게 직접 청구할 수 있다."},{"번호":2,"판정":"옳음","설명":"합의가 있어도 乙의 甲에 대한 청구권은 소멸하지 않는다."},{"번호":3,"판정":"옳음","설명":"甲의 乙에 대한 대금채권 행사는 제한되지 않는다."},{"번호":4,"판정":"옳음","설명":"허가구역에서는 丙이 직접 甲에게 허가신청 협력을 구할 수 없다."},{"번호":5,"판정":"틀림","설명":"합의가 없으면 乙의 등기청구권 양도는 채권양도로서 甲의 동의가 있어야 효력이 생긴다(제449조제1항)."}],"개념":[{"종류":"흐름","제목":"甲→乙→丙 순차 매매","단계":[{"이름":"1","설명":"甲→乙, 乙→丙 매매 성립"},{"이름":"2","설명":"3자 합의 있으면 丙이 甲에게 직접 청구"},{"이름":"3","설명":"합의 없으면 乙 청구권 양도에 甲 동의 필요"},{"이름":"4","설명":"토지거래허가구역이면 허가는 당사자별로 따로"}]},{"종류":"표","제목":"중간생략 합의 유무","머리":["구분","합의 있음","합의 없음"],"행":[["丙의 직접 청구","가능","원칙 불가"],["乙의 청구권","소멸 안 함","그대로"],["甲의 대금채권","제한 없음","제한 없음"],["청구권 양도","불필요","甲 동의 필요"]]}],"함정":"합의가 없어도 양수인이 직접 청구할 수 있다고 읽기 쉽다. 매도인 동의가 있어야 한다."},"31회-1차-055":{"한줄":"등기의 추정력은 권리변동의 당사자 사이에서도 원용할 수 있으므로 1번이 틀렸다.","근거":[{"법령":"민법","조문":"제198조","원문":"전후양시에 점유한 사실이 있는 때에는 그 점유는 계속한 것으로 추정한다."},{"법령":"민법","조문":"제200조","원문":"점유자가 점유물에 대하여 행사하는 권리는 적법하게 보유한 것으로 추정한다."},{"판례":"대법원 판례","요지":"등기의 추정력은 등기부상 권리변동의 당사자 사이에서도 인정된다. 원인 없이 부적법하게 말소된 경우에는 권리소멸 추정이 생기지 않는다."},{"판례":"대법원 판례","요지":"부동산 물권에는 등기의 추정력이 적용되므로 점유의 권리추정 규정은 특별한 사정이 없으면 적용되지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"당사자 사이에서도 추정력은 원용할 수 있다."},{"번호":2,"판정":"옳음","설명":"전후 양시에 점유한 사실이 있으면 점유는 계속한 것으로 추정한다(제198조)."},{"번호":3,"판정":"옳음","설명":"부적법하게 말소된 등기에는 권리소멸 추정력이 없다."},{"번호":4,"판정":"옳음","설명":"부동산 물권은 등기가 권리를 추정하므로 점유의 권리추정(제200조)은 적용되지 않는다."},{"번호":5,"판정":"옳음","설명":"등기원인으로 주장된 계약서가 진정하지 않다고 증명되면 적법 추정은 깨진다."}],"개념":[{"종류":"표","제목":"추정 규정","머리":["내용","근거"],"행":[["소유의 의사·선의·평온·공연","제197조제1항"],["점유 계속","제198조"],["점유 권리의 적법","제200조(부동산 물권 제외)"],["등기 권리 적법","판례"],["점유 승계","제199조"]]}],"함정":"추정력은 제3자에게만 쓸 수 있다고 생각하기 쉽다. 당사자 사이에도 원용된다."},"31회-1차-054":{"한줄":"무효인 매매의 매수인이 필요비를 지출한 뒤 매도인이 목적물을 제3자에게 양도하면 매수인은 양수인에게 비용상환을 청구할 수 있다.","근거":[{"법령":"민법","조문":"제203조","원문":"① 점유자가 점유물을 반환할 때에는 회복자에 대하여 점유물을 보존하기 위하여 지출한 금액 기타 필요비의 상환을 청구할 수 있다. 그러나 점유자가 과실을 취득한 경우에는 통상의 필요비는 청구하지 못한다.\n② 점유자가 점유물을 개량하기 위하여 지출한 금액 기타 유익비에 관하여는 그 가액의 증가가 현존한 경우에 한하여 회복자의 선택에 좇아 그 지출금액이나 증가액의 상환을 청구할 수 있다."},{"법령":"민법","조문":"제202조","원문":"점유물이 점유자의 책임있는 사유로 인하여 멸실 또는 훼손한 때에는 악의의 점유자는 그 손해의 전부를 배상하여야 하며 선의의 점유자는 이익이 현존하는 한도에서 배상하여야 한다. 소유의 의사가 없는 점유자는 선의인 경우에도 손해의 전부를 배상하여야 한다."},{"법령":"민법","조문":"제548조제1항","원문":"당사자 일방이 계약을 해제한 때에는 각 당사자는 그 상대방에 대하여 원상회복의 의무가 있다. 그러나 제삼자의 권리를 해하지 못한다."},{"판례":"대법원 판례","요지":"계약 해제로 원상회복을 하는 매수인에게는 선의 점유자의 과실취득권 규정이 적용되지 않는다. 점유자가 비용을 지출한 뒤 소유자가 바뀌면 점유자는 현재의 회복자인 양수인에게 상환을 청구할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"과실을 취득한 점유자는 통상의 필요비를 청구하지 못한다(제203조제1항 단서)."},{"번호":2,"판정":"틀림","설명":"해제에 따른 원상회복에서 매수인은 수취한 과실도 반환해야 한다(제548조제1항). 선의 점유자의 과실취득권은 적용되지 않는다."},{"번호":3,"판정":"틀림","설명":"악의의 점유자는 손해의 전부를 배상한다. 현존이익 한도는 선의 점유자 몫이다(제202조)."},{"번호":4,"판정":"틀림","설명":"유익비는 지출금액이나 증가액 중 회복자의 선택에 따라 상환한다(제203조제2항)."},{"번호":5,"판정":"옳음","설명":"비용상환 청구는 점유물을 반환할 때의 회복자에게 할 수 있어 양수인에게도 청구할 수 있다."}],"개념":[{"종류":"표","제목":"점유자와 회복자","머리":["구분","선의 점유자","악의 점유자"],"행":[["과실","취득","반환·대가 보상(제201조제2항)"],["멸실·훼손","이익 현존 한도","손해 전부(제202조)"],["필요비","과실 취득 시 통상 필요비 제외","청구 가능"],["유익비","회복자가 지출액·증가액 중 선택","동일"]]}],"함정":"선의 점유자의 과실취득을 해제 사안에도 그대로 적용하기 쉽다. 해제에서는 원상회복으로 과실도 돌려준다."},"31회-1차-056":{"한줄":"공유자는 단독으로 자기 지분에 관한 제3자의 취득시효를 중단시킬 수 있다.","근거":[{"법령":"민법","조문":"제263조","원문":"공유자는 그 지분을 처분할 수 있고 공유물 전부를 지분의 비율로 사용, 수익할 수 있다."},{"법령":"민법","조문":"제264조","원문":"공유자는 다른 공유자의 동의없이 공유물을 처분하거나 변경하지 못한다."},{"법령":"민법","조문":"제247조제2항","원문":"②소멸시효의 중단에 관한 규정은 전2조의 소유권취득기간에 준용한다."},{"법령":"민법","조문":"제267조","원문":"공유자가 그 지분을 포기하거나 상속인없이 사망한 때에는 그 지분은 다른 공유자에게 각 지분의 비율로 귀속한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"공유자는 자기 지분에 대해 처분권을 가지므로(제263조) 단독으로 자기 지분의 취득시효를 중단시킬 수 있다(제247조제2항)."},{"번호":2,"판정":"옳음","설명":"나대지에 건물을 신축하는 것은 공유물의 변경이어서(제264조) 과반수로도 못한다. 관리방법으로 부적법하다."},{"번호":3,"판정":"옳음","설명":"부동산 공유지분의 포기는 등기해야 효력이 생긴다(제186조)."},{"번호":4,"판정":"옳음","설명":"갑은 소수지분권자라 단독 임대의 권한이 없어 임차인 정은 사용·수익이 부당하다. 을은 정에게 부당이득 반환을 청구할 수 있다(판례)."},{"번호":5,"판정":"옳음","설명":"소수지분권자는 다른 소수지분권자를 상대로 보존행위로서 인도를 청구하지 못한다(2018다287522 전원합의체)."}],"개념":[{"종류":"흐름","제목":"공유지분 포기의 효과","단계":[{"이름":"의사표시","설명":"공유자가 지분 포기"},{"이름":"등기","설명":"부동산은 등기해야 포기에 따른 물권변동이 생김(제186조)"},{"이름":"귀속","설명":"포기된 지분은 다른 공유자에게 각 지분 비율로 귀속(제267조)"}]},{"종류":"표","제목":"공유자 1인이 할 수 있는 행위","머리":["행위","가능 여부","근거"],"행":[["자기 지분 처분","가능","제263조"],["자기 지분의 시효 중단","가능","제247조제2항"],["공유물 전부 처분·변경","동의 없으면 불가","제264조"],["보존행위","각자 가능","제265조 단서"],["다른 소수지분권자에게 인도 청구","불가, 방해금지·배제만","판례"]]}],"함정":"1번은 공유자 1인이 아무것도 못 한다는 식으로 읽기 쉽다. 자기 지분에 대한 시효 중단은 단독으로 할 수 있다. 5번은 보존행위를 근거로 인도까지 구할 수 있는 것처럼 보이나 판례가 막았다."},"31회-1차-057":{"한줄":"취득시효 완성 후 등기 전에 원소유자가 설정한 저당권의 피담보채무를 시효취득자가 변제해도 원소유자에게 부당이득 반환을 청구할 수 없다.","근거":[{"법령":"민법","조문":"제245조","원문":"①20년간 소유의 의사로 평온, 공연하게 부동산을 점유하는 자는 등기함으로써 그 소유권을 취득한다.\n②부동산의 소유자로 등기한 자가 10년간 소유의 의사로 평온, 공연하게 선의이며 과실없이 그 부동산을 점유한 때에는 소유권을 취득한다."},{"법령":"민법","조문":"제247조제1항","원문":"①전2조의 규정에 의한 소유권취득의 효력은 점유를 개시한 때에 소급한다."},{"판례":"대법원 판례(시효완성 후 소유자 변경)","요지":"시효완성 후 등기 전에 제3자가 소유권이전등기를 마치면 시효완성자는 그 제3자에게 시효완성을 주장하지 못한다. 명의신탁 해지로 명의신탁자에게 등기가 넘어간 경우도 같다."}],"선지":[{"번호":1,"판정":"옳음","설명":"국유재산 중 일반재산은 취득시효의 대상이 된다."},{"번호":2,"판정":"옳음","설명":"중복등기로 무효인 소유권보존등기에 기한 등기부취득시효(제245조제2항)는 인정되지 않는다(판례)."},{"번호":3,"판정":"옳음","설명":"시효완성으로 인한 소유권이전등기청구권은 채권으로서 원소유자의 동의 없이 양도할 수 있다(판례)."},{"번호":4,"판정":"틀림","설명":"판례는 시효취득자의 피담보채무 변제를 이유로 한 원소유자에 대한 부당이득 반환청구를 인정하지 않는다."},{"번호":5,"판정":"옳음","설명":"시효완성 후 새 소유자가 된 명의신탁자에게는 시효완성을 주장하지 못한다(판례)."}],"개념":[{"종류":"표","제목":"취득시효 쟁점별 결론","머리":["쟁점","결론","근거"],"행":[["국유 일반재산","취득시효 대상","판례"],["중복등기로 무효인 보존등기","등기부취득시효 부정","판례"],["시효완성에 따른 이전등기청구권","원소유자 동의 없이 양도 가능","판례"],["시효완성 후 등기 전 소유자 변경","새 소유자에게 시효완성 주장 불가","판례"],["부동산 점유취득시효 기간","20년, 등기해야 취득","제245조제1항"],["등기부취득시효","등기한 선의·무과실 10년","제245조제2항"]]}],"함정":"4번은 변제한 사람이 구상권을 갖는 것처럼 보여 맞게 읽기 쉽다. 판례는 부당이득 반환청구를 부정한다. 1번에서 국유재산 전체를 시효취득할 수 없다고 외우는 오해도 있다. 행정재산만 대상에서 빠진다."},"31회-1차-058":{"한줄":"ㄴ(갱신청구권)과 ㄹ(무상 담보지상권자의 손해배상 불가)이 옳다.","근거":[{"법령":"민법","조문":"제279조","원문":"지상권자는 타인의 토지에 건물 기타 공작물이나 수목을 소유하기 위하여 그 토지를 사용하는 권리가 있다."},{"법령":"민법","조문":"제283조제1항","원문":"지상권이 소멸한 경우에 건물 기타 공작물이나 수목이 현존한 때에는 지상권자는 계약의 갱신을 청구할 수 있다."},{"법령":"민법","조문":"제287조","원문":"지상권자가 2년 이상의 지료를 지급하지 아니한 때에는 지상권설정자는 지상권의 소멸을 청구할 수 있다."},{"판례":"대법원 판례(무상 담보지상권)","요지":"채권 담보를 위해 저당권과 함께 설정한 무상의 담보지상권자는 특별한 사정이 없으면 제3자의 토지 불법점유로 인한 임료 상당 손해배상을 청구할 수 없다."},{"판례":"대법원 판례(토지 양도와 지료 연체)","요지":"지료 연체가 토지 양도 전후에 걸친 경우 양수인에 대한 연체기간이 2년에 이르러야 소멸청구가 가능하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄴ은 옳으나 ㄹ도 옳아 ㄴ만으로는 부족하다."},{"번호":2,"판정":"틀림","설명":"ㄱ·ㄷ이 모두 틀리다."},{"번호":3,"판정":"옳음","설명":"ㄴ·ㄹ이 옳다."},{"번호":4,"판정":"틀림","설명":"ㄷ이 틀리다."},{"번호":5,"판정":"틀림","설명":"ㄱ·ㄷ이 틀리다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"지료는 지상권의 성립요소가 아니다. 무상 지상권도 성립한다."},{"기호":"ㄴ","판정":"옳음","설명":"지상권이 소멸하고 건물이 현존하면 갱신을 청구할 수 있다(제283조제1항)."},{"기호":"ㄷ","판정":"틀림","설명":"양수인에 대한 연체가 2년에 이르러야 한다."},{"기호":"ㄹ","판정":"옳음","설명":"무상 담보지상권자는 특별한 사정이 없으면 제3자의 불법점유에 대한 임료 상당 손해배상을 청구할 수 없다."}],"개념":[{"종류":"표","제목":"지상권의 성립과 소멸","머리":["쟁점","내용","근거"],"행":[["성립 요소","지료는 요소가 아님(무상 지상권 가능)","제279조"],["갱신청구","소멸 시 건물 등이 현존하면 지상권자가 갱신 청구","제283조제1항"],["매수청구","설정자가 갱신을 원하지 않으면 지상권자가 매수 청구","제283조제2항"],["지료 연체","2년 이상 시 소멸청구, 양도 시 양수인에 대한 연체가 2년","제287조, 판례"],["담보지상권","무상, 피담보채권 소멸 시 함께 소멸","판례"]]}],"함정":"토지가 양도되었으니 연체액을 합산할 수 있다고 보기 쉽다. 양수인에 대한 연체가 2년이어야 한다. 지료는 지상권의 성립요소라고 단정하는 것도 틀리다."},"31회-1차-059":{"한줄":"요역지 소유권이 양도되면 지역권도 원칙적으로 함께 이전된다.","근거":[{"법령":"민법","조문":"제292조제1항","원문":"지역권은 요역지소유권에 부종하여 이전하며 또는 요역지에 대한 소유권이외의 권리의 목적이 된다. 그러나 다른 약정이 있는 때에는 그 약정에 의한다."},{"법령":"민법","조문":"제295조","원문":"①공유자의 1인이 지역권을 취득한 때에는 다른 공유자도 이를 취득한다. ②점유로 인한 지역권취득기간의 중단은 지역권을 행사하는 모든 공유자에 대한 사유가 아니면 그 효력이 없다."},{"법령":"민법","조문":"제219조제2항","원문":"전항의 통행권자는 통행지소유자의 손해를 보상하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"지역권은 요역지 소유권에 부종하여 이전된다(제292조제1항)."},{"번호":2,"판정":"옳음","설명":"제295조제1항."},{"번호":3,"판정":"옳음","설명":"제295조제2항."},{"번호":4,"판정":"옳음","설명":"통행지역권을 주장하는 쪽이 요역지 존재를 증명해야 한다(판례)."},{"번호":5,"판정":"옳음","설명":"시효취득한 통행지역권도 승역지 소유자의 손해를 보상해야 한다(제219조제2항 유추)."}],"개념":[{"종류":"표","제목":"지역권의 부종성·불가분성","머리":["성질","내용","근거"],"행":[["이전","요역지 소유권과 함께 이전, 다른 약정이 있으면 그에 따름","제292조제1항"],["분리 처분 금지","요역지와 분리 양도·담보 불가","제292조제2항"],["취득의 불가분","공유자 1인 취득 시 다른 공유자도 취득","제295조제1항"],["취득시효 중단","행사하는 모든 공유자에 대한 사유여야 효력","제295조제2항"],["소멸시효 중단·정지","1인의 사유가 다른 공유자에게도 효력","제296조"]]}],"함정":"요역지가 팔려도 지역권은 별개 권리여서 남는다고 생각하기 쉽다. 요역지 소유권에 따라 함께 이전된다."},"31회-1차-060":{"한줄":"전세권 존속기간이 시작되기 전에 마쳐진 설정등기도 특별한 사정이 없으면 유효한 것으로 추정한다. 5번이 틀렸다.","근거":[{"법령":"민법","조문":"제312조제1항","원문":"전세권의 존속기간은 10년을 넘지 못한다. 당사자의 약정기간이 10년을 넘는 때에는 이를 10년으로 단축한다."},{"법령":"민법","조문":"제304조제1항","원문":"타인의 토지에 있는 건물에 전세권을 설정한 때에는 전세권의 효력은 그 건물의 소유를 목적으로 한 지상권 또는 임차권에 미친다."},{"판례":"대법원 판례(기간 시작 전 등기)","요지":"존속기간이 시작되기 전에 마쳐진 용익권 설정등기도 특별한 사정이 없으면 유효한 것으로 추정한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"약정기간이 10년을 넘으면 10년으로 단축된다(제312조제1항)."},{"번호":2,"판정":"옳음","설명":"전세금은 기존 채권으로 갈음할 수 있다(판례)."},{"번호":3,"판정":"옳음","설명":"건물 전세권의 효력은 그 건물 소유를 목적으로 한 지상권에 미친다(제304조제1항)."},{"번호":4,"판정":"옳음","설명":"법정갱신은 법률 규정에 의한 물권변동이라 등기 없이 갱신된 전세권을 주장할 수 있다(제312조제4항, 제187조)."},{"번호":5,"판정":"틀림","설명":"기간 시작 전에 마쳐진 설정등기는 특별한 사정이 없으면 유효로 추정한다(판례)."}],"개념":[{"종류":"표","제목":"전세권 소멸·기간 정리","머리":["쟁점","내용"],"행":[["약정기간 15년","10년으로 단축"],["건물 전세 1년 미만 약정","1년으로"],["법정갱신","등기 없이 제3자에게 대항"],["건물 전세권의 지상권 효력","건물 소유를 목적으로 한 지상권·임차권에 미침(제304조제1항)"],["기간 시작 전 설정등기","특별한 사정이 없으면 유효 추정"]]}],"함정":"5번을 무효 추정으로 읽으면 틀린다. 등기가 효력 발생 시점보다 앞섰다는 이유만으로 무효로 보지 않는다."},"31회-1차-061":{"한줄":"유치권에는 부종성·수반성·불가분성이 있고 물상대위성은 없다.","근거":[{"법령":"민법","조문":"제321조","원문":"유치권자는 채권전부의 변제를 받을 때까지 유치물전부에 대하여 그 권리를 행사할 수 있다."},{"법령":"민법","조문":"제328조","원문":"유치권은 점유의 상실로 인하여 소멸한다."},{"판례":"통설(물상대위성 부정)","요지":"유치권은 우선변제권이 없고 유치적 효력만 있어 물상대위성이 인정되지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ(불가분성)이 빠진 조합이다."},{"번호":2,"판정":"틀림","설명":"물상대위성(ㄹ)은 유치권에 없다."},{"번호":3,"판정":"틀림","설명":"물상대위성(ㄹ)은 유치권에 없고 부종성·수반성이 빠졌다."},{"번호":4,"판정":"옳음","설명":"부종성·수반성·불가분성이 유치권에 인정된다."},{"번호":5,"판정":"틀림","설명":"물상대위성(ㄹ)은 유치권에 없다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"피담보채권이 없으면 유치권도 없다."},{"기호":"ㄴ","판정":"옳음","설명":"피담보채권이 양도되면 유치권도 함께 이전한다. 다만 점유 이전이 필요하다."},{"기호":"ㄷ","판정":"옳음","설명":"채권 전부를 변제받을 때까지 유치물 전부에 행사할 수 있다(제321조)."},{"기호":"ㄹ","판정":"틀림","설명":"우선변제권이 없어 물상대위성은 인정되지 않는다."}],"개념":[{"종류":"표","제목":"담보물권의 통유성","머리":["통유성","유치권","질권","저당권"],"행":[["부종성","있음","있음","있음"],["수반성","있음","있음","있음"],["불가분성","있음(제321조)","있음","있음"],["물상대위성","없음","있음","있음"]]}],"함정":"물상대위성은 우선변제권이 있는 담보물권에만 있다. 유치권은 유치적 효력만 있어 ㄹ을 고르면 틀린다."},"31회-1차-062":{"한줄":"유치권을 포기하기로 한 특약은 당사자뿐 아니라 제3자도 그 특약의 효력을 주장할 수 있다. 2번이 틀렸다.","근거":[{"법령":"민법","조문":"제322조제1항","원문":"유치권자는 채권의 변제를 받기 위하여 유치물을 경매할 수 있다."},{"법령":"민법","조문":"제327조","원문":"채무자는 상당한 담보를 제공하고 유치권의 소멸을 청구할 수 있다."},{"판례":"대법원 판례(유치권 배제 특약)","요지":"유치권 배제 특약이 있으면 그 특약의 상대방이 아닌 제3자도 특약의 효력을 주장할 수 있다."},{"판례":"대법원 판례(권리금)","요지":"임차인이 임대인과의 약정에 따른 권리금반환채권으로는 임차건물에 유치권을 행사할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"점유는 직접점유든 간접점유든 상관없다(채무자를 매개로 한 간접점유는 제외)."},{"번호":2,"판정":"틀림","설명":"특약의 효력은 제3자도 주장할 수 있다(판례)."},{"번호":3,"판정":"옳음","설명":"유치권자는 유치물을 경매할 수 있다(제322조제1항)."},{"번호":4,"판정":"옳음","설명":"채무자는 상당한 담보를 제공하고 소멸을 청구할 수 있다(제327조)."},{"번호":5,"판정":"옳음","설명":"권리금반환채권은 건물에 관하여 생긴 채권이 아니다(판례)."}],"개념":[{"종류":"표","제목":"유치권의 특약·소멸청구","머리":["쟁점","내용"],"행":[["유치권 배제·포기 특약","당사자 외 제3자도 효력 주장 가능"],["경매권","있음(제322조제1항), 우선변제권은 없음"],["타담보 제공","채무자의 소멸청구(제327조)"],["권리금반환채권","피담보채권 불인정"],["점유 형태","직접·간접 불문, 채무자 매개 간접점유 제외"]]}],"함정":"포기 특약은 당사자 사이에서만 효력이 있다고 읽기 쉽다. 판례는 제3자도 특약을 주장할 수 있다고 본다."},"31회-1차-063":{"한줄":"일괄경매는 설정 후 설정자가 건물을 축조했거나 설정자가 그 건물의 소유권을 취득한 경우에 청구할 수 있어 ㄴ·ㄷ이 해당한다.","근거":[{"법령":"민법","조문":"제365조","원문":"토지를 목적으로 저당권을 설정한 후 그 설정자가 그 토지에 건물을 축조한 때에는 저당권자는 토지와 함께 그 건물에 대하여도 경매를 청구할 수 있다. 그러나 그 건물의 경매대가에 대하여는 우선변제를 받을 권리가 없다."},{"판례":"대법원 판례(제3자가 축조한 건물과 일괄경매)","요지":"저당권 설정 후 제3자가 축조한 건물이라도 설정자가 그 소유권을 취득했다면 저당권자는 토지와 함께 건물의 일괄경매를 청구할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄴ·ㄷ도 가능하다."},{"번호":2,"판정":"틀림","설명":"ㄷ도 가능하다."},{"번호":3,"판정":"틀림","설명":"ㄱ은 불가능하다."},{"번호":4,"판정":"옳음","설명":"ㄴ(설정 후 설정자 축조)과 ㄷ(설정자가 건물 소유권 취득)이 해당한다."},{"번호":5,"판정":"틀림","설명":"ㄱ은 설정 전에 이미 건물이 있었으므로 제외된다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"저당권 설정 전에 이미 건물이 존재했으므로 제365조의 설정 후 축조에 해당하지 않는다."},{"기호":"ㄴ","판정":"옳음","설명":"설정 후 설정자가 건물을 축조해 소유하므로 제365조 본문에 해당한다."},{"기호":"ㄷ","판정":"옳음","설명":"건물을 지은 자는 지상권자 丙이지만 설정자 乙이 그 소유권을 취득했으므로 일괄경매를 청구할 수 있다."}],"개념":[{"종류":"표","제목":"일괄경매 청구 가능 여부","머리":["사례","가능","이유"],"행":[["설정 전부터 설정자 소유 건물","불가","제365조는 설정 후 축조"],["설정 후 설정자가 축조","가능","제365조 본문"],["설정 후 제3자 축조, 설정자가 소유권 취득","가능","판례"],["설정 후 제3자 축조, 제3자 소유","불가","판례"],["건물 경매대가의 우선변제","불가","제365조 단서"]]}],"함정":"ㄷ은 건물을 지은 사람이 丙이라서 제3자 건물이라고 보고 빼기 쉽다. 기준은 건물을 누가 지었는지가 아니라, 일괄경매 때 건물이 설정자 소유인가이다."},"31회-1차-064":{"한줄":"채권최고액에는 채무의 이자가 산입된 것으로 본다.","근거":[{"법령":"민법","조문":"제357조","원문":"①저당권은 그 담보할 채무의 최고액만을 정하고 채무의 확정을 장래에 보류하여 이를 설정할 수 있다. 이 경우에는 그 확정될 때까지의 채무의 소멸 또는 이전은 저당권에 영향을 미치지 아니한다. ②전항의 경우에는 채무의 이자는 최고액 중에 산입한 것으로 본다."},{"판례":"대법원 판례(제3자 명의 근저당)","요지":"채권자가 아닌 제3자 명의로 한 근저당권설정등기는 특별한 사정이 없는 한 무효다."},{"판례":"대법원 판례(기본계약 해지와 확정)","요지":"근저당권설정자가 적법하게 기본계약을 해지하면 피담보채권이 확정된다."},{"판례":"대법원 판례(경매신청과 확정)","요지":"근저당권자가 피담보채무 불이행을 이유로 경매를 신청하면 신청 시에 피담보채권액이 확정된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"물상보증처럼 채무자가 아닌 제3자도 근저당권을 설정할 수 있다."},{"번호":2,"판정":"옳음","설명":"채권자가 아닌 제3자 명의의 등기는 특별한 사정이 없는 한 무효다."},{"번호":3,"판정":"틀림","설명":"이자는 최고액 중에 산입한 것으로 본다(제357조제2항)."},{"번호":4,"판정":"옳음","설명":"설정자가 기본계약을 적법하게 해지하면 피담보채권이 확정된다."},{"번호":5,"판정":"옳음","설명":"근저당권자가 직접 경매를 신청하면 신청 시에 확정된다."}],"개념":[{"종류":"표","제목":"근저당권의 핵심 쟁점","머리":["쟁점","내용","근거"],"행":[["채권최고액과 이자","이자는 최고액에 포함","제357조제2항"],["지연배상","최고액 한도 내에서 담보","판례"],["확정 전 채권 변동","저당권에 영향 없음","제357조제1항"],["확정 전 채무자 변경","가능","판례"],["물상보증인의 책임","최고액 한도","판례"],["명의","채권자 명의여야 유효","판례"]]}],"함정":"채권최고액은 원금 기준이라고 보기 쉽다. 이자도 최고액에 들어가므로 원금과 이자의 합이 최고액을 넘지 못한다."},"31회-1차-065":{"한줄":"현상광고는 광고에 정한 행위를 완료함으로써 효력이 생기는 요물계약이어서 낙성계약으로 짝지은 것이 잘못이다.","근거":[{"법령":"민법","조문":"제675조","원문":"현상광고는 광고자가 어느 행위를 한 자에게 일정한 보수를 지급할 의사를 표시하고 이에 응한 자가 그 광고에 정한 행위를 완료함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제664조","원문":"도급은 당사자 일방이 어느 일을 완성할 것을 약정하고 상대방이 그 일의 결과에 대하여 보수를 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제609조","원문":"사용대차는 당사자 일방이 상대방에게 무상으로 사용, 수익하게 하기 위하여 목적물을 인도할 것을 약정하고 상대방은 이를 사용, 수익한 후 그 물건을 반환할 것을 약정함으로써 그 효력이 생긴다."}],"선지":[{"번호":1,"판정":"옳음","설명":"도급은 일의 완성과 보수 지급이 서로 대가인 쌍무계약이다(제664조)."},{"번호":2,"판정":"옳음","설명":"무상임치는 수치인만 보관 채무를 지는 편무계약이다."},{"번호":3,"판정":"옳음","설명":"임대차는 차임을 대가로 하는 유상계약이다."},{"번호":4,"판정":"옳음","설명":"사용대차는 대가 없이 사용하게 하는 무상계약이다(제609조)."},{"번호":5,"판정":"틀림","설명":"현상광고는 행위 완료로 효력이 생기는 요물계약이다(제675조). 낙성계약이 아니다."}],"개념":[{"종류":"표","제목":"계약의 종류와 예","머리":["분류","예","근거"],"행":[["쌍무·유상·낙성","매매, 교환, 임대차, 도급","제563조, 제618조, 제664조"],["편무·무상·낙성","증여, 사용대차, 무상임치","제554조, 제609조, 제693조"],["편무·유상","이자부 소비대차","-"],["요물계약","현상광고","제675조"],["낙성계약","임치(승낙으로 효력 발생)","제693조"]]}],"함정":"전형계약 이름만 보면 모든 계약이 합의만으로 성립한다고 단정하게 된다. 현상광고는 정한 행위를 완료해야 효력이 생기는 점이 다르다."},"31회-1차-066":{"한줄":"청약자가 발송 후 사망해도 청약의 효력은 그대로이므로 효력을 상실한다는 선지는 틀리다.","근거":[{"법령":"민법","조문":"제111조","원문":"① 상대방이 있는 의사표시는 상대방에게 도달한 때에 그 효력이 생긴다. ② 의사표시자가 그 통지를 발송한 후 사망하거나 제한능력자가 되어도 의사표시의 효력에 영향을 미치지 아니한다."},{"법령":"민법","조문":"제528조제1항","원문":"승낙의 기간을 정한 계약의 청약은 청약자가 그 기간 내에 승낙의 통지를 받지 못한 때에는 그 효력을 잃는다."},{"법령":"민법","조문":"제530조","원문":"전2조의 경우에 연착된 승낙은 청약자가 이를 새 청약으로 볼 수 있다."},{"법령":"민법","조문":"제534조","원문":"승낙자가 청약에 대하여 조건을 붙이거나 변경을 가하여 승낙한 때에는 그 청약의 거절과 동시에 새로 청약한 것으로 본다."},{"판례":"대법원 판례(침묵과 승낙)","요지":"청약자가 이의가 없으면 승낙한 것으로 본다고 표시해도 상대방을 구속하지 못하므로 상대방이 이의하지 않아도 계약이 성립하지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"청약은 상대방에게 도달한 때 효력이 생긴다(제111조제1항). 2020.5.1. 도달했다."},{"번호":2,"판정":"틀림","설명":"발송 후 청약자가 사망해도 청약의 효력은 영향을 받지 않는다(제111조제2항)."},{"번호":3,"판정":"옳음","설명":"청약자가 정한 침묵의 승낙 간주는 상대방을 구속하지 못해 계약이 성립하지 않는다."},{"번호":4,"판정":"옳음","설명":"5.8. 기간이 지난 5.15. 도달한 승낙은 연착된 승낙이어서 甲이 새 청약으로 보고 승낙하면 계약이 성립한다(제530조)."},{"번호":5,"판정":"옳음","설명":"청약은 5억원, 승낙은 5천만원이어서 내용이 일치하지 않는다. 승낙이 도달해도 계약이 성립하지 않는다(제534조)."}],"개념":[{"종류":"표","제목":"의사표시의 효력 발생","머리":["경우","효력","근거"],"행":[["상대방 있는 의사표시","도달한 때 효력 발생","제111조제1항"],["발송 후 표의자의 사망·제한능력","효력에 영향 없음","제111조제2항"],["상대방이 제한능력자일 때","의사표시자는 대항 불가(법정대리인이 안 뒤는 예외)","제112조"],["승낙기간 후 도달한 승낙","청약 효력 상실, 청약자는 새 청약으로 볼 수 있음","제528조제1항, 제530조"],["변경을 가한 승낙","거절 + 새 청약","제534조"]]},{"종류":"흐름","제목":"이 사안의 시간 흐름","단계":[{"이름":"2020.5.1.","설명":"청약이 乙에게 도달해 효력 발생"},{"이름":"2020.5.8.","설명":"승낙기간 만료, 승낙 통지가 도달하지 않아 청약 효력 상실"},{"이름":"2020.5.15.","설명":"乙의 승낙이 연착으로 도달"},{"이름":"甲의 선택","설명":"연착 승낙을 새 청약으로 보고 승낙하면 계약 성립"}]}],"함정":"청약자가 죽으면 상대방과의 신뢰관계가 사라져 청약도 효력을 잃는다고 보기 쉽다. 민법은 발송 후 사망해도 의사표시의 효력은 유지된다고 정한다."},"31회-1차-067":{"한줄":"ㄱ(보증금 반환과 목적물 반환)과 ㄹ(건물매수청구권 행사 후 건물 인도·등기와 대금 지급)이 동시이행 관계다.","근거":[{"법령":"민법","조문":"제536조제1항","원문":"쌍무계약의 당사자 일방은 상대방이 그 채무이행을 제공할 때 까지 자기의 채무이행을 거절할 수 있다. 그러나 상대방의 채무가 변제기에 있지 아니하는 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제643조","원문":"건물 기타 공작물의 소유 또는 식목, 채염, 목축을 목적으로 한 토지임대차의 기간이 만료한 경우에 건물, 수목 기타 지상시설이 현존한 때에는 제283조의 규정을 준용한다."},{"판례":"대법원 판례(임대차 종료)","요지":"임대차 종료 시 임차인의 목적물 반환의무와 임대인의 보증금 반환의무는 동시이행 관계다."},{"판례":"대법원 판례(건물매수청구권)","요지":"임차인이 건물매수청구권을 행사하면 건물 인도·소유권이전등기의무와 임대인의 대금 지급의무는 동시이행 관계다."},{"판례":"대법원 판례(변제와 말소)","요지":"피담보채권을 변제할 의무가 근저당권설정등기 말소의무보다 먼저이고 둘은 동시이행 관계가 아니다."},{"판례":"대법원 판례(토지거래허가)","요지":"매도인의 토지거래허가 신청절차 협력의무와 매수인의 대금지급의무는 동시이행 관계가 아니다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄹ뿐 아니라 ㄱ도 동시이행 관계다."},{"번호":2,"판정":"틀림","설명":"ㄴ은 동시이행 관계가 아니다."},{"번호":3,"판정":"옳음","설명":"동시이행 관계에 있는 것은 ㄱ, ㄹ이다."},{"번호":4,"판정":"틀림","설명":"ㄴ, ㄷ은 동시이행 관계가 아니다."},{"번호":5,"판정":"틀림","설명":"ㄷ은 동시이행 관계가 아니다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"임대차 종료 시 보증금 반환의무와 임차물 반환의무는 동시이행 관계다."},{"기호":"ㄴ","판정":"틀림","설명":"피담보채권의 변제가 먼저이고 말소등기는 그 뒤여서 동시이행이 아니다."},{"기호":"ㄷ","판정":"틀림","설명":"토지거래허가 신청 협력의무와 대금지급의무는 서로 대가관계가 아니다."},{"기호":"ㄹ","판정":"옳음","설명":"건물매수청구권을 행사하면 건물 인도·등기의무와 대금 지급의무가 동시이행 관계가 된다."}],"개념":[{"종류":"비교","제목":"동시이행 관계의 인정과 부정","왼쪽":{"이름":"동시이행 인정","항목":["임대차 종료 시 보증금 반환과 목적물 반환","건물매수청구권 행사 후 건물 인도·등기와 대금 지급","해제 후 쌍방 원상회복의무(제549조)","전세권 소멸 시 인도·서류 교부와 전세금 반환(제317조)"]},"오른쪽":{"이름":"동시이행 부정","항목":["피담보채권 변제와 근저당권 말소(변제가 선이행)","토지거래허가 협력의무와 대금 지급","무효 경매의 말소의무와 배당금 반환의무"]}},{"종류":"표","제목":"동시이행 항변권의 요건과 효과","머리":["쟁점","내용","근거"],"행":[["요건","쌍무계약, 상대방 채무가 변제기에 있을 것","제536조제1항"],["먼저 이행할 자","상대방 이행이 곤란할 현저한 사유가 있으면 항변 가능","제536조제2항"],["효과","상대방이 이행을 제공할 때까지 자기 채무 이행 거절","제536조제1항"],["이행지체","동시이행 항변권이 있는 동안은 지체 책임이 없음","판례"]]}],"함정":"서로 얽힌 채무는 모두 동시이행이라고 보기 쉽다. 변제가 먼저인 말소등기(ㄴ)와 허가 협력의무(ㄷ)는 대가관계가 아니어서 빠진다."},"31회-1차-068":{"한줄":"채무자 책임 있는 사유로 생긴 후발적 불능은 위험부담이 아니라 채무불이행이어서 손해배상·해제의 문제다.","근거":[{"법령":"민법","조문":"제105조","원문":"법률행위의 당사자가 법령 중의 선량한 풍속 기타 사회질서에 관계없는 규정과 다른 의사를 표시한 때에는 그 의사에 의한다."},{"법령":"민법","조문":"제390조","원문":"채무자가 채무의 내용에 좇은 이행을 하지 아니한 때에는 채권자는 손해배상을 청구할 수 있다. 그러나 채무자의 고의나 과실없이 이행할 수 없게 된 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제538조제1항","원문":"쌍무계약의 당사자 일방의 채무가 채권자의 책임있는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구할 수 있다. 채권자의 수령지체 중에 당사자쌍방의 책임없는 사유로 이행할 수 없게 된 때에도 같다."},{"판례":"대법원 판례(대상청구권)","요지":"대상청구권을 행사한 채권자는 반대급부를 이행할 의무가 있어 매도인은 매매대금을 청구할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"위험부담 규정은 임의규정이어서 당사자가 달리 정할 수 있다(제105조)."},{"번호":2,"판정":"틀림","설명":"채무자 책임 있는 사유로 불능이 되면 채무불이행이다(제390조, 제546조). 위험부담 법리가 적용되지 않는다."},{"번호":3,"판정":"옳음","설명":"대상청구권을 행사하면 매수인은 반대급부인 대금을 지급할 의무가 있다."},{"번호":4,"판정":"옳음","설명":"채권자의 수령지체 중 쌍방 무책 불능이면 채무자는 상대방의 이행을 청구할 수 있다(제538조제1항 후단)."},{"번호":5,"판정":"옳음","설명":"채권자 책임 있는 불능이면 채무자는 상대방의 이행을 청구할 수 있다(제538조제1항 전단)."}],"개념":[{"종류":"표","제목":"불능과 위험부담 정리","머리":["귀책","효과","근거"],"행":[["채무자 책임","손해배상·해제","제390조, 제546조"],["쌍방 무책","채무자는 반대급부 청구 불가","제537조"],["채권자 책임","채무자는 반대급부 청구 가능","제538조제1항 전단"],["수령지체 중 쌍방 무책","채무자는 반대급부 청구 가능","제538조제1항 후단"],["당사자 특약","임의규정이므로 달리 정할 수 있음","제105조"]]}],"함정":"위험부담은 불능이 생기면 언제나 적용된다고 보기 쉽다. 채무자에게 귀책이 있으면 채무불이행으로 처리하고 위험부담은 문제 되지 않는다."},"31회-1차-069":{"한줄":"요약자가 낙약자의 채무불이행을 이유로 계약을 해제하면, 수익자는 낙약자에게 자기가 입은 손해의 배상을 청구할 수 있다.","근거":[{"법령":"민법","조문":"제541조","원문":"제539조의 규정에 의하여 제삼자의 권리가 생긴 후에는 당사자는 이를 변경 또는 소멸시키지 못한다."},{"법령":"민법","조문":"제542조","원문":"채무자는 제539조의 계약에 기한 항변으로 그 계약의 이익을 받을 제삼자에게 대항할 수 있다."},{"판례":"대법원 판례(제3자를 위한 계약의 해제와 수익자의 손해배상)","요지":"낙약자의 채무불이행으로 요약자가 계약을 해제해도 수익자는 낙약자에게 채무불이행으로 자기가 입은 손해의 배상을 청구할 수 있다."},{"판례":"대법원 판례(해제 후 급부의 반환)","요지":"낙약자가 요약자와의 계약을 해제하고 이미 수익자에게 한 급부를 돌려받으려면, 반환 상대방은 수익자가 아니라 계약 상대방인 요약자다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수익자가 수익의 의사표시를 한 뒤에는 당사자가 제3자의 권리를 소멸시키지 못한다(제541조). 수익자 동의 없는 합의해제는 허용되지 않는다."},{"번호":2,"판정":"틀림","설명":"수익자는 계약의 당사자가 아니어서 해제권이 없다. 해제권은 요약자 몫이다."},{"번호":3,"판정":"옳음","설명":"요약자의 해제로 수익자의 권리는 소멸하지만, 낙약자의 채무불이행에 따른 수익자 자신의 손해배상청구는 인정된다."},{"번호":4,"판정":"틀림","설명":"낙약자는 요약자와의 계약에 기한 항변(동시이행 등)으로 수익자에게 대항할 수 있다(제542조). 甲의 등기 지체를 이유로 대금지급을 거절할 수 있다."},{"번호":5,"판정":"틀림","설명":"낙약자 乙이 해제하고 丙에게 이미 지급한 대금을 돌려받으려면 요약자 甲에게 청구해야 하고, 丙에게는 청구할 수 없다."}],"개념":[{"종류":"비교","제목":"요약자·낙약자·수익자의 권한","왼쪽":{"이름":"요약자·낙약자(계약 당사자)","항목":["계약 취소·해제는 당사자 몫","요약자는 수익자 동의 없이 낙약자의 채무불이행을 이유로 해제 가능","낙약자는 기본관계(보상관계) 항변으로 수익자에게 대항(제542조)","수익자 수익 표시 뒤에는 합의로 권리 변경·소멸 불가(제541조)"]},"오른쪽":{"이름":"수익자(제3자)","항목":["수익의 의사표시로 권리 취득(제539조제2항)","낙약자에게 직접 이행 청구","해제권·취소권 없음(당사자 아님)","낙약자 채무불이행 시 자기 손해배상 청구 가능","계약 체결 당시 특정·현존 불요"]}},{"종류":"흐름","제목":"제3자를 위한 계약의 권리 발생","단계":[{"이름":"계약 체결","설명":"요약자와 낙약자가 제3자에게 급부하기로 약정(제539조제1항)"},{"이름":"수익의 의사표시","설명":"수익자가 낙약자에게 표시한 때 수익자의 권리 발생(제539조제2항)"},{"이름":"권리 확정","설명":"이후 당사자는 수익자의 권리를 변경·소멸시키지 못함(제541조)"},{"이름":"해제 시","설명":"요약자가 해제하면 수익자는 낙약자에게 손해배상 청구, 낙약자의 반환 청구 상대는 요약자"}]}],"함정":"4번에서 동시이행 항변을 수익자에게 쓸 수 있는지가 갈린다. 낙약자는 요약자와의 관계에서 생긴 항변을 수익자에게 그대로 내세울 수 있다. 5번은 해제 후 반환 상대방이 수익자가 아니라 요약자라는 점에서 틀린다."},"31회-1차-070":{"한줄":"채무자가 미리 이행하지 않겠다는 의사를 명백히 표시하면 이행기 전이라도 최고 없이 해제할 수 있다.","근거":[{"법령":"민법","조문":"제544조","원문":"당사자 일방이 그 채무를 이행하지 아니하는 때에는 상대방은 상당한 기간을 정하여 그 이행을 최고하고 그 기간내에 이행하지 아니한 때에는 계약을 해제할 수 있다. 그러나 채무자가 미리 이행하지 아니할 의사를 표시한 경우에는 최고를 요하지 아니한다."},{"법령":"민법","조문":"제551조","원문":"계약의 해지 또는 해제는 손해배상의 청구에 영향을 미치지 아니한다."},{"법령":"민법","조문":"제547조제1항","원문":"당사자의 일방 또는 쌍방이 수인인 경우에는 계약의 해지나 해제는 그 전원으로부터 또는 전원에 대하여 하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"해지·해제 모두 손해배상 청구에 영향이 없다(제551조)."},{"번호":2,"판정":"틀림","설명":"제544조 단서의 '미리' 이행하지 않겠다는 의사표시는 이행기 전의 이행거절을 가리킨다. 이행거절이 명백하면 이행기 도래 전에도 최고 없이 해제할 수 있다."},{"번호":3,"판정":"옳음","설명":"이행불능은 이행 자체가 불가능하므로, 해제하는 채권자가 자기 급부를 제공해 이행을 청구할 필요가 없다(제546조)."},{"번호":4,"판정":"옳음","설명":"일부 이행불능이라도 나머지만으로는 계약 목적을 이룰 수 없으면 계약 전부를 해제할 수 있다."},{"번호":5,"판정":"옳음","설명":"해지·해제의 불가분성이다(제547조제1항)."}],"개념":[{"종류":"표","제목":"해제 사유별 최고 필요 여부","머리":["사유","최고","근거"],"행":[["이행지체","필요(상당한 기간)","제544조 본문"],["이행거절(이행기 전 포함)","불요","제544조 단서"],["이행불능","불요","제546조"],["정기행위의 이행지체","불요","제545조"],["일부 이행불능","불요, 목적 달성 불능이면 전부 해제","제546조 법리"],["당사자 다수","전원 행사·전원 상대","제547조제1항"]]}],"함정":"이행기가 오기 전이니 최고부터 해야 한다고 판단하면 2번이 옳아 보인다. 이행거절은 이행기 전후를 가리지 않고 최고를 면제한다."},"31회-1차-072":{"한줄":"합의해제는 계약 내용을 새로 정하는 계약이어서, 특약이 없으면 채무불이행으로 인한 손해배상청구권이 따로 생기지 않는다.","근거":[{"법령":"민법","조문":"제548조제1항","원문":"당사자 일방이 계약을 해제한 때에는 각 당사자는 그 상대방에 대하여 원상회복의 의무가 있다. 그러나 제삼자의 권리를 해하지 못한다."},{"법령":"민법","조문":"제548조제2항","원문":"전항의 경우에 반환할 금전에는 그 받은 날로부터 이자를 가하여야 한다."},{"판례":"대법원 판례(합의해제의 효과)","요지":"합의해제는 법정해제와 달리 제548조제2항과 제551조가 적용되지 않는다. 반환 금전에 이자를 붙이지 않아도 되고, 특약이 없으면 채무불이행에 따른 손해배상도 청구하지 못한다. 소유권은 당연히 복귀하고 제3자의 권리는 해하지 못한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"합의해제에는 법정해제의 손해배상 규정(제551조)이 적용되지 않는다. 특약이 없으면 채무불이행 손해배상을 청구하지 못한다."},{"번호":2,"판정":"옳음","설명":"제548조제2항의 이자 가산은 법정해제 규정이어서 합의해제에는 적용되지 않는다. 약정이 있어야 이자를 붙인다."},{"번호":3,"판정":"옳음","설명":"합의해제의 물권적 효과로 매수인에게 넘어간 소유권은 당연히 매도인에게 복귀한다."},{"번호":4,"판정":"옳음","설명":"합의해제의 소급효도 제548조제1항 단서와 같이 제3자의 권리를 해하지 못한다."},{"번호":5,"판정":"옳음","설명":"매도인이 해제를 주장하며 대금을 공탁하고 매수인이 이의 없이 수령하면 묵시적 합의해제로 본다."}],"개념":[{"종류":"표","제목":"법정해제와 합의해제","머리":["구분","법정해제","합의해제"],"행":[["근거","법률(제544조~제546조)","당사자 합의(계약)"],["소급효","있음","있음, 제3자의 권리 불가침"],["반환 금전의 이자","받은 날부터 가산(제548조제2항)","약정 없으면 불요"],["손해배상","청구 가능(제551조)","특약 없으면 불가"],["이행제공","상대방 채무불이행·최고 요건 필요","자기 채무의 이행제공 불요"],["소유권","당연 복귀(등기 무관)","당연 복귀"]]}],"함정":"합의해제를 해제의 한 종류로만 보면 법정해제 효과를 그대로 끌어와 1번을 옳게 본다. 합의해제의 효과는 합의 내용이 정하며, 합의에 정함이 없으면 이자와 손해배상이 모두 빠진다."},"31회-1차-071":{"한줄":"불특정물(종류매매)의 하자에서는 해제, 손해배상, 완전물급부청구가 규정되어 있고 대금감액청구권은 규정되어 있지 않다.","근거":[{"법령":"민법","조문":"제581조","원문":"① 매매의 목적물을 종류로 지정한 경우에도 그 후 특정된 목적물에 하자가 있는 때에는 전조의 규정을 준용한다. ② 전항의 경우에 매수인은 계약의 해제 또는 손해배상의 청구를 하지 아니하고 하자없는 물건을 청구할 수 있다."},{"법령":"민법","조문":"제580조제1항","원문":"매매의 목적물에 하자가 있는 때에는 제575조제1항의 규정을 준용한다. 그러나 매수인이 하자있는 것을 알았거나 과실로 인하여 이를 알지 못한 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제575조제1항","원문":"매매의 목적물이 지상권, 지역권, 전세권, 질권 또는 유치권의 목적이 된 경우에 매수인이 이를 알지 못한 때에는 이로 인하여 계약의 목적을 달성할 수 없는 경우에 한하여 매수인은 계약을 해제할 수 있다. 기타의 경우에는 손해배상만을 청구할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ만 고르면 ㄱ, ㄴ, ㄹ이 빠진다. ㄷ은 규정에 없다."},{"번호":2,"판정":"틀림","설명":"ㄷ은 규정된 권리가 아니다."},{"번호":3,"판정":"틀림","설명":"ㄱ이 빠졌다. 계약목적을 달성할 수 없으면 해제권이 있다."},{"번호":4,"판정":"옳음","설명":"ㄱ, ㄴ, ㄹ이 규정된 권리다."},{"번호":5,"판정":"틀림","설명":"ㄷ 대금감액청구권은 하자담보 규정에 없다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"계약의 목적을 달성할 수 없는 경우 해제권이 인정된다(제581조제1항, 제580조, 제575조제1항)."},{"기호":"ㄴ","판정":"옳음","설명":"하자가 있으면 손해배상을 청구할 수 있다(제580조, 제575조제1항)."},{"기호":"ㄷ","판정":"틀림","설명":"하자담보책임의 효과로 대금감액청구는 규정되어 있지 않다. 대금감액은 권리의 일부 타인 귀속·수량부족(제572조·제574조) 등에서 나온다."},{"기호":"ㄹ","판정":"옳음","설명":"종류매매에서는 해제·손해배상 대신 하자 없는 물건을 청구할 수 있다(제581조제2항)."}],"개념":[{"종류":"표","제목":"담보책임 유형별 매수인의 권리","머리":["유형","해제","대금감액","손해배상","근거"],"행":[["전부 타인 권리","가능(선의·악의)","-","선의만","제570조"],["일부 타인 권리·수량부족","선의, 잔존만이면 매수 안 했을 때","가능","선의만","제572조·제574조"],["제한물권","계약목적 달성 불가 시","-","가능","제575조"],["저당권·전세권 행사","가능","-","가능","제576조"],["특정물 하자","계약목적 달성 불가 시","-","가능","제580조"],["종류물 하자","같음 + 완전물급부청구","-","가능","제581조"]]}],"함정":"ㄷ에서 하자가 있으면 값을 깎아 달라는 청구가 당연히 될 것 같지만, 민법은 하자담보에 대금감액청구를 규정하지 않는다. 대금감액은 일부 타인 권리·수량부족에서 나온다."},"31회-1차-073":{"한줄":"토지거래허가구역 내 계약에 허가를 받은 것만으로는 이행착수가 아니므로, 매도인은 배액을 상환하고 해제할 수 있다.","근거":[{"법령":"민법","조문":"제565조","원문":"① 매매의 당사자 일방이 계약당시에 금전 기타 물건을 계약금, 보증금등의 명목으로 상대방에게 교부한 때에는 당사자간에 다른 약정이 없는 한 당사자의 일방이 이행에 착수할 때까지 교부자는 이를 포기하고 수령자는 그 배액을 상환하여 매매계약을 해제할 수 있다. ② 제551조의 규정은 전항의 경우에 이를 적용하지 아니한다."},{"법령":"민법","조문":"제398조제4항","원문":"위약금의 약정은 손해배상액의 예정으로 추정한다."},{"판례":"대법원 판례(계약금 일부 지급과 해제)","요지":"계약금 일부만 지급된 경우 수령자가 배액상환 해제를 하려면 약정 계약금의 배액을 상환해야 하고, 받은 일부의 배액만으로는 해제할 수 없다."},{"판례":"대법원 판례(토지거래허가와 이행착수)","요지":"토지거래허가를 받는 것은 이행의 착수에 해당하지 않으므로, 허가를 받은 뒤에도 이행착수 전이면 해약금 규정에 따라 해제할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"계약금은 특약이 없으면 해약금으로 추정한다(제565조제1항)."},{"번호":2,"판정":"옳음","설명":"계약금을 위약금으로 약정하면 손해배상액의 예정으로 추정된다(제398조제4항)."},{"번호":3,"판정":"옳음","설명":"이행기 전 중도금 지급도 이행착수라서 甲은 배액을 상환하고 해제할 수 없다."},{"번호":4,"판정":"옳음","설명":"일부만 지급된 경우 수령한 금액의 배액을 상환해서는 해제할 수 없다. 약정 계약금의 배액을 상환해야 해제할 수 있다."},{"번호":5,"판정":"틀림","설명":"허가를 받는 것은 이행착수가 아니므로 甲은 배액을 상환하고 해제할 수 있다."}],"개념":[{"종류":"표","제목":"이행착수 해당 여부","머리":["사례","이행착수","결과"],"행":[["중도금 지급(약정 기일 전 포함)","해당","해약금 해제 불가"],["토지거래허가 신청·취득","비해당","해약금 해제 가능"],["계약금 일부 지급","비해당","약정 계약금 배액 상환 후 해제"],["계약금 지급 자체","비해당","해약금 해제 가능"]]}],"함정":"허가를 받으면 계약이 완전 유효해져 이행에 착수한 것으로 보이기 쉽다. 판례는 허가 취득을 이행착수로 보지 않아 배액상환 해제를 허용한다."},"31회-1차-074":{"한줄":"법원이 정한 증액 차임은 증액청구의 의사표시를 한 때로 소급해 효력이 생기고 그때를 이행기로 보므로, 결정 다음날부터 지연손해금이 발생한다는 설명이 틀리다.","근거":[{"법령":"민법","조문":"제628조","원문":"임대물에 대한 공과부담의 증감 기타 경제사정의 변동으로 인하여 약정한 차임이 상당하지 아니하게 된 때에는 당사자는 장래에 대한 차임의 증감을 청구할 수 있다."},{"법령":"민법","조문":"제627조제1항","원문":"임차물의 일부가 임차인의 과실없이 멸실 기타 사유로 인하여 사용, 수익할 수 없는 때에는 임차인은 그 부분의 비율에 의한 차임의 감액을 청구할 수 있다."},{"법령":"민법","조문":"제640조","원문":"건물 기타 공작물의 임대차에는 임차인의 차임연체액이 2기의 차임액에 달하는 때에는 임대인은 계약을 해지할 수 있다."},{"판례":"대법원 2015다239508, 239515","요지":"법원이 결정해 주는 증액 차임은 증액청구의 의사표시를 한 때에 소급해 효력이 생기고, 특별한 사정이 없으면 법원 결정 시가 아니라 증액청구의 의사표시가 상대방에게 도달한 때를 이행기로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"일부멸실로 사용·수익할 수 없는 부분의 비율로 차임감액을 청구할 수 있다(제627조제1항)."},{"번호":2,"판정":"옳음","설명":"공동임차인은 차임지급의무를 연대해 부담한다(제654조, 제616조)."},{"번호":3,"판정":"틀림","설명":"증액된 차임의 이행기는 결정 시가 아니라 증액청구가 도달한 때를 기준으로 본다. 결정 다음날부터 지연손해금이 생긴다는 설명은 틀리다."},{"번호":4,"판정":"옳음","설명":"차임연체로 해지된 임차인은 부속물매수를 청구할 수 없다(판례)."},{"번호":5,"판정":"옳음","설명":"1기 연체만으로 해지할 수 있다는 약정은 제640조의 2기 기준보다 임차인에게 불리해 무효다(제652조)."}],"개념":[{"종류":"표","제목":"임대차 차임 관련 규정","머리":["쟁점","내용","근거"],"행":[["일부멸실","과실 없는 일부멸실 시 비율대로 감액청구, 잔존부분으로 목적 달성이 안 되면 해지","제627조"],["차임증감청구","공과부담 증감·경제사정 변동으로 차임이 상당하지 않게 된 때 장래에 대해 청구","제628조"],["증액 결정의 효력","증액청구 의사표시를 한 때로 소급, 이행기도 그때","판례"],["연체와 해지","건물 임대차는 2기의 차임액에 달하면 임대인 해지","제640조"],["약정의 한계","1기 연체로 해지한다는 약정 등 불리한 약정 무효","제652조"],["공동임차","연대 의무","제654조, 제616조"]]}],"함정":"3은 법원이 결정할 때 비로소 증액 차임의 지급기일이 도래한다고 보기 쉽다. 판례는 결정의 효력이 청구 시로 소급한다고 보아 이행기도 청구 도달 시로 잡는다. 4는 연체 해지된 임차인에게 부속물매수청구가 막힌다는 판례의 내용이라 옳다."},"31회-1차-075":{"한줄":"임차권등기명령에 따른 등기와 관련해 든 비용은 임대인에게 청구할 수 있다.","근거":[{"법령":"주택임대차보호법","조문":"제3조의3제8항","원문":"임차인은 제1항에 따른 임차권등기명령의 신청과 그에 따른 임차권등기와 관련하여 든 비용을 임대인에게 청구할 수 있다."},{"법령":"주택임대차보호법","조문":"제3조의3제5항","원문":"임차권등기명령의 집행에 따른 임차권등기를 마치면 제3조제1항ㆍ제2항 또는 제3항에 따른 대항력과 제3조의2제2항에 따른 우선변제권을 취득한다. 다만, 임차인이 임차권등기 이전에 이미 대항력이나 우선변제권을 취득한 경우에는 그 대항력이나 우선변제권은 그대로 유지되며, 임차권등기 이후에는 제3조제1항ㆍ제2항 또는 제3항의 대항요건을 상실하더라도 이미 취득한 대항력이나 우선변제권을 상실하지 아니한다."},{"법령":"주택임대차보호법","조문":"제3조의3제6항","원문":"임차권등기명령의 집행에 따른 임차권등기가 끝난 주택(임대차의 목적이 주택의 일부분인 경우에는 해당 부분으로 한정한다)을 그 이후에 임차한 임차인은 제8조에 따른 우선변제를 받을 권리가 없다."},{"판례":"대법원 판례(임차권등기와 보증금반환)","요지":"임차인의 임차권등기말소 의무는 임대인의 보증금반환 의무보다 뒤에 이행할 의무여서 동시이행 관계에 있지 않다. 경매개시결정등기 전에 임차권등기를 마친 임차인은 배당요구를 하지 않아도 배당받는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"등기 신청과 등기에 든 비용을 임대인에게 청구할 수 있다(제3조의3제8항)."},{"번호":2,"판정":"틀림","설명":"임차권등기 후에는 이사해도 이미 취득한 대항력을 잃지 않는다(제3조의3제5항)."},{"번호":3,"판정":"틀림","설명":"보증금반환이 먼저이고 임차권등기말소는 그 뒤의 의무다. 동시이행이 아니다."},{"번호":4,"판정":"틀림","설명":"경매개시결정등기(2020. 6. 9.) 전에 임차권등기(2020. 3. 9.)를 마쳤으므로 배당요구 없이도 배당받는다. 순위도 2018. 3. 5.의 대항요건·확정일자가 丙의 저당권(2018. 5. 6.)보다 앞선다."},{"번호":5,"판정":"틀림","설명":"임차권등기 후에 임차한 丁은 최우선변제를 받지 못하고(제3조의3제6항), 확정일자도 없어 丙보다 앞서지 못한다."}],"개념":[{"종류":"표","제목":"임차권등기명령","머리":["구분","내용","근거"],"행":[["신청 시기","임대차 종료 후 보증금 미반환","제3조의3제1항"],["신청 법원","임차주택 소재지 관할 지방법원·지원·시군법원","제1항"],["효과","대항력·우선변제권 취득, 이전에 취득했다면 유지","제5항"],["등기 후 대항요건 상실","이미 취득한 권리 유지","제5항"],["비용","임대인에게 청구","제8항"],["등기 후 임차한 자","최우선변제 불가","제6항"]]}],"함정":"임차권등기를 마쳤으니 보증금 반환과 등기 말소를 맞바꾸는 동시이행으로 보기 쉽다. 반환이 먼저다. 등기 후 이사 때문에 대항력을 잃는다고 고르기도 쉬운데, 임차권등기 후에는 잃지 않는다."},"31회-1차-076":{"한줄":"채권담보 목적으로 임차주택을 양도한 경우에는 양수인이 임대인 지위를 승계하지 않아 양도인 甲이 보증금반환 의무를 면하지 못한다.","근거":[{"법령":"주택임대차보호법","조문":"제3조제4항","원문":"임차주택의 양수인(그 밖에 임대할 권리를 승계한 자를 포함한다)은 임대인의 지위를 승계한 것으로 본다."},{"판례":"대법원 판례(임차주택 양도와 임대인 지위)","요지":"임차주택이 양도되면 양수인이 임대인 지위를 승계하고 양도인은 보증금반환 의무를 면한다. 양도 전 발생한 연체차임채권은 따로 양수하지 않는 한 승계되지 않는다."},{"판례":"대법원 판례(양도담보)","요지":"채권담보를 목적으로 주택을 양도한 경우 양수인은 임대인 지위를 승계하지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"양수인이 임대인 지위를 승계하므로 양도인은 보증금반환의무를 면한다."},{"번호":2,"판정":"옳음","설명":"이미 발생한 연체차임채권은 따로 양도받지 않는 한 양수인에게 넘어가지 않는다."},{"번호":3,"판정":"옳음","설명":"가압류된 보증금반환채권의 제3채무자 지위는 양수인에게 승계된다."},{"번호":4,"판정":"옳음","설명":"보증금반환의무는 양수인의 의무이므로 반환한 양수인이 양도인에게 부당이득반환을 청구할 수 없다."},{"번호":5,"판정":"틀림","설명":"담보 목적 양도는 임대할 권리를 승계한 것이 아니어서 양수인이 임대인 지위를 승계하지 않는다. 甲은 의무를 면하지 못한다."}],"개념":[{"종류":"표","제목":"임차주택 양도 시 효과","머리":["쟁점","결과"],"행":[["보증금반환의무","양수인이 승계, 양도인 면책"],["양도 전 연체차임채권","별도 양수 없으면 승계 안 됨"],["양도 전 가압류된 보증금채권","양수인이 제3채무자 지위 승계"],["양수인이 보증금 반환","양도인에게 부당이득반환 청구 불가"],["채권담보 목적 양도","임대인 지위 승계 안 됨, 양도인 책임 존속"]]}],"함정":"담보 목적이든 매매든 소유권이 넘어가면 똑같이 임대인 지위가 이전된다고 생각하기 쉽다. 담보 목적 양도는 소유권 자체를 확정적으로 넘긴 것이 아니라 지위 승계가 일어나지 않는다."},"31회-1차-079":{"한줄":"ㄷ(전차인이 직접 점유하며 자기 명의로 사업자등록)은 임차인의 대항력이 유지되는 경우이고, 폐업(ㄱ)이나 폐업 뒤 재등록(ㄴ)은 종전 대항력이 이어지지 않는다. 시험에서는 ②와 ④를 모두 정답으로 처리했다.","근거":[{"법령":"상가건물 임대차보호법","조문":"제3조제1항","원문":"임대차는 그 등기가 없는 경우에도 임차인이 건물의 인도와 「부가가치세법」 제8조, 「소득세법」 제168조 또는 「법인세법」 제111조에 따른 사업자등록을 신청하면 그 다음 날부터 제3자에 대하여 효력이 생긴다."},{"판례":"대법원 판례(폐업과 대항력)","요지":"사업자등록은 대항력의 존속요건이기도 하다. 임차인이 폐업하면 사업자등록이 대항력 요건을 잃어 대항력이 소멸한다."},{"판례":"대법원 판례(전차인 명의 사업자등록)","요지":"적법한 전차인이 건물을 직접 점유하며 자기 명의로 사업자등록을 하고 영업하는 경우 임차인의 임대차는 제3자에 대하여 효력이 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ만으로는 폐업 시 대항력이 없어 틀린다."},{"번호":2,"판정":"옳음","설명":"ㄷ만 고른 조합으로 판례 기준 정답이다."},{"번호":3,"판정":"틀림","설명":"ㄱ이 틀려 조합이 어긋난다."},{"번호":4,"판정":"틀림","설명":"판례 기준으로 ㄴ은 틀려 이 조합은 맞지 않는다. 재등록 다음 날부터 생기는 새 대항력까지 넣어 읽으면 ㄴ도 효력이 있어 시험에서는 ④도 정답으로 처리했다."},{"번호":5,"판정":"틀림","설명":"ㄱ이 틀린다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"폐업하면 사업자등록이 대항력 요건을 잃어 대항력이 소멸한다."},{"기호":"ㄴ","판정":"틀림","설명":"폐업신고로 사업자등록이 대항력 요건을 잃으면 같은 상호·등록번호로 다시 등록해도 종전 대항력은 이어지지 않는다(판례). 새 등록 다음 날부터 새 대항력이 생길 뿐이다."},{"기호":"ㄷ","판정":"옳음","설명":"전차인이 직접 점유하며 자기 명의로 등록하고 영업하면 임차인의 임대차가 제3자에게 효력이 있다."}],"개념":[{"종류":"표","제목":"상가 대항력과 사업자등록","머리":["상황","결과"],"행":[["인도와 사업자등록 신청","다음 날부터 대항력"],["임차인 폐업","대항력 소멸"],["폐업 후 새로 사업자등록 신청","종전 대항력은 이어지지 않고 새 신청 다음 날부터 새로 효력"],["적법한 전차인이 직접 점유·자기 명의 등록","임차인의 임대차가 대항력 인정"],["확정일자","우선변제권 요건(대항력 요건 아님)"]]}],"함정":"사업자등록은 한 번만 하면 계속 유지된다고 보기 쉽다. 사업자등록은 대항력의 존속요건이라서 폐업하면 대항력이 사라진다."},"31회-1차-078":{"한줄":"채무 1억원에 시가 2억원인 건물을 이전등기로 담보했으면 가담법이 적용되고, 청산절차를 마쳐 소유권을 취득한 채권자 甲은 점유자 丙에게 인도를 청구할 수 있다.","근거":[{"법령":"가등기담보 등에 관한 법률","조문":"제4조제2항","원문":"채권자는 담보목적부동산에 관하여 이미 소유권이전등기를 마친 경우에는 청산기간이 지난 후 청산금을 채무자등에게 지급한 때에 담보목적부동산의 소유권을 취득하며, 담보가등기를 마친 경우에는 청산기간이 지나야 그 가등기에 따른 본등기(本登記)를 청구할 수 있다."},{"법령":"가등기담보 등에 관한 법률","조문":"제11조","원문":"채무자등은 청산금채권을 변제받을 때까지 그 채무액(반환할 때까지의 이자와 손해금을 포함한다)을 채권자에게 지급하고 그 채권담보의 목적으로 마친 소유권이전등기의 말소를 청구할 수 있다. 다만, 그 채무의 변제기가 지난 때부터 10년이 지나거나 선의의 제삼자가 소유권을 취득한 경우에는 그러하지 아니하다."},{"판례":"대법원 판례(양도담보권자의 지위)","요지":"양도담보는 채권담보가 목적이어서 담보권 실행으로 소유권을 확정하기 전에는 목적물의 사용·수익권이 설정자에게 있다. 양도담보 목적물이 멸실되어 설정자가 보험금청구권을 취득하면 양도담보권자는 여기에 물상대위권을 행사할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"양도담보권자는 설정자가 취득한 화재보험금청구권에 물상대위권을 행사할 수 있다. 행사할 수 없다는 진술이 틀리다."},{"번호":2,"판정":"틀림","설명":"청산절차를 마치기 전의 양도담보권자는 소유권을 확정적으로 취득하지 못한 상태이고 사용·수익권은 설정자에게 있다. 설정자에게서 임차한 丙에게 소유권에 기해 반환을 청구할 수 없다."},{"번호":3,"판정":"옳음","설명":"甲이 청산기간이 지나고 청산금을 지급해 소유권을 취득하면(제4조제2항) 담보권 실행의 결과로 임차인 丙에게 인도를 청구할 수 있다. 청산금 지급과 인도는 동시이행이다(제4조제3항)."},{"번호":4,"판정":"틀림","설명":"사용·수익권이 설정자 乙에게 있으므로 乙에게서 임차한 丙이 쓰는 데 대해 甲이 임료 상당 부당이득을 청구할 수 없다."},{"번호":5,"판정":"틀림","설명":"선의의 제삼자 丁이 소유권을 취득한 경우에는 말소를 청구할 수 없다(제11조 단서)."}],"개념":[{"종류":"표","제목":"양도담보 전후 당사자의 권리","머리":["구분","청산 전","청산 후(소유권 취득)"],"행":[["채권자 지위","담보권자. 소유권 확정 전","소유권 취득(제4조제2항)"],["사용·수익","설정자","채권자"],["임차인 상대 인도·부당이득","청구 불가","인도 청구 가능(청산금과 동시이행)"],["목적물 멸실 시 보험금","채권자가 물상대위","해당 없음"],["설정자의 말소 청구","변제하고 말소 청구(제11조)","선의 제3자 취득·변제기 후 10년이면 불가"]]}],"함정":"양도담보라서 이미 소유권이 甲에게 있다고 보면 선지 2와 4를 고르기 쉽다. 청산절차 전에는 담보권자일 뿐이고, 소유권을 확정한 뒤에야 인도를 청구할 수 있다."},"31회-1차-077":{"한줄":"옳은 것은 ㄱ뿐이다. 담보책임 기간의 전유부분 기산점은 인도한 날이고, 구조상 공용부분은 등기가 필요 없으며, 분양자도 담보책임을 진다.","근거":[{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제11조","원문":"각 공유자는 공용부분을 그 용도에 따라 사용할 수 있다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제9조의2제2항제1호","원문":"전유부분: 구분소유자에게 인도한 날"},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제9조제1항","원문":"제1조 또는 제1조의2의 건물을 건축하여 분양한 자(이하 \"분양자\"라 한다)와 분양자와의 계약에 따라 건물을 건축한 자로서 대통령령으로 정하는 자(이하 \"시공자\"라 한다)는 구분소유자에 대하여 담보책임을 진다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제13조제3항","원문":"공용부분에 관한 물권의 득실변경(得失變更)은 등기가 필요하지 아니하다."}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ만 옳다. 보기판정과 일치한다."},{"번호":2,"판정":"틀림","설명":"ㄷ은 틀린 보기다."},{"번호":3,"판정":"틀림","설명":"ㄴ이 틀려서 ㄱ, ㄴ 조합이 맞지 않는다."},{"번호":4,"판정":"틀림","설명":"ㄹ이 틀려서 ㄱ, ㄹ 조합이 맞지 않는다."},{"번호":5,"판정":"틀림","설명":"ㄴ, ㄷ, ㄹ 모두 틀린 보기다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"각 공유자는 공용부분을 용도에 따라 사용할 수 있다(제11조)."},{"기호":"ㄴ","판정":"틀림","설명":"전유부분 담보책임의 기간은 구분소유자에게 인도한 날부터 센다(제9조의2제2항제1호). 사용검사일은 공용부분의 기산점이다."},{"기호":"ㄷ","판정":"틀림","설명":"구조상 공용부분의 물권 득실변경은 등기가 필요 없다(제13조제3항)."},{"기호":"ㄹ","판정":"틀림","설명":"분양자는 구분소유자에 대해 담보책임을 진다(제9조제1항)."}],"개념":[{"종류":"표","제목":"담보책임의 당사자와 기간","머리":["쟁점","내용","조문"],"행":[["책임 주체","분양자와 시공자(구분소유자에 대해)","제9조제1항"],["준용","민법 제667조, 제668조","제9조제1항"],["특약","이 법·민법보다 매수인에게 불리한 특약은 무효","제9조제4항"],["전유부분 기산점","구분소유자에게 인도한 날","제9조의2제2항제1호"],["공용부분 기산점","사용검사일 또는 사용승인일","제9조의2제2항제2호"],["주요구조부·지반공사 하자","10년","제9조의2제1항제1호"]]}],"함정":"ㄴ에서 사용검사일을 전유부분 기산점으로 착각하기 쉽고, ㄹ은 분양자를 책임 없는 자로 바꿔 놓았다."},"31회-1차-080":{"한줄":"수탁자 乙이 丙에게 적법하게 양도했다가 다시 소유권을 취득해도 甲은 乙에게 소유물반환을 청구할 수 없다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제8조제2호","원문":"다음 각 호의 어느 하나에 해당하는 경우로서 조세 포탈, 강제집행의 면탈(免脫) 또는 법령상 제한의 회피를 목적으로 하지 아니하는 경우에는 제4조부터 제7조까지 및 제12조제1항부터 제3항까지를 적용하지 아니한다. 2. 배우자 명의로 부동산에 관한 물권을 등기한 경우"},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조","원문":"① 명의신탁약정은 무효로 한다. ② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다. ③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법령상 제한 회피 목적이므로 배우자 특례가 적용되지 않아 명의신탁은 무효다(제8조, 제4조). 소유권은 甲에게 남아 있어 말소를 청구할 수 있다."},{"번호":2,"판정":"옳음","설명":"약정이 무효이므로 약정의 해지를 원인으로 이전등기를 청구할 수 없다."},{"번호":3,"판정":"옳음","설명":"수탁자는 소유자가 아니므로 乙의 점유는 타주점유다."},{"번호":4,"판정":"옳음","설명":"제3자에게 무효를 대항할 수 없으므로 증여받은 丙도 소유권을 취득한다(제4조제3항)."},{"번호":5,"판정":"틀림","설명":"丙에게 적법하게 양도되는 순간 甲은 소유권을 잃었다(제4조제3항). 乙이 다시 취득한 소유권은 乙 자신의 것이어서 甲이 소유물반환을 청구할 수 없다."}],"개념":[{"종류":"표","제목":"양자간 명의신탁(무효)의 법률관계","머리":["쟁점","내용","근거"],"행":[["약정","무효","제4조제1항"],["수탁자 명의 등기","무효. 소유권은 신탁자에게 남음","제4조제2항"],["신탁자의 청구","소유권에 기한 말소, 진정명의회복","판례"],["명의신탁 해지 이전등기","불가","판례"],["수탁자 점유","타주점유","판례"],["수탁자가 제3자에게 처분","제3자 소유권 취득, 신탁자는 소유권 상실","제4조제3항"],["수탁자의 재취득","수탁자 고유 소유권. 신탁자의 반환 청구 불가","제4조제3항"]]}],"함정":"수탁자가 다시 취득했으니 원래 상태로 돌아와 甲의 소유라고 보기 쉽다. 제3자에게 넘어가는 순간 甲의 소유권은 없어졌다."},"31회-2차-004":{"한줄":"공장재단은 시행령 제2조의 대상이고 가압류된 토지와 미등기 건축물은 토지·정착물이어서 ㄱ, ㄷ, ㄹ이 정답이다.","근거":[{"법령":"공인중개사법","조문":"제3조","원문":"1. 토지 2. 건축물 그 밖의 토지의 정착물 3. 그 밖에 대통령령으로 정하는 재산권 및 물건"},{"법령":"공인중개사법 시행령","조문":"제2조","원문":"1. 「입목에 관한 법률」에 따른 입목 2. 「공장 및 광업재단 저당법」에 따른 공장재단 및 광업재단"},{"판례":"대법원 판례(영업용 비품·무형의 가치)","요지":"영업용 건물의 영업시설·비품 등 유형물이나 거래처, 신용 등 무형의 재산적 가치는 중개대상물이 아니다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ, ㄹ도 중개대상물이라 ㄱ만으로는 부족하다."},{"번호":2,"판정":"틀림","설명":"ㄴ은 중개대상물이 아니고 ㄷ, ㄹ이 빠져 있다."},{"번호":3,"판정":"옳음","설명":"ㄱ, ㄷ, ㄹ이 중개대상물에 해당한다."},{"번호":4,"판정":"틀림","설명":"ㄴ은 중개대상물이 아니고 ㄱ이 빠져 있다."},{"번호":5,"판정":"틀림","설명":"ㄴ이 중개대상물이 아니라서 네 보기 전부는 될 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"공장 및 광업재단 저당법에 따른 공장재단은 시행령 제2조제2호의 중개대상물이다."},{"기호":"ㄴ","판정":"틀림","설명":"영업시설·비품 등과 거래처, 신용 등은 중개대상물이 아니다."},{"기호":"ㄷ","판정":"옳음","설명":"가압류가 있어도 토지는 중개대상물이다(제3조제1호)."},{"기호":"ㄹ","판정":"옳음","설명":"미등기 건축물도 토지의 정착물로서 중개대상물이다(제3조제2호)."}],"개념":[{"종류":"표","제목":"중개대상물 해당 여부 모음","머리":["대상","해당 여부","근거"],"행":[["토지(토지거래허가구역 토지, 가압류된 토지 포함)","해당","제3조제1호"],["건축물·정착물(미등기 건축물, 주벽을 갖춘 신축 중 건물)","해당","제3조제2호"],["입목법상 입목, 공장재단·광업재단","해당","시행령 제2조"],["동·호수가 특정되어 분양계약이 체결된 아파트 분양권","해당","판례"],["입주권(추첨 신청으로 분양예정자가 될 지위), 대토권","비해당","판례"],["영업시설·비품, 거래처·신용·점포 위치의 이점 등 무형의 가치","비해당","판례"],["금전채권(피담보채권 포함)","비해당","판례"]]}],"함정":"ㄱ을 법령 범위 밖의 재산으로 보아 빼기 쉽다. 시행령 제2조가 입목, 공장재단, 광업재단을 중개대상물로 정한다. ㄷ, ㄹ은 권리 제한이나 미등기 때문에 제외하는 오류가 나온다."},"31회-2차-017":{"한줄":"소속공인중개사의 금지행위로 그 소속공인중개사가 징역형을 선고받아도 개업공인중개사에게는 해당 조의 벌금형만 부과되므로 ④가 틀리다.","근거":[{"법령":"공인중개사법","조문":"제15조제2항","원문":"소속공인중개사 또는 중개보조원의 업무상 행위는 그를 고용한 개업공인중개사의 행위로 본다."},{"법령":"공인중개사법","조문":"제25조제4항","원문":"제3항에 따른 확인ㆍ설명서에는 개업공인중개사(법인인 경우에는 대표자를 말하며, 법인에 분사무소가 설치되어 있는 경우에는 분사무소의 책임자를 말한다)가 서명 및 날인하되, 해당 중개행위를 한 소속공인중개사가 있는 경우에는 소속공인중개사가 함께 서명 및 날인하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"제5조제2항","원문":"제2조제4항, 제3조제2항ㆍ제4항 및 제4조제1항ㆍ제2항의 개업공인중개사의 위임을 받은 소속공인중개사(「공인중개사법」 제2조제5호에 따른 소속공인중개사를 말한다. 이하 같다)는 부동산거래계약 신고서 등의 제출을 대행할 수 있다."},{"법령":"공인중개사법","조문":"제30조제5항","원문":"개업공인중개사는 중개가 완성된 때에는 거래당사자에게 손해배상책임의 보장에 관한 다음 각 호의 사항을 설명하고 관계 증서의 사본을 교부하거나 관계 증서에 관한 전자문서를 제공하여야 한다."},{"법령":"공인중개사법","조문":"제50조","원문":"소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 중개업무에 관하여 제48조 또는 제49조의 규정에 해당하는 위반행위를 한 때에는 그 행위자를 벌하는 외에 그 개업공인중개사에 대하여도 해당 조에 규정된 벌금형을 과한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"소속공인중개사의 업무상 행위는 고용한 개업공인중개사의 행위로 본다(제15조제2항)."},{"번호":2,"판정":"옳음","설명":"확인·설명서에는 개업공인중개사가 서명 및 날인하고, 중개행위를 한 소속공인중개사가 함께 서명 및 날인한다(제25조제4항)."},{"번호":3,"판정":"옳음","설명":"개업공인중개사의 위임을 받은 소속공인중개사는 부동산거래계약 신고서 등의 제출을 대행할 수 있다(부동산 거래신고 등에 관한 법률 시행규칙 제5조제2항)."},{"번호":4,"판정":"틀림","설명":"양벌규정은 행위자를 벌하는 외에 개업공인중개사에게 해당 조에 규정된 벌금형을 과한다. 징역형은 과하지 않는다(제50조)."},{"번호":5,"판정":"옳음","설명":"중개가 완성되면 손해배상책임 보장 사항을 설명하고 관계 증서의 사본을 교부하거나 전자문서를 제공한다(제30조제5항)."}],"개념":[{"종류":"표","제목":"소속공인중개사·중개보조원과 개업공인중개사의 관계","머리":["사항","내용","조문"],"행":[["고용 신고","고용하거나 고용관계가 종료되면 등록관청에 신고","법 제15조제1항"],["업무상 행위","고용한 개업공인중개사의 행위로 봄","법 제15조제2항"],["중개보조원 수","개업공인중개사와 소속공인중개사 합산 수의 5배 초과 금지","법 제15조제3항"],["확인·설명서 서명·날인","개업공인중개사와 중개행위를 한 소속공인중개사","법 제25조제4항"],["양벌규정","행위자 처벌 외에 개업공인중개사에게 해당 조의 벌금형. 상당한 주의와 감독을 다했으면 면책","법 제50조"],["신고서 제출 대행","개업공인중개사의 위임을 받은 소속공인중개사 가능","거래신고법 시행규칙 제5조제2항"]]}],"함정":"소속공인중개사의 행위가 개업공인중개사의 행위로 간주된다(①)는 점에서 징역형도 함께 받는다고 확장해 버리기 쉽다. 처벌은 별개로, 개업공인중개사에게는 벌금형만 과해지고 주의·감독을 다했다면 그마저도 면한다."},"31회-2차-018":{"한줄":"법정 한도를 초과한 중개보수를 받는 행위는 조례를 잘못 해석했더라도 제33조의 금지행위에 해당하므로 ③이 틀리다.","근거":[{"법령":"공인중개사법","조문":"제32조제1항","원문":"개업공인중개사는 중개업무에 관하여 중개의뢰인으로부터 소정의 보수를 받는다. 다만, 개업공인중개사의 고의 또는 과실로 인하여 중개의뢰인간의 거래행위가 무효ㆍ취소 또는 해제된 경우에는 그러하지 아니하다."},{"법령":"공인중개사법","조문":"제32조제4항","원문":"주택(부속토지를 포함한다. 이하 이 항에서 같다)의 중개에 대한 보수와 제2항에 따른 실비의 한도 등에 관하여 필요한 사항은 국토교통부령으로 정하는 범위 안에서 특별시ㆍ광역시ㆍ도 또는 특별자치도(이하 \"시ㆍ도\"라 한다)의 조례로 정하고, 주택 외의 중개대상물의 중개에 대한 보수는 국토교통부령으로 정한다."},{"법령":"공인중개사법","조문":"제33조제1항제3호","원문":"사례ㆍ증여 그 밖의 어떠한 명목으로도 제32조에 따른 보수 또는 실비를 초과하여 금품을 받는 행위"},{"법령":"공인중개사법 시행령","조문":"제27조의2","원문":"법 제32조제3항에 따른 중개보수의 지급시기는 개업공인중개사와 중개의뢰인간의 약정에 따르되, 약정이 없을 때에는 중개대상물의 거래대금 지급이 완료된 날로 한다."},{"판례":"대법원 판례(한도 초과 중개보수 약정)","요지":"공인중개사법령이 정한 한도를 초과하는 중개보수 약정은 한도를 초과하는 범위 내에서 무효다."}],"선지":[{"번호":1,"판정":"옳음","설명":"개업공인중개사의 고의·과실로 거래행위가 무효·취소·해제된 경우에만 보수를 받지 못한다. 고의·과실이 없으면 받을 수 있다(제32조제1항 단서)."},{"번호":2,"판정":"옳음","설명":"주택은 국토교통부령 범위 안에서 시·도 조례, 주택 외는 국토교통부령으로 정한다(제32조제4항)."},{"번호":3,"판정":"틀림","설명":"사례·증여 그 밖의 어떠한 명목으로도 제32조에 따른 보수를 초과하여 금품을 받는 행위는 금지행위다(제33조제1항제3호). 조례를 잘못 해석했다는 사정이 있어도 초과 수령이라는 사실은 달라지지 않는다."},{"번호":4,"판정":"옳음","설명":"한도를 초과하는 약정은 초과하는 범위 내에서 무효다."},{"번호":5,"판정":"옳음","설명":"약정이 없으면 거래대금 지급이 완료된 날이다(시행령 제27조의2)."}],"개념":[{"종류":"표","제목":"중개보수 수령의 효과","머리":["상황","결과","조문"],"행":[["거래행위가 무효·취소·해제됨(개업공인중개사 고의·과실 없음)","보수를 받을 수 있음","법 제32조제1항 단서"],["거래행위가 무효·취소·해제됨(개업공인중개사 고의·과실 있음)","보수를 받을 수 없음","법 제32조제1항 단서"],["법정 한도를 초과한 약정","초과 범위 내 무효","판례"],["법정 한도를 초과하여 금품 수령","금지행위(제33조제1항제3호), 1년 이하 징역 또는 1천만원 이하 벌금","법 제33조, 제49조제1항제10호"],["지급시기","약정 우선, 없으면 거래대금 지급 완료일","시행령 제27조의2"]]}],"함정":"조례를 잘못 읽은 경우라 위법의 인식이 없어 금지행위에서 빠진다고 생각하기 쉽다. 금지행위 규정은 한도를 넘어 금품을 받은 행위 자체를 대상으로 한다."},"31회-2차-039":{"한줄":"주택 면적이 3분의 1이라 주택 외 규정이 적용되고 매매와 임대차가 동일 기회에 이루어졌으므로 매매 거래금액만 적용하며 乙과 丙에게서 각각 받을 수 있어 ㄱ, ㄷ이 옳다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제20조제6항","원문":"중개대상물인 건축물 중 주택의 면적이 2분의 1이상인 경우에는 제1항의 규정을 적용하고, 주택의 면적이 2분의 1미만인 경우에는 제4항의 규정을 적용한다."},{"법령":"공인중개사법 시행규칙","조문":"제20조제4항제2호","원문":"제1호 외의 경우: 중개의뢰인 쌍방으로부터 각각 받되, 거래금액의 1천분의 9 이내에서 중개의뢰인과 개업공인중개사가 서로 협의하여 결정한다."},{"법령":"공인중개사법 시행규칙","조문":"제20조제5항제3호","원문":"동일한 중개대상물에 대하여 동일 당사자간에 매매를 포함한 둘 이상의 거래가 동일 기회에 이루어지는 경우에는 매매계약에 관한 거래금액만을 적용한다."},{"법령":"공인중개사법","조문":"제32조제4항","원문":"주택(부속토지를 포함한다. 이하 이 항에서 같다)의 중개에 대한 보수와 제2항에 따른 실비의 한도 등에 관하여 필요한 사항은 국토교통부령으로 정하는 범위 안에서 특별시ㆍ광역시ㆍ도 또는 특별자치도(이하 \"시ㆍ도\"라 한다)의 조례로 정하고, 주택 외의 중개대상물의 중개에 대한 보수는 국토교통부령으로 정한다."},{"법령":"공인중개사법 시행규칙","조문":"제20조제3항","원문":"제1항 및 제2항의 경우에 중개대상물의 소재지와 중개사무소의 소재지가 다른 경우에는 개업공인중개사는 중개사무소의 소재지를 관할하는 시ㆍ도의 조례에서 정한 기준에 따라 중개보수 및 실비를 받아야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ도 옳아서 ㄷ만으로는 부족하다."},{"번호":2,"판정":"옳음","설명":"ㄱ, ㄷ이 옳다."},{"번호":3,"판정":"틀림","설명":"ㄴ, ㄹ은 틀린 보기다."},{"번호":4,"판정":"틀림","설명":"ㄴ은 틀린 보기라 들어갈 수 없다."},{"번호":5,"판정":"틀림","설명":"ㄴ, ㄹ은 틀린 보기이고 ㄷ이 빠져 있다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"주택 외 규정은 중개의뢰인 쌍방으로부터 각각 받는다(규칙 제20조제4항제2호). 乙과 丙에게서 각각 받을 수 있다."},{"기호":"ㄴ","판정":"틀림","설명":"주택 외 중개대상물의 보수는 시·도 조례가 아니라 국토교통부령으로 정한다(제32조제4항). 소재지가 다를 때 중개사무소 소재지 시·도 조례를 따르는 것은 주택의 경우다(규칙 제20조제3항)."},{"기호":"ㄷ","판정":"옳음","설명":"동일 대상물, 동일 당사자, 동일 기회에 매매를 포함한 둘 이상의 거래가 이루어지면 매매계약 거래금액만 적용한다(규칙 제20조제5항제3호)."},{"기호":"ㄹ","판정":"틀림","설명":"주택 면적이 2분의 1 미만이면 주택 외 규정(제4항)을 적용한다(규칙 제20조제6항)."}],"개념":[{"종류":"흐름","제목":"중개보수 적용 규정 판단","단계":[{"이름":"대상물 구분","설명":"주택(부속토지 포함)인지, 건축물 중 주택이 일부인지, 그 밖의 대상물인지 구분"},{"이름":"주택 면적 비율","설명":"건축물 중 주택 면적이 2분의 1 이상이면 주택 규정(제20조제1항), 2분의 1 미만이면 주택 외 규정(제20조제4항)"},{"이름":"주택 규정","설명":"별표 1 상한요율·한도액 범위 안에서 시·도 조례로 요율한도 결정. 소재지가 다르면 중개사무소 소재지 시·도 조례"},{"이름":"주택 외 규정","설명":"오피스텔(전용 85제곱미터 이하, 입식 부엌·수세식 화장실·목욕시설)은 별표 2, 그 밖에는 거래금액의 1천분의 9 이내"},{"이름":"거래금액 계산","설명":"동일 기회에 매매를 포함한 둘 이상의 거래는 매매 거래금액만 적용"}]},{"종류":"표","제목":"주택 외 중개보수 상한","머리":["대상","상한","조문"],"행":[["오피스텔(요건 충족) 매매·교환","거래금액의 1천분의 5","규칙 별표 2"],["오피스텔(요건 충족) 임대차 등","거래금액의 1천분의 4","규칙 별표 2"],["그 밖의 주택 외(상가·토지·요건 미충족 오피스텔 등)","거래금액의 1천분의 9 이내에서 협의","규칙 제20조제4항제2호"],["주택 면적 2분의 1 미만 건축물","주택 외 규정 적용","규칙 제20조제6항"]]}],"함정":"주택이 포함되어 있으니 주택 규정이라고 보는 ㄹ이 가장 흔한 오답이다. 주택 면적이 2분의 1에 미치지 못하면 건물 전체에 주택 외 규정이 적용된다. ㄴ도 주택의 소재지 규정과 섞어 놓은 선지다."},"31회-2차-021":{"한줄":"국토교통부장관, 시·도지사, 등록관청은 교육 관련 조사·연구에 필요한 비용을 지원할 수 있으므로(법 제34조의2제1항, 영 제28조의2제1항제3호) ④가 옳다.","근거":[{"법령":"공인중개사법","조문":"법 제34조의2제1항","원문":"국토교통부장관, 시ㆍ도지사 및 등록관청은 개업공인중개사등이 부동산거래사고 예방 등을 위하여 교육을 받는 경우에는 대통령령으로 정하는 바에 따라 필요한 비용을 지원할 수 있다."},{"법령":"공인중개사법 시행령","조문":"영 제28조의2제1항제3호","원문":"교육 관련 조사 및 연구에 필요한 비용"},{"법령":"공인중개사법 시행령","조문":"영 제13조제1항제2호라목","원문":"대표자, 임원 또는 사원 전원 및 분사무소의 책임자(법 제13조제3항에 따라 분사무소를 설치하려는 경우에만 해당한다)가 법 제34조제1항에 따른 실무교육을 받았을 것"},{"법령":"공인중개사법 시행령","조문":"영 제28조제1항제2호","원문":"교육시간: 45시간"},{"법령":"공인중개사법 시행령","조문":"영 제28조제2항제1호","원문":"교육내용: 중개보조원의 직무수행에 필요한 직업윤리 등"},{"법령":"공인중개사법","조문":"법 제34조제4항","원문":"제1항 및 제2항에 따른 실무교육을 받은 개업공인중개사 및 소속공인중개사는 실무교육을 받은 후 2년마다 시ㆍ도지사가 실시하는 연수교육을 받아야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"법인이 개설등록을 신청할 때는 사원·임원 전원이 실무교육을 받는다(법 제34조제1항, 영 제13조제1항제2호라목). 공인중개사가 아닌 사원도 대상이다."},{"번호":2,"판정":"틀림","설명":"실무교육 시간은 45시간이다(영 제28조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"중개보조원이 받는 교육은 직무교육이고 내용은 직업윤리 등이다(영 제28조제2항제1호). 법·제도 변경사항은 연수교육 내용이다(영 제28조제3항제1호)."},{"번호":4,"판정":"옳음","설명":"교육 관련 조사 및 연구에 필요한 비용은 지원 대상 비용이다(영 제28조의2제1항제3호)."},{"번호":5,"판정":"틀림","설명":"연수교육은 시·도지사가 실시한다(법 제34조제4항). 국토교통부장관이 실시하지 않는다."}],"개념":[{"종류":"표","제목":"개업공인중개사등의 교육","머리":["구분","대상","시기","시간","실시"],"행":[["실무교육","개설등록 신청자(법인은 사원·임원, 분사무소는 책임자), 소속공인중개사","등록신청일·분사무소 신고일·고용 신고일 전 1년 이내","45시간","시·도지사"],["직무교육","중개보조원","고용 신고일 전 1년 이내","3시간 이상 4시간 이하","시·도지사 또는 등록관청"],["연수교육","실무교육을 받은 개업공인중개사·소속공인중개사","실무교육을 받은 후 2년마다","12시간 이상 16시간 이하","시·도지사(2년이 되기 2개월 전까지 일시·장소·내용 통지)"],["부동산거래사고 예방교육","개업공인중개사등","필요하다고 인정할 때","-","국토교통부장관·시·도지사·등록관청(교육일 10일 전까지 공고·통지)"]]},{"종류":"표","제목":"교육비 지원 대상 비용(영 제28조의2제1항)","머리":["호","비용"],"행":[["1","교육시설 및 장비의 설치에 필요한 비용"],["2","교육자료의 개발 및 보급에 필요한 비용"],["3","교육 관련 조사 및 연구에 필요한 비용"],["4","교육 실시에 따른 강사비"]]}],"함정":"①은 공인중개사가 아닌 사원을 교육 대상에서 빼 놓아 옳게 보인다. 법인은 사원·임원 전원이다. ③은 중개보조원 교육의 내용에 연수교육 내용을 붙였다. ⑤는 연수교육의 실시 주체를 국토교통부장관으로 바꿨다.","개정":"실무교육 시간은 영 제28조제1항제2호에서 45시간으로 개정되었다(2025.10.21). ②의 26시간 이상 32시간 이하는 현행 시간과 맞지 않는다."},"31회-2차-005":{"한줄":"다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 한 경우는 자격정지가 아니라 자격취소 사유(법 제35조제1항제2호)이므로 ④가 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제35조제1항제2호","원문":"제7조제1항의 규정을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도 또는 대여한 경우"},{"법령":"공인중개사법","조문":"법 제10조제2항","원문":"제1항제1호부터 제11호까지의 어느 하나에 해당하는 자는 소속공인중개사 또는 중개보조원이 될 수 없다."},{"법령":"공인중개사법","조문":"법 제10조제1항제7호","원문":"제36조제1항에 따라 공인중개사의 자격이 정지된 자로서 자격정지기간중에 있는 자"},{"법령":"공인중개사법","조문":"법 제7조제1항","원문":"공인중개사는 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 자기의 공인중개사자격증을 양도 또는 대여하여서는 아니된다."},{"법령":"공인중개사법","조문":"법 제8조","원문":"공인중개사가 아닌 자는 공인중개사 또는 이와 유사한 명칭을 사용하지 못한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"자격이 취소된 후 3년이 지나지 않은 자는 결격사유(제10조제1항제6호)에 해당해 소속공인중개사·중개보조원이 될 수 없다(제10조제2항)."},{"번호":2,"판정":"옳음","설명":"법 제7조제1항은 대가 유무를 구분하지 않고 자격증의 양도·대여를 금지한다. 무상으로도 대여할 수 없다."},{"번호":3,"판정":"옳음","설명":"자격정지는 정지기간 중에 있는 자만 결격사유다(제10조제1항제7호). 자격정지처분을 받은 날부터 6개월이 경과하면 정지기간이 끝나 법인의 임원이 될 수 있다."},{"번호":4,"판정":"틀림","설명":"자기의 성명을 사용하여 중개업무를 하게 한 경우는 자격취소 사유다(법 제35조제1항제2호). 자격정지 사유가 아니다."},{"번호":5,"판정":"옳음","설명":"공인중개사가 아닌 자는 공인중개사 또는 이와 유사한 명칭을 사용하지 못한다(법 제8조)."}],"개념":[{"종류":"비교","제목":"자격취소 사유와 자격정지 사유","왼쪽":{"이름":"자격취소(법 제35조)","항목":["부정한 방법으로 자격 취득","성명 사용 허락, 자격증 양도·대여","자격정지 중 중개업무(다른 개업공인중개사의 소속이 되는 경우 포함)","이 법 또는 직무 관련 형법 위반으로 금고 이상 형 선고(집행유예 포함)","처분권자 시·도지사, 청문 필수"]},"오른쪽":{"이름":"자격정지(법 제36조)","항목":["둘 이상의 중개사무소 소속","인장등록 위반","확인·설명 불성실, 서명·날인 누락","거래계약서 거짓 기재, 이중 계약서","제33조제1항 금지행위","6개월의 범위, 소속공인중개사로서 업무를 수행하는 기간 중"]}},{"종류":"표","제목":"개설등록 결격사유(법 제10조제1항)","머리":["호","결격사유"],"행":[["1","미성년자"],["2","피성년후견인 또는 피한정후견인"],["3","파산선고를 받고 복권되지 아니한 자"],["4","금고 이상의 실형 선고 후 집행 종료(면제)일부터 3년이 지나지 아니한 자"],["5","금고 이상의 형의 집행유예를 받고 그 유예기간이 만료된 날부터 2년이 지나지 아니한 자"],["6","공인중개사 자격이 취소된 후 3년이 지나지 아니한 자"],["7","자격정지기간 중에 있는 자"],["8","일정한 사유로 개설등록이 취소된 후 3년이 지나지 아니한 자"],["9","업무정지처분을 받고 폐업신고를 한 자로서 업무정지기간이 지나지 아니한 자"],["10","업무정지처분을 받은 법인의 사유 발생 당시 사원·임원이었던 자로서 업무정지기간이 지나지 아니한 자"],["11","이 법을 위반하여 300만원 이상의 벌금형을 선고받고 3년이 지나지 아니한 자"],["12","사원 또는 임원 중 제1호부터 제11호까지에 해당하는 자가 있는 법인"]]}],"함정":"자격정지 사유 일곱 가지(제36조제1항)에는 성명 사용 허락이 없다. 자격증 양도·대여와 같은 조항(제7조제1항)이라 자격취소로 간다. ③은 자격정지가 기간 중에만 결격이라는 점을 몰라 틀렸다고 판단하기 쉽다."},"31회-2차-024":{"한줄":"성명 사용 허락(ㄱ)과 이 법 위반 징역형 집행유예(ㄴ)는 자격취소 사유이고, 거래계약서 거짓 기재(ㄷ)와 중개대상물 매매업(ㄹ)은 자격정지 사유여서 네 보기가 모두 옳다.","근거":[{"법령":"공인중개사법","조문":"법 제35조제1항제2호","원문":"제7조제1항의 규정을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도 또는 대여한 경우"},{"법령":"공인중개사법","조문":"법 제35조제1항제4호","원문":"이 법 또는 공인중개사의 직무와 관련하여 「형법」 제114조, 제231조, 제234조, 제347조, 제355조 또는 제356조를 위반하여 금고 이상의 형(집행유예를 포함한다)을 선고받은 경우"},{"법령":"공인중개사법","조문":"법 제36조제1항제6호","원문":"제26조제3항의 규정을 위반하여 거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우"},{"법령":"공인중개사법","조문":"법 제36조제1항제7호","원문":"제33조제1항 각 호에 규정된 금지행위를 한 경우"},{"법령":"공인중개사법","조문":"법 제33조제1항제1호","원문":"제3조에 따른 중개대상물의 매매를 업으로 하는 행위"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄴ, ㄷ, ㄹ도 옳은 보기라 ㄱ만 고른 조합은 부족하다."},{"번호":2,"판정":"틀림","설명":"ㄴ, ㄷ도 옳은 보기라 ㄱ, ㄹ만 고른 조합은 부족하다."},{"번호":3,"판정":"틀림","설명":"ㄱ, ㄴ도 옳은 보기라 ㄷ, ㄹ만 고른 조합은 부족하다."},{"번호":4,"판정":"틀림","설명":"ㄹ도 옳은 보기라 ㄱ, ㄴ, ㄷ만 고른 조합은 부족하다."},{"번호":5,"판정":"옳음","설명":"ㄱ, ㄴ, ㄷ, ㄹ이 모두 옳아 이 조합이 맞다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"자기의 성명을 사용하여 중개업무를 하게 한 경우는 자격취소 사유다(법 제35조제1항제2호)."},{"기호":"ㄴ","판정":"옳음","설명":"이 법을 위반하여 금고 이상의 형(집행유예 포함)을 선고받은 경우는 자격취소 사유다(법 제35조제1항제4호)."},{"기호":"ㄷ","판정":"옳음","설명":"거래계약서에 거래내용을 거짓으로 기재한 경우는 자격정지 사유다(법 제36조제1항제6호)."},{"기호":"ㄹ","판정":"옳음","설명":"중개대상물의 매매를 업으로 하는 행위는 제33조제1항제1호 금지행위이고 금지행위는 자격정지 사유다(법 제36조제1항제7호)."}],"개념":[{"종류":"비교","제목":"자격취소 사유와 자격정지 사유","왼쪽":{"이름":"자격취소(법 제35조)","항목":["부정한 방법으로 자격 취득","성명 사용 허락, 자격증 양도·대여","자격정지 중 중개업무(다른 개업공인중개사의 소속이 되는 경우 포함)","이 법 또는 직무 관련 형법 위반으로 금고 이상 형 선고(집행유예 포함)","처분권자 시·도지사, 청문 필수"]},"오른쪽":{"이름":"자격정지(법 제36조)","항목":["둘 이상의 중개사무소 소속","인장등록 위반","확인·설명 불성실, 서명·날인 누락","거래계약서 거짓 기재, 이중 계약서","제33조제1항 금지행위","6개월의 범위, 소속공인중개사로서 업무를 수행하는 기간 중"]}},{"종류":"표","제목":"공인중개사 자격취소 사유(법 제35조제1항)","머리":["호","사유"],"행":[["1","부정한 방법으로 공인중개사의 자격을 취득한 경우"],["2","다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도·대여한 경우"],["3","자격정지처분을 받고 그 정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인인 개업공인중개사의 사원·임원이 되는 경우 포함)"],["4","이 법 또는 공인중개사의 직무와 관련하여 형법 제114조, 제231조, 제234조, 제347조, 제355조 또는 제356조를 위반하여 금고 이상의 형(집행유예 포함)을 선고받은 경우"]]}],"함정":"매매업(ㄹ)은 중대해 보여 자격취소로 착각하기 쉽다. 제33조제1항 금지행위는 한꺼번에 자격정지(제36조제1항제7호)로 간다. ㄴ은 집행유예도 금고 이상의 형에 포함된다는 점에서 취소 사유다."},"31회-2차-029":{"한줄":"2019. 1. 8. 위반 후 2019. 3. 5. 폐업, 2019. 12. 5. 재등록이면 폐업기간이 9개월로 1년 이하라 업무정지 사유 위반행위에 대해 1월의 업무정지처분을 받을 수 있으므로 ④가 옳다.","근거":[{"법령":"공인중개사법","조문":"법 제40조제3항제2호","원문":"폐업신고 전의 위반행위에 대한 행정처분이 업무정지에 해당하는 경우로서 폐업기간이 1년을 초과한 경우"},{"법령":"공인중개사법","조문":"법 제40조제3항제1호","원문":"폐업신고를 한 날부터 다시 중개사무소의 개설등록을 한 날까지의 기간(이하 제2호에서 \"폐업기간\"이라 한다)이 3년을 초과한 경우"},{"법령":"공인중개사법","조문":"법 제40조제2항","원문":"제1항의 경우 폐업신고 전의 개업공인중개사에 대하여 제39조제1항 각 호, 제51조제1항 각 호, 같은 조 제2항 각 호 및 같은 조 제3항 각 호의 위반행위를 사유로 행한 행정처분의 효과는 그 처분일부터 1년간 다시 중개사무소의 개설등록을 한 자(이하 이 조에서 \"재등록 개업공인중개사\"라 한다)에게 승계된다."},{"법령":"공인중개사법","조문":"법 제21조제1항","원문":"개업공인중개사는 3개월을 초과하는 휴업(중개사무소의 개설등록 후 업무를 개시하지 아니하는 경우를 포함한다. 이하 같다), 폐업 또는 휴업한 중개업을 재개하고자 하는 때에는 등록관청에 그 사실을 신고하여야 한다. 휴업기간을 변경하고자 하는 때에도 또한 같다."},{"법령":"공인중개사법","조문":"법 제21조의2제2항","원문":"등록관청은 제1항에 따른 간판의 철거를 개업공인중개사가 이행하지 아니하는 경우에는 「행정대집행법」에 따라 대집행을 할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"폐업은 등록관청에 신고한다(법 제21조제1항). 국토교통부장관이 아니다."},{"번호":2,"판정":"틀림","설명":"폐업신고 후 간판을 철거하지 않으면 등록관청이 행정대집행으로 철거할 수 있다(법 제21조의2제2항). 과태료 부과 사유로 열거되어 있지 않다(법 제51조)."},{"번호":3,"판정":"틀림","설명":"2019. 2. 8. 처분 후 2019. 12. 11. 재등록은 약 10개월 만이라 처분일부터 1년 안이다. 따라서 업무정지처분의 효과가 승계된다(법 제40조제2항)."},{"번호":4,"판정":"옳음","설명":"폐업기간 2019. 3. 5.~2019. 12. 5.는 9개월로 1년 이하이므로 업무정지에 해당하는 위반행위로 처분할 수 있다(법 제40조제3항제2호)."},{"번호":5,"판정":"틀림","설명":"폐업기간 2018. 3. 6.~2020. 10. 16.은 2년 7개월 남짓으로 3년 이하이므로 등록취소 사유 위반행위로 취소처분을 할 수 있다(법 제40조제3항제1호)."}],"개념":[{"종류":"계산","제목":"폐업기간·승계기간 계산","단계":[{"설명":"④ 폐업기간(업무정지 해당 위반): 폐업신고 2019.3.5 ~ 재등록 2019.12.5","식":"12월 5일 - 3월 5일","값":"9개월 (1년 이하 → 처분 가능)"},{"설명":"⑤ 폐업기간(등록취소 해당 위반): 2018.3.6 ~ 2020.10.16","식":"2년 7개월 10일","값":"3년 이하 → 처분 가능"},{"설명":"③ 처분 효과 승계: 처분일 2019.2.8 ~ 재등록 2019.12.11","식":"10개월 3일","값":"1년 이내 → 승계"}]},{"종류":"표","제목":"행정제재처분효과의 승계(법 제40조)","머리":["구분","내용"],"행":[["지위 승계","폐업신고 후 다시 개설등록을 하면 폐업신고 전 개업공인중개사의 지위를 승계(동일인 재등록의 경우)"],["처분 효과의 승계","폐업신고 전 업무정지·과태료 처분의 효과는 그 처분일부터 1년간 재등록 개업공인중개사에게 승계"],["위반행위에 대한 처분","재등록 개업공인중개사에게 폐업신고 전의 등록취소·업무정지 사유 위반행위로 처분 가능"],["처분 불가 1","폐업기간(폐업신고일~재등록일)이 3년을 초과한 경우"],["처분 불가 2","폐업신고 전 위반행위에 대한 처분이 업무정지에 해당하는 경우로서 폐업기간이 1년을 초과한 경우"],["처분 시 고려","폐업기간과 폐업의 사유 등을 고려"],["법인","법인의 대표자에 관하여 준용(개업공인중개사는 법인의 대표자로 봄)"]]}],"함정":"③은 승계 기간 1년, ④와 ⑤는 폐업기간 1년·3년이라는 서로 다른 기준을 같은 문제에서 묻는다. 날짜를 정확히 빼서 비교한다. ②는 간판 철거 불이행에 과태료가 아닌 대집행 규정이 있다는 점을 놓치기 쉽다."},"31회-2차-025":{"한줄":"무등록 중개업(ㄱ), 거짓 등록(ㄴ), 둘 이상의 중개사무소(ㄷ), 임시 중개시설물(ㄹ)은 벌금 부과 대상이고 존재하지 않는 중개대상물을 광고한 ㅁ은 과태료 대상이라 ④가 정답이다.","근거":[{"법령":"공인중개사법","조문":"법 제48조제1호","원문":"제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 한 자"},{"법령":"공인중개사법","조문":"법 제48조제2호","원문":"거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 자"},{"법령":"공인중개사법","조문":"법 제49조제1항제4호","원문":"제13조제1항의 규정을 위반하여 둘 이상의 중개사무소를 둔 자"},{"법령":"공인중개사법","조문":"법 제49조제1항제5호","원문":"제13조제2항의 규정을 위반하여 임시 중개시설물을 설치한 자"},{"법령":"공인중개사법","조문":"법 제51조제2항제1호","원문":"제18조의2제4항 각 호를 위반하여 부당한 표시ㆍ광고를 한 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄴ, ㄷ, ㄹ도 벌금 부과 대상이라 ㄱ만 고른 조합은 부족하다."},{"번호":2,"판정":"틀림","설명":"ㄷ, ㄹ도 벌금 부과 대상이라 ㄱ, ㄴ만 고른 조합은 부족하다."},{"번호":3,"판정":"틀림","설명":"ㅁ은 과태료 대상이고 ㄱ, ㄹ이 빠졌다."},{"번호":4,"판정":"옳음","설명":"ㄱ, ㄴ, ㄷ, ㄹ이 벌금 대상이고 ㅁ만 과태료 대상이어서 이 조합이 맞다."},{"번호":5,"판정":"틀림","설명":"ㅁ은 벌금이 아니라 과태료 대상이므로 다섯 보기를 모두 고르면 맞지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"중개사무소 개설등록 없이 중개업을 한 자는 3년 이하 징역 또는 3천만원 이하 벌금이다(법 제48조제1호)."},{"기호":"ㄴ","판정":"옳음","설명":"거짓이나 그 밖의 부정한 방법으로 개설등록을 한 자는 3년 이하 징역 또는 3천만원 이하 벌금이다(법 제48조제2호)."},{"기호":"ㄷ","판정":"옳음","설명":"등록관청 관할 구역 안에 둘 이상의 중개사무소를 둔 자는 1년 이하 징역 또는 1천만원 이하 벌금이다(법 제49조제1항제4호)."},{"기호":"ㄹ","판정":"옳음","설명":"임시 중개시설물을 설치한 자는 1년 이하 징역 또는 1천만원 이하 벌금이다(법 제49조제1항제5호)."},{"기호":"ㅁ","판정":"틀림","설명":"존재하지 않아 거래할 수 없는 중개대상물을 광고한 개업공인중개사는 과태료 대상이다(법 제51조제2항제1호, 제18조의2제4항제1호)."}],"개념":[{"종류":"표","제목":"벌칙 정리(법 제48조·제49조)","머리":["형량","행위","조문"],"행":[["3년 이하 징역 또는 3천만원 이하 벌금","무등록 중개업, 거짓·부정한 방법의 개설등록","법 제48조제1호·제2호"],["3년 이하 징역 또는 3천만원 이하 벌금","제33조제1항제5호~제9호 금지행위(증서 등 중개, 직접 거래·쌍방 대리, 투기 조장, 시세 부당 영향, 단체 중개 제한)","법 제48조제3호"],["3년 이하 징역 또는 3천만원 이하 벌금","제33조제2항의 업무방해","법 제48조제4호"],["1년 이하 징역 또는 1천만원 이하 벌금","자격증 양도·대여·양수 및 성명 사용 허락, 그 알선","법 제49조제1항제1호·제1호의2"],["1년 이하 징역 또는 1천만원 이하 벌금","개업공인중개사 등록증 양도·대여, 성명·상호 사용 허락, 그 알선","법 제49조제1항제7호·제7호의2"],["1년 이하 징역 또는 1천만원 이하 벌금","이중등록·이중소속, 둘 이상의 중개사무소, 임시 중개시설물, 중개보조원 고용 상한 초과","법 제49조제1항제3호~제5호의2"],["1년 이하 징역 또는 1천만원 이하 벌금","공인중개사·공인중개사사무소·부동산중개 유사명칭 사용, 개업공인중개사가 아닌 자의 중개대상물 표시·광고","법 제49조제1항제2호·제6호·제6호의2"],["1년 이하 징역 또는 1천만원 이하 벌금","거래정보사업자의 의뢰받지 않은 정보 공개, 업무상 비밀누설(피해자 의사에 반하여 벌하지 않음)","법 제49조제1항제8호·제9호, 제2항"],["1년 이하 징역 또는 1천만원 이하 벌금","제33조제1항제1호~제4호 금지행위(매매업, 무등록업자와 거래, 보수 초과 수수, 거짓 언행)","법 제49조제1항제10호"]]},{"종류":"표","제목":"과태료 부과·징수권자(법 제51조제5항)","머리":["부과권자","과태료 사유","조문"],"행":[["국토교통부장관","인터넷 광고 모니터링 자료 제출·조치 요구 불이행, 부동산거래정보망 운영규정 위반, 거래정보사업자의 보고·검사 거부, 공제사업 운용실적 미공시, 공제 개선명령 불이행, 임원 징계·해임 요구 불이행, 협회 조사·검사 거부","제2항제1호의2·제1호의3·제1호의5·제6호~제8호·제8호의2·제9호"],["시·도지사","연수교육 미이수, 공인중개사자격증 미반납·사유서 미제출","제2항제5호의2, 제3항제6호"],["등록관청","부당 표시·광고, 중개보조원 신분 미고지, 확인·설명 불성실, 등록증 미게시, 사무소 명칭 위반, 표시·광고 위반, 이전신고·휴업·폐업·재개·휴업기간 변경 미신고, 손해배상책임 설명·증서 교부 위반, 등록증 미반납","제2항제1호·제1호의4·제1호의6, 제3항제1호~제5호·제7호"]]}],"함정":"ㅁ(존재하지 않는 중개대상물 광고)은 허위 광고라 형사처벌처럼 보이지만 개업공인중개사의 부당 표시·광고는 과태료다(제51조제2항제1호, 영 별표 2 가목 1) 500만원). 반대로 개업공인중개사가 아닌 자의 광고는 벌칙이다."},"31회-2차-002":{"한줄":"합명회사 같은 법인이 개설등록을 하려면 사원 전원이 실무교육을 받아야 한다(영 제13조제1항제2호라목).","근거":[{"법령":"공인중개사법 시행령","조문":"영 제13조제1항제2호라목","원문":"라. 대표자, 임원 또는 사원 전원 및 분사무소의 책임자(법 제13조제3항에 따라 분사무소를 설치하려는 경우에만 해당한다)가 법 제34조제1항에 따른 실무교육을 받았을 것"},{"법령":"공인중개사법 시행령","조문":"영 제13조제1항제2호가목","원문":"가. 「상법」상 회사 또는 「협동조합 기본법」 제2조제1호에 따른 협동조합(같은 조 제3호에 따른 사회적협동조합은 제외한다)으로서 자본금이 5천만원 이상일 것"},{"법령":"공인중개사법 시행령","조문":"영 제13조제1항제2호다목","원문":"다. 대표자는 공인중개사이어야 하며, 대표자를 제외한 임원 또는 사원(합명회사 또는 합자회사의 무한책임사원을 말한다. 이하 이 조에서 같다)의 3분의 1 이상은 공인중개사일 것"},{"법령":"공인중개사법","조문":"법 제9조제2항","원문":"공인중개사(소속공인중개사는 제외한다) 또는 법인이 아닌 자는 제1항에 따라 중개사무소의 개설등록을 신청할 수 없다."},{"법령":"공인중개사법 시행령","조문":"영 제13조제1항제2호마목","원문":"마. 건축물대장에 기재된 건물에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)할 것"}],"선지":[{"번호":1,"판정":"옳음","설명":"대표자, 임원 또는 사원 전원이 실무교육을 받아야 한다(영 제13조제1항제2호라목)."},{"번호":2,"판정":"틀림","설명":"협동조합은 자본금이 5천만원 이상이어야 하고 사회적협동조합은 제외된다(영 제13조제1항제2호가목)."},{"번호":3,"판정":"틀림","설명":"공인중개사 비율은 대표자를 \"제외한\" 임원 또는 사원의 3분의 1 이상이다(영 제13조제1항제2호다목)."},{"번호":4,"판정":"틀림","설명":"법인이 아닌 자는 개설등록을 신청할 수 없다. 법인 아닌 사단도 같다(법 제9조제2항)."},{"번호":5,"판정":"틀림","설명":"사용권은 소유 외에 전세·임대차·사용대차 등으로도 확보할 수 있다(영 제13조제1항제2호마목)."}],"개념":[{"종류":"표","제목":"중개사무소 개설등록 기준(영 제13조제1항)","머리":["구분","공인중개사","법인"],"행":[["자본금","요건 없음","상법상 회사 또는 협동조합(사회적협동조합 제외)으로서 5천만원 이상"],["업무 범위","-","법 제14조에 규정된 업무만 영위할 목적으로 설립"],["공인중개사 요건","본인이 공인중개사","대표자는 공인중개사, 대표자를 제외한 임원·사원의 3분의 1 이상이 공인중개사"],["실무교육","본인","대표자·임원·사원 전원, 분사무소를 설치하려면 분사무소 책임자도 포함"],["사무소","건축물대장에 기재된 건물에 소유·전세·임대차·사용대차 등으로 사용권 확보","같음"],["예외","-","다른 법률에 따라 중개업을 할 수 있는 경우 위 기준을 적용하지 않음"]]},{"종류":"표","제목":"개설등록을 해 주지 않는 경우(영 제13조제2항)","머리":["호","사유"],"행":[["1","공인중개사 또는 법인이 아닌 자가 신청한 경우"],["2","신청한 자가 법 제10조제1항 각 호의 어느 하나에 해당하는 경우"],["3","영 제13조제1항의 개설등록 기준에 적합하지 아니한 경우"],["4","그 밖에 이 법 또는 다른 법령에 따른 제한에 위반되는 경우"]]}],"함정":"사무소 사용권은 소유권으로 한정되지 않는다(⑤). 공인중개사 비율의 모수에 대표자는 들어가지 않는다(③). 자본금 1,000만원은 5천만원에 미달한다(②)."},"31회-2차-003":{"한줄":"파산선고를 받고 복권되지 않은 자(ㄱ)와 자격이 취소된 후 3년이 지나지 않은 임원이 있는 법인(ㄷ)이 결격이다.","근거":[{"법령":"공인중개사법","조문":"법 제10조제1항제3호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 파산선고를 받고 복권되지 아니한 자"},{"법령":"공인중개사법","조문":"법 제10조제1항제2호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 피성년후견인 또는 피한정후견인"},{"법령":"공인중개사법","조문":"법 제10조제1항제12호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 사원 또는 임원 중 제1호부터 제11호까지의 어느 하나에 해당하는 자가 있는 법인"},{"법령":"공인중개사법","조문":"법 제10조제1항제6호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 제35조제1항에 따라 공인중개사의 자격이 취소된 후 3년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제10조제1항제8호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 제38조제1항제2호ㆍ제4호부터 제8호까지, 같은 조 제2항제2호부터 제11호까지에 해당하는 사유로 중개사무소의 개설등록이 취소된 후 3년(제40조제3항에 따라 등록이 취소된 경우에는 3년에서 같은 항 제1호에 따른 폐업기간을 공제한 기간을 말한다)이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제38조제1항제1호","원문":"등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 중개사무소의 개설등록을 취소하여야 한다. 개인인 개업공인중개사가 사망하거나 개업공인중개사인 법인이 해산한 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ도 결격사유라서 ㄱ만으로는 모자란다."},{"번호":2,"판정":"옳음","설명":"ㄱ, ㄷ이 결격사유에 해당한다."},{"번호":3,"판정":"틀림","설명":"ㄴ은 결격사유가 아니다."},{"번호":4,"판정":"틀림","설명":"ㄴ, ㄹ은 결격사유가 아니다."},{"번호":5,"판정":"틀림","설명":"ㄹ은 결격사유가 아니다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"파산선고를 받고 복권되지 아니한 자는 결격이다(법 제10조제1항제3호)."},{"기호":"ㄴ","판정":"틀림","설명":"결격사유는 피성년후견인과 피한정후견인이다. 피특정후견인은 열거되지 않았다(법 제10조제1항제2호)."},{"기호":"ㄷ","판정":"옳음","설명":"임원이 자격취소 후 3년이 지나지 않았다면(제6호) 그 임원이 있는 법인은 결격이다(법 제10조제1항제12호)."},{"기호":"ㄹ","판정":"틀림","설명":"해산으로 인한 등록취소(법 제38조제1항제1호)는 법 제10조제1항제8호의 결격 사유가 아니다. 대표였던 자는 결격이 아니다."}],"개념":[{"종류":"표","제목":"개설등록 결격사유(법 제10조제1항)","머리":["호","사유","기준"],"행":[["1","미성년자","-"],["2","피성년후견인, 피한정후견인","피특정후견인은 열거되지 않음"],["3","파산선고를 받고 복권되지 아니한 자","복권 전까지"],["4","금고 이상의 실형을 선고받은 자","집행 종료(종료로 보는 경우 포함)·집행 면제일부터 3년"],["5","금고 이상의 형의 집행유예를 받은 자","유예기간 만료일부터 2년"],["6","공인중개사 자격이 취소된 자","취소 후 3년"],["7","공인중개사 자격이 정지된 자","자격정지기간 중"],["8","일정한 사유로 개설등록이 취소된 자","취소 후 3년(법 제40조제3항 취소는 폐업기간 공제)"],["9","업무정지처분을 받고 폐업신고를 한 자","업무정지기간이 지나기 전(폐업에도 진행)"],["10","업무정지처분을 받은 법인의 정지 사유 발생 당시 사원·임원이었던 자","해당 법인의 업무정지기간이 지나기 전"],["11","이 법을 위반하여 300만원 이상 벌금형을 선고받은 자","선고 후 3년"],["12","사원 또는 임원 중 제1호~제11호 해당자가 있는 법인","법인"]]},{"종류":"흐름","제목":"등록 후 법인의 사원·임원에게 결격사유가 생긴 경우","단계":[{"이름":"사유 발생","설명":"사원 또는 임원이 제10조제1항제1호~제11호 중 하나에 해당하게 되어 법인이 제12호에 해당(법 제10조제1항제12호)"},{"이름":"2개월 이내 해소","설명":"사유 발생일부터 2개월 이내에 사유를 해소하면 등록취소 제외(법 제38조제1항제3호 단서)"},{"이름":"미해소","설명":"해소하지 못하면 등록관청이 개설등록을 취소해야 함(법 제38조제1항제3호)"},{"이름":"청문","설명":"등록을 취소하려면 청문을 실시(법 제38조제3항)"},{"이름":"등록증 반납","설명":"취소처분을 받은 날부터 7일 이내에 등록관청에 반납(시행규칙 제24조제1항)"}]}],"함정":"법인의 대표자였던 사람(ㄹ)은 해산에 따른 등록취소만으로는 결격이 아니다. 해산 취소(제38조제1항제1호)는 제10조제1항제8호의 3년 결격 사유에 없다. 법인 자체의 결격(ㄷ)은 임원이나 사원 중에 제1호~제11호 해당자가 있을 때 생긴다."},"31회-2차-006":{"한줄":"주상복합 건물의 분양·관리 대행(ㄴ)과 개업공인중개사 대상 경영기법 제공(ㅁ)만 겸업 범위에 들어 ㄴ, ㅁ이 맞다.","근거":[{"법령":"공인중개사법","조문":"법 제14조제1항","원문":"법인인 개업공인중개사는 다른 법률에 규정된 경우를 제외하고는 중개업 및 다음 각 호에 규정된 업무와 제2항에 규정된 업무 외에 다른 업무를 함께 할 수 없다. 1. 상업용 건축물 및 주택의 임대관리 등 부동산의 관리대행 2. 부동산의 이용ㆍ개발 및 거래에 관한 상담 3. 개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공 4. 상업용 건축물 및 주택의 분양대행 5. 그 밖에 중개업에 부수되는 업무로서 대통령령으로 정하는 업무"},{"법령":"공인중개사법","조문":"법 제14조제2항","원문":"개업공인중개사는 「민사집행법」에 의한 경매 및 「국세징수법」 그 밖의 법령에 의한 공매대상 부동산에 대한 권리분석 및 취득의 알선과 매수신청 또는 입찰신청의 대리를 할 수 있다."},{"법령":"공인중개사법","조문":"법 제2조제4호","원문":"이 법에서 사용하는 용어의 정의는 다음과 같다. \"개업공인중개사\"라 함은 이 법에 의하여 중개사무소의 개설등록을 한 자를 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ은 겸업 범위에 없다."},{"번호":2,"판정":"옳음","설명":"ㄴ, ㅁ이 겸업할 수 있는 업무다."},{"번호":3,"판정":"틀림","설명":"ㄷ, ㄹ은 겸업 범위에 없다."},{"번호":4,"판정":"틀림","설명":"ㄱ은 겸업 범위에 없다."},{"번호":5,"판정":"틀림","설명":"ㄷ, ㄹ은 겸업 범위에 없다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"분양대행은 상업용 건축물 및 주택이 대상이다. 주택용지는 해당하지 않는다(법 제14조제1항제4호)."},{"기호":"ㄴ","판정":"옳음","설명":"주택과 상업시설이 함께 있는 건물의 분양대행(제4호)과 임대관리 등 관리대행(제1호)은 겸업 범위에 든다."},{"기호":"ㄷ","판정":"틀림","설명":"거래에 관한 상담은 가능하나(제2호) 금융의 알선은 열거된 업무가 아니다."},{"기호":"ㄹ","판정":"틀림","설명":"경매·공매 업무의 대상은 부동산이다. 동산에 대한 입찰신청의 대리는 법 제14조제2항에 없다."},{"기호":"ㅁ","판정":"옳음","설명":"개업공인중개사를 대상으로 한 경영기법 제공은 겸업할 수 있고(법 제14조제1항제3호), 법인인 개업공인중개사도 개업공인중개사다(법 제2조제4호)."}],"개념":[{"종류":"표","제목":"법인인 개업공인중개사의 겸업 범위(법 제14조, 영 제17조제2항)","머리":["구분","내용","근거"],"행":[["관리대행","상업용 건축물 및 주택의 임대관리 등 부동산의 관리대행","법 제14조제1항제1호"],["상담","부동산의 이용·개발 및 거래에 관한 상담","법 제14조제1항제2호"],["경영 지원","개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공","법 제14조제1항제3호"],["분양대행","상업용 건축물 및 주택의 분양대행","법 제14조제1항제4호"],["부수 업무","중개의뢰인의 의뢰에 따른 도배·이사업체의 소개 등 주거이전에 부수되는 용역의 알선","법 제14조제1항제5호, 영 제17조제2항"],["경매·공매","경매·공매 대상 부동산의 권리분석, 취득의 알선, 매수신청·입찰신청의 대리","법 제14조제2항"],["위반","겸업 제한 위반은 개설등록 취소 가능","법 제38조제2항제4호"]]},{"종류":"비교","제목":"법인인 개업공인중개사의 업무: 할 수 있는 것과 없는 것","왼쪽":{"이름":"할 수 있는 것","항목":["상업용 건축물·주택의 임대관리 등 관리대행","부동산 이용·개발·거래 상담","개업공인중개사 대상 경영기법·경영정보 제공","상업용 건축물·주택의 분양대행","주거이전에 부수되는 용역의 알선","경매·공매 부동산의 권리분석, 취득 알선, 입찰·매수신청 대리"]},"오른쪽":{"이름":"열거되지 않아 할 수 없는 것","항목":["부동산 임대업 자체","토지(주택용지 등)의 분양대행","금융의 알선","공제업무 대행","동산에 대한 입찰 대리","그 밖에 법 제14조에 열거되지 않은 업무"]}}],"함정":"분양대행의 대상은 상업용 건축물과 주택이라서 주택용지(ㄱ)는 빠진다. 거래 상담은 되지만 금융 알선(ㄷ)은 열거에 없다. 공매는 부동산이 대상이고 동산(ㄹ)은 아니다."},"31회-2차-007":{"한줄":"분사무소는 법인인 개업공인중개사만 설치할 수 있으므로 공인중개사인 개업공인중개사는 분사무소를 설치할 수 없다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제15조제1항","원문":"법 제13조제3항에 따른 분사무소는 주된 사무소의 소재지가 속한 시(구가 설치되지 아니한 시와 특별자치도의 행정시를 말한다. 이하 이 조에서 같다)ㆍ군ㆍ구를 제외한 시ㆍ군ㆍ구별로 설치하되, 시ㆍ군ㆍ구별로 1개소를 초과할 수 없다."},{"법령":"공인중개사법","조문":"법 제13조제3항","원문":"제1항에도 불구하고 법인인 개업공인중개사는 대통령령으로 정하는 기준과 절차에 따라 등록관청에 신고하고 그 관할 구역 외의 지역에 분사무소를 둘 수 있다."},{"법령":"공인중개사법 시행령","조문":"영 제15조제2항","원문":"제1항의 규정에 따른 분사무소에는 공인중개사를 책임자로 두어야 한다. 다만, 다른 법률의 규정에 따라 중개업을 할 수 있는 법인의 분사무소인 경우에는 그러하지 아니하다."},{"법령":"공인중개사법","조문":"법 제34조제1항","원문":"제9조에 따라 중개사무소의 개설등록을 신청하려는 자(법인의 경우에는 사원ㆍ임원을 말하며, 제13조제3항에 따라 분사무소의 설치신고를 하려는 경우에는 분사무소의 책임자를 말한다)는 등록신청일(분사무소 설치신고의 경우에는 신고일을 말한다)전 1년 이내에 시ㆍ도지사가 실시하는 실무교육(실무수습을 포함한다)을 받아야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 자는 그러하지 아니하다. 1. 폐업신고 후 1년 이내에 중개사무소의 개설등록을 다시 신청 하려는 자 2. 소속공인중개사로서 고용관계 종료 신고 후 1년 이내에 중개사무소의 개설등록을 신청하려는 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"주된 사무소가 속한 군(郡)에는 분사무소를 둘 수 없다(영 제15조제1항)."},{"번호":2,"판정":"틀림","설명":"분사무소는 등록관청의 인가가 아니라 신고로 설치한다(법 제13조제3항)."},{"번호":3,"판정":"옳음","설명":"분사무소는 법인인 개업공인중개사가 둘 수 있다(법 제13조제3항)."},{"번호":4,"판정":"틀림","설명":"다른 법률에 따라 중개업을 할 수 있는 법인의 분사무소에는 공인중개사 책임자를 두지 않아도 된다(영 제15조제2항 단서)."},{"번호":5,"판정":"틀림","설명":"실무교육은 시·도지사가 실시한다(법 제34조제1항)."}],"개념":[{"종류":"표","제목":"분사무소 설치(법 제13조제3항, 영 제15조)","머리":["항목","내용","근거"],"행":[["설치 주체","법인인 개업공인중개사","법 제13조제3항"],["설치 지역","주된 사무소 소재지가 속한 시·군·구를 제외한 시·군·구, 시·군·구별 1개소","영 제15조제1항"],["책임자","공인중개사. 다른 법률에 따라 중개업을 하는 법인의 분사무소는 예외","영 제15조제2항"],["신고처","주된 사무소 소재지 관할 등록관청","영 제15조제3항"],["첨부서류","책임자 실무교육 수료확인증 사본, 보증 설정 증명서류, 사용권 확보 증명서류","영 제15조제3항제3호~제5호"],["신고확인서","적합하면 신고확인서를 교부하고 설치예정지역 관할 시장·군수·구청장에게 통보","법 제13조제4항"],["보증","분사무소마다 2억원 이상 추가 설정","영 제24조제1항제1호"]]},{"종류":"표","제목":"교육의 종류와 대상(법 제34조, 영 제28조)","머리":["교육","대상","시기","시간"],"행":[["실무교육","개설등록 신청자(법인은 사원·임원, 분사무소는 책임자), 소속공인중개사","등록신청일(분사무소 설치신고일, 고용 신고일) 전 1년 이내","45시간"],["직무교육","중개보조원","고용 신고일 전 1년 이내","3시간 이상 4시간 이하"],["연수교육","실무교육을 받은 개업공인중개사·소속공인중개사","실무교육 후 2년마다","12시간 이상 16시간 이하"],["면제","폐업신고·고용관계 종료 신고 후 1년 이내 재신청·재신고하는 자","법 제34조제1항·제2항·제3항 단서","-"]]}],"함정":"분사무소는 법인만, 신고로, 다른 시·군·구에 설치한다. 교육 실시 주체는 시·도지사다."},"31회-2차-008":{"한줄":"분사무소 설치신고(③)에는 등록증 첨부가 없고 분사무소 폐업신고(④)에는 등록증이 아니라 분사무소설치신고확인서를 첨부하므로 ③, ④가 해당하지 않는다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제11조제1항제1호","원문":"법 제20조제1항에 따라 중개사무소의 이전신고를 하려는 자는 별지 제12호서식의 중개사무소이전신고서에 다음 각 호의 서류를 첨부하여 등록관청(분사무소의 경우에는 주된 사무소의 소재지를 관할하는 등록관청을 말한다. 이하 이 조에서 같다)에 제출해야 한다. 중개사무소등록증(분사무소의 경우에는 분사무소설치신고확인서를 말한다)"},{"법령":"공인중개사법 시행령","조문":"영 제18조제1항","원문":"개업공인중개사는 법 제21조제1항에 따라 다음 각 호의 어느 하나에 해당하는 경우에는 국토교통부령으로 정하는 신고서에 중개사무소등록증을 첨부(제1호 및 제2호의 경우만 해당한다)하여 등록관청에 미리 신고(제3호 및 제4호에 해당하여 신고하는 경우에는 전자문서에 의한 신고를 포함한다)해야 한다. 1. 3개월을 초과하여 휴업(법 제9조에 따른 중개사무소 개설등록 후 업무를 개시하지 않는 경우를 포함한다. 이하 이 조에서 같다)하려는 경우 2. 폐업하려는 경우 3. 3개월을 초과하여 휴업한 부동산중개업을 재개하려는 경우 4. 신고한 휴업기간을 변경하려는 경우"},{"법령":"공인중개사법 시행령","조문":"영 제18조제2항","원문":"법인인 개업공인중개사는 제1항에도 불구하고 법 제13조제3항에 따라 분사무소를 둔 경우에는 제1항에 따른 신고를 분사무소별로 할 수 있다. 이 경우 법 제13조제4항에 따른 신고확인서를 첨부(제1항제1호 및 제2호의 경우만 해당한다)해야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제15조제3항","원문":"법 제13조제3항에 따라 분사무소의 설치신고를 하려는 자는 국토교통부령으로 정하는 분사무소설치신고서에 다음 각 호의 서류를 첨부하여 주된 사무소의 소재지를 관할하는 등록관청에 제출하여야 한다. 이 경우 등록관청은 법 제5조제2항에 따라 공인중개사 자격증을 발급한 시ㆍ도지사에게 분사무소 책임자의 공인중개사 자격 확인을 요청하여야 하고, 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 법인 등기사항증명서를 확인하여야 한다. 1. 삭제<2012.6.29> 2. 삭제<2006.6.12> 3. 분사무소 책임자의 법 제34조제1항의 규정에 따른 실무교육의 수료확인증 사본 4. 제25조의 규정에 따른 보증의 설정을 증명할 수 있는 서류 5. 건축물대장에 기재된 건물에 분사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)하였음을 증명하는 서류. 다만, 건축물대장에 기재되지 아니한 건물에 분사무소를 확보하였을 경우에는 건축물대장 기재가 지연되는 사유를 적은 서류도 함께 내야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"중개사무소 이전신고에는 중개사무소등록증을 첨부한다(시행규칙 제11조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"폐업신고에는 중개사무소등록증을 첨부한다(영 제18조제1항)."},{"번호":3,"판정":"틀림","설명":"분사무소 설치신고의 첨부서류는 책임자의 실무교육 수료확인증 사본, 보증 설정 증명서류, 사용권 확보 증명서류이고 등록증은 없다(영 제15조제3항)."},{"번호":4,"판정":"틀림","설명":"분사무소를 분사무소별로 폐업신고하면 첨부하는 것은 분사무소설치신고확인서다(영 제18조제2항)."},{"번호":5,"판정":"옳음","설명":"3개월을 초과하는 휴업신고에는 중개사무소등록증을 첨부한다(영 제18조제1항)."}],"개념":[{"종류":"표","제목":"신고·신청별 등록증(신고확인서) 첨부 여부","머리":["신고·신청","첨부 서류","근거"],"행":[["중개사무소 이전신고","중개사무소등록증(분사무소는 분사무소설치신고확인서)과 사용권 확보 증명서류","시행규칙 제11조제1항"],["휴업 신고","중개사무소등록증(분사무소를 분사무소별로 신고하면 신고확인서)","영 제18조제1항·제2항"],["폐업 신고","중개사무소등록증(분사무소를 분사무소별로 신고하면 신고확인서)","영 제18조제1항·제2항"],["재개 신고, 휴업기간 변경 신고","첨부하지 않음. 전자문서 신고 가능","영 제18조제1항"],["분사무소 설치신고","책임자 실무교육 수료확인증 사본, 보증 설정 증명서류, 사용권 확보 증명서류(등록증 첨부 없음)","영 제15조제3항"],["종별을 달리하는 등록신청","종전의 등록증 반납","시행규칙 제4조제3항"]]},{"종류":"흐름","제목":"휴업·재개·폐업 신고","단계":[{"이름":"휴업 신고","설명":"3개월을 초과하는 휴업은 등록관청에 미리 신고하고 등록증을 첨부(영 제18조제1항제1호)"},{"이름":"휴업 기간","설명":"6개월을 초과할 수 없음. 질병 요양, 징집 입영, 취학, 임신·출산 등은 예외(법 제21조제2항, 영 제18조제6항)"},{"이름":"기간 변경","설명":"신고한 휴업기간을 바꾸려면 미리 신고. 전자문서 신고 가능(영 제18조제1항제4호)"},{"이름":"재개 신고","설명":"3개월을 초과하여 휴업한 중개업을 재개하려면 미리 신고. 등록관청은 반납받은 등록증을 즉시 반환(영 제18조제1항제3호·제5항)"},{"이름":"폐업 신고","설명":"폐업하려면 미리 신고하고 등록증 첨부. 신고 후 간판은 지체 없이 철거(영 제18조제1항제2호, 법 제21조의2제1항)"}]}],"함정":"이 문항은 정답이 ③, ④ 두 개다. 분사무소를 대상으로 한 신고는 법인의 등록증이 아니라 분사무소설치신고확인서가 쓰이거나 아예 첨부가 없다. 이전·폐업·휴업 신고는 등록증을 붙인다."},"31회-2차-009":{"한줄":"소속공인중개사가 등록하지 않은 인장을 사용하면 6개월의 범위에서 자격정지를 받을 수 있다(법 제36조제1항제2호).","근거":[{"법령":"공인중개사법","조문":"법 제36조제1항제2호","원문":"시ㆍ도지사는 공인중개사가 소속공인중개사로서 업무를 수행하는 기간 중에 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 그 자격을 정지할 수 있다. 제16조의 규정을 위반하여 인장등록을 하지 아니하거나 등록하지 아니한 인장을 사용한 경우"},{"법령":"공인중개사법","조문":"법 제16조제1항","원문":"개업공인중개사 및 소속공인중개사는 국토교통부령으로 정하는 바에 따라 중개행위에 사용할 인장을 등록관청에 등록하여야 한다. 등록한 인장을 변경한 경우에도 또한 같다."},{"법령":"공인중개사법","조문":"법 제9조제1항","원문":"중개업을 영위하려는 자는 국토교통부령으로 정하는 바에 따라 중개사무소(법인의 경우에는 주된 중개사무소를 말한다)를 두려는 지역을 관할하는 시장(구가 설치되지 아니한 시의 시장과 특별자치도 행정시의 시장을 말한다. 이하 같다)ㆍ군수 또는 구청장(이하 \"등록관청\"이라 한다)에게 중개사무소의 개설등록을 하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제9조제2항","원문":"제1항의 규정에 따라 등록한 인장을 변경한 경우에는 개업공인중개사 및 소속공인중개사는 변경일부터 7일 이내에 그 변경된 인장을 등록관청에 등록(전자문서에 의한 등록을 포함한다)하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제9조제3항","원문":"제1항 및 제2항에 따라 개업공인중개사 및 소속공인중개사가 등록하여야 할 인장은 공인중개사인 개업공인중개사, 법 제7638호 부칙 제6조제2항에 규정된 개업공인중개사 및 소속공인중개사의 경우에는 「가족관계의 등록 등에 관한 법률」에 따른 가족관계등록부 또는 「주민등록법」에 따른 주민등록표에 기재되어 있는 성명이 나타난 인장으로서 그 크기가 가로ㆍ세로 각각 7밀리미터 이상 30밀리미터 이내인 인장이어야 하며, 법인인 개업공인중개사의 경우에는 「상업등기규칙」에 따라 신고한 법인의 인장이어야 한다. 다만, 분사무소에서 사용할 인장의 경우에는 「상업등기규칙」 제35조제3항에 따라 법인의 대표자가 보증하는 인장을 등록할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"인장 등록 대상은 개업공인중개사와 소속공인중개사다. 중개보조원은 대상이 아니다(법 제16조제1항)."},{"번호":2,"판정":"틀림","설명":"인장을 변경하면 변경일부터 10일이 아니라 7일 이내에 등록한다(시행규칙 제9조제2항)."},{"번호":3,"판정":"틀림","설명":"인장은 법 제9조제1항의 등록관청(법인은 주된 중개사무소 관할)에 등록한다. 분사무소 소재지 시장·군수·구청장에게 등록한다는 규정은 없다(법 제16조제1항)."},{"번호":4,"판정":"틀림","설명":"분사무소에서 사용할 인장은 법인 대표자가 보증하는 인장도 등록할 수 있다(시행규칙 제9조제3항 단서)."},{"번호":5,"판정":"옳음","설명":"미등록 인장 사용은 소속공인중개사의 자격정지 사유다(법 제36조제1항제2호)."}],"개념":[{"종류":"표","제목":"인장등록(법 제16조, 시행규칙 제9조)","머리":["항목","내용","근거"],"행":[["등록 대상자","개업공인중개사, 소속공인중개사","법 제16조제1항"],["등록 시기","업무를 개시하기 전","시행규칙 제9조제1항"],["변경 등록","변경일부터 7일 이내","시행규칙 제9조제2항"],["사용 의무","중개행위를 할 때 등록한 인장 사용","법 제16조제2항"],["함께 할 수 있는 신청","개설등록 신청, 소속공인중개사·중개보조원 고용 신고와 같이 등록 가능","시행규칙 제9조제6항"],["위반 제재","개업공인중개사는 업무정지, 소속공인중개사는 자격정지","법 제39조제1항제2호, 제36조제1항제2호"]]},{"종류":"비교","제목":"등록하는 인장의 종류(시행규칙 제9조제3항·제4항)","왼쪽":{"이름":"공인중개사인 개업공인중개사·소속공인중개사","항목":["가족관계등록부 또는 주민등록표에 기재된 성명이 나타난 인장","가로·세로 각각 7밀리미터 이상 30밀리미터 이내"]},"오른쪽":{"이름":"법인인 개업공인중개사","항목":["「상업등기규칙」에 따라 신고한 법인의 인장","인장 등록은 인감증명서 제출로 갈음","분사무소에서 쓸 인장은 법인 대표자가 보증하는 인장도 등록 가능"]}}],"함정":"중개보조원은 인장등록 대상이 아니다(①). 변경 기한은 7일이다(②). 분사무소 인장 특례는 대표자 보증 인장까지다(④)."},"31회-2차-010":{"한줄":"개업공인중개사는 법인이든 공인중개사든 사무소 명칭에 \"공인중개사사무소\" 또는 \"부동산중개\"를 사용해야 한다(법 제18조제1항).","근거":[{"법령":"공인중개사법","조문":"법 제18조제1항","원문":"개업공인중개사는 그 사무소의 명칭에 \"공인중개사사무소\" 또는 \"부동산중개\"라는 문자를 사용하여야 한다."},{"법령":"공인중개사법","조문":"법 제18조제2항","원문":"개업공인중개사가 아닌 자는 \"공인중개사사무소\", \"부동산중개\" 또는 이와 유사한 명칭을 사용하여서는 아니된다."},{"법령":"공인중개사법","조문":"법 제18조제3항","원문":"개업공인중개사가 「옥외광고물 등의 관리와 옥외광고산업 진흥에 관한 법률」 제2조제1호에 따른 옥외광고물을 설치하는 경우 중개사무소등록증에 표기된 개업공인중개사(법인의 경우에는 대표자, 법인 분사무소의 경우에는 제13조제4항의 규정에 따른 신고확인서에 기재된 책임자를 말한다)의 성명을 표기하여야 한다."},{"법령":"공인중개사법","조문":"법 제18조제5항","원문":"등록관청은 제1항부터 제3항까지의 규정을 위반한 사무소의 간판 등에 대하여 철거를 명할 수 있다. 이 경우 그 명령을 받은 자가 철거를 이행하지 아니하는 경우에는 「행정대집행법」에 의하여 대집행을 할 수 있다."},{"법령":"공인중개사법","조문":"법 제18조의2제1항","원문":"개업공인중개사가 의뢰받은 중개대상물에 대하여 표시ㆍ광고(「표시ㆍ광고의 공정화에 관한 법률」 제2조에 따른 표시ㆍ광고를 말한다. 이하 같다)를 하려면 중개사무소, 개업공인중개사에 관한 사항으로서 대통령령으로 정하는 사항을 명시하여야 하며, 중개보조원에 관한 사항은 명시해서는 아니 된다."},{"법령":"공인중개사법 시행령","조문":"영 제17조의2제1항제1호","원문":"법 제18조의2제1항에서 \"대통령령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 중개사무소의 명칭, 소재지, 연락처 및 등록번호"}],"선지":[{"번호":1,"판정":"옳음","설명":"개업공인중개사는 사무소 명칭에 \"공인중개사사무소\" 또는 \"부동산중개\"라는 문자를 사용해야 한다(법 제18조제1항)."},{"번호":2,"판정":"틀림","설명":"개업공인중개사가 아닌 자는 \"공인중개사사무소\"와 \"부동산중개\" 모두 사용할 수 없다(법 제18조제2항)."},{"번호":3,"판정":"틀림","설명":"옥외광고물을 설치하는 경우 등록증에 표기된 개업공인중개사의 성명을 표기해야 한다(법 제18조제3항)."},{"번호":4,"판정":"틀림","설명":"간판 철거를 명하는 주체는 국토교통부장관이 아니라 등록관청이다(법 제18조제5항)."},{"번호":5,"판정":"틀림","설명":"표시·광고에는 중개사무소의 명칭을 명시해야 한다(법 제18조의2제1항, 영 제17조의2제1항제1호)."}],"개념":[{"종류":"표","제목":"중개사무소 명칭과 표시·광고(법 제18조, 제18조의2)","머리":["항목","내용","근거"],"행":[["명칭","개업공인중개사는 사무소 명칭에 \"공인중개사사무소\" 또는 \"부동산중개\" 사용","법 제18조제1항"],["명칭 금지","개업공인중개사가 아닌 자는 \"공인중개사사무소\", \"부동산중개\" 또는 유사 명칭 사용 금지","법 제18조제2항"],["옥외광고물","설치하는 경우 등록증에 표기된 개업공인중개사 성명 표기(법인은 대표자, 분사무소는 신고확인서의 책임자). 설치 자체는 의무 아님","법 제18조제3항, 시행규칙 제10조의2"],["철거","위반 간판은 등록관청이 철거를 명하고 이행하지 않으면 행정대집행","법 제18조제5항"],["표시·광고 명시","중개사무소 명칭·소재지·연락처·등록번호, 개업공인중개사 성명(법인은 대표자). 중개보조원 사항은 명시 금지","법 제18조의2제1항, 영 제17조의2제1항"],["표시·광고 주체","개업공인중개사가 아닌 자는 중개대상물 표시·광고 금지","법 제18조의2제3항"],["제재","명칭 미사용·성명 미표기 100만원 이하 과태료, 명칭 무자격 사용 1년 이하 징역 또는 1천만원 이하 벌금","법 제51조제3항제2호, 제49조제1항제6호"]]},{"종류":"비교","제목":"명칭·표시광고 규정: 개업공인중개사와 그 밖의 자","왼쪽":{"이름":"개업공인중개사","항목":["사무소 명칭에 \"공인중개사사무소\" 또는 \"부동산중개\" 사용 의무(법 제18조제1항)","미사용 시 100만원 이하 과태료(법 제51조제3항제2호)","옥외광고물 설치 시 성명 표기","표시·광고에 명칭 등 명시(법 제18조의2제1항)"]},"오른쪽":{"이름":"개업공인중개사가 아닌 자","항목":["\"공인중개사사무소\", \"부동산중개\" 또는 유사 명칭 사용 금지(법 제18조제2항)","위반 시 1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제6호)","위반 간판은 등록관청이 철거 명령, 대집행 가능","중개대상물 표시·광고 금지(법 제18조의2제3항)"]}}],"함정":"개설등록을 하지 않은 사람은 \"부동산중개\"도 쓰지 못한다(②). 철거를 명하는 쪽은 국토교통부장관이 아니라 등록관청이다(④). 표시·광고에는 명칭을 빼지 못한다(⑤)."},"31회-2차-011":{"한줄":"표시·광고의 구체적인 방법은 국토교통부장관이 고시한다(영 제17조의2제3항).","근거":[{"법령":"공인중개사법 시행령","조문":"영 제17조의2제3항","원문":"중개대상물에 대한 제1항 및 제2항에 따른 사항의 구체적인 표시ㆍ광고(「표시ㆍ광고의 공정화에 관한 법률」 제2조제1호 및 제2호에 따른 표시ㆍ광고를 말한다. 이하 같다) 방법에 대해서는 국토교통부장관이 정하여 고시한다."},{"법령":"공인중개사법","조문":"법 제18조의2제1항","원문":"개업공인중개사가 의뢰받은 중개대상물에 대하여 표시ㆍ광고(「표시ㆍ광고의 공정화에 관한 법률」 제2조에 따른 표시ㆍ광고를 말한다. 이하 같다)를 하려면 중개사무소, 개업공인중개사에 관한 사항으로서 대통령령으로 정하는 사항을 명시하여야 하며, 중개보조원에 관한 사항은 명시해서는 아니 된다."},{"법령":"공인중개사법","조문":"법 제18조의2제2항","원문":"개업공인중개사가 인터넷을 이용하여 중개대상물에 대한 표시ㆍ광고를 하는 때에는 제1항에서 정하는 사항 외에 중개대상물의 종류별로 대통령령으로 정하는 소재지, 면적, 가격 등의 사항을 명시하여야 한다."},{"법령":"공인중개사법","조문":"법 제46조제1항","원문":"등록관청은 다음 각 호의 어느 하나에 해당하는 자를 등록관청, 수사기관이나 제47조의2에 따른 부동산거래질서교란행위 신고센터에 신고 또는 고발한 자에 대하여 대통령령으로 정하는 바에 따라 포상금을 지급할 수 있다. 1. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 한 자 2. 거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 자 3. 중개사무소등록증 또는 공인중개사자격증을 다른 사람에게 양도ㆍ대여하거나 다른 사람으로부터 양수ㆍ대여받은 자 4. 제18조의2제3항을 위반하여 표시ㆍ광고를 한 자 5. 제33조제1항제8호 또는 제9호에 따른 행위를 한 자 6. 제33조제2항을 위반하여 개업공인중개사등의 업무를 방해한 자"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제10조의3제1항","원문":"법 제18조의3제1항에 따른 모니터링 업무는 다음 각 호의 구분에 따라 수행한다. 1. 기본 모니터링 업무: 제2항제1호에 따른 모니터링 기본계획서에 따라 분기별로 실시하는 모니터링 2. 수시 모니터링 업무: 법 제18조의2를 위반한 사실이 의심되는 경우 등 국토교통부장관이 필요하다고 판단하여 실시하는 모니터링"}],"선지":[{"번호":1,"판정":"틀림","설명":"중개보조원에 관한 사항은 명시해서는 안 된다(법 제18조의2제1항)."},{"번호":2,"판정":"옳음","설명":"표시·광고 방법은 국토교통부장관이 고시한다(영 제17조의2제3항)."},{"번호":3,"판정":"틀림","설명":"포상금 대상은 개업공인중개사가 아닌 자의 표시·광고 등이다. 중개대상물 내용을 거짓으로 표시·광고한 개업공인중개사를 신고한 경우는 열거되지 않았다(법 제46조제1항)."},{"번호":4,"판정":"틀림","설명":"인터넷 표시·광고는 중개사무소·개업공인중개사 사항에 더하여 소재지·면적·가격 등을 명시한다(법 제18조의2제2항)."},{"번호":5,"판정":"틀림","설명":"기본 모니터링은 기본계획서에 따라 분기별로 실시한다(시행규칙 제10조의3제1항제1호). 6개월마다가 아니다."}],"개념":[{"종류":"표","제목":"인터넷 표시·광고 모니터링(법 제18조의3, 시행규칙 제10조의3)","머리":["구분","내용"],"행":[["기본 모니터링","모니터링 기본계획서에 따라 분기별로 실시"],["수시 모니터링","법 제18조의2 위반이 의심되는 경우 등 국토교통부장관이 필요하다고 판단하여 실시"],["기본계획서 제출","다음 연도 계획을 매년 12월 31일까지 제출"],["결과보고서 제출","기본 모니터링은 분기 마지막 날부터 30일 이내, 수시 모니터링은 완료일부터 15일 이내"],["후속 조치","국토교통부장관이 시·도지사·등록관청에 통보하고 조사·조치를 요구, 완료한 날부터 10일 이내 결과 통보"],["위탁","국토교통부장관은 공공기관, 정부출연연구기관 등에 위탁 가능(영 제17조의3)"]]},{"종류":"표","제목":"부당한 표시·광고와 과태료(법 제18조의2제4항, 영 별표 2)","머리":["유형","과태료"],"행":[["존재하지 않아 실제로 거래할 수 없는 중개대상물","500만원"],["존재하지만 실제로 중개의 대상이 될 수 없는 중개대상물","400만원"],["가격 등 내용을 거짓으로 표시·광고하거나 과장","300만원"],["입지조건·가격·거래조건 등 중요한 사실을 빠뜨리거나 은폐·축소하여 소비자를 속임","300만원"],["존재하지만 실제로 중개할 의사가 없는 중개대상물","250만원"]]}],"함정":"인터넷 광고는 추가 항목을 더 쓰는 것이지 사무소 사항을 빼는 것이 아니다(④). 모니터링 주기는 분기다(⑤). 부당 광고를 한 개업공인중개사는 과태료 대상이다(③)."},"31회-2차-013":{"한줄":"분사무소 이전신고를 받은 등록관청은 이전 전·후 소재지 관할 시장·군수·구청장에게 지체 없이 통보해야 한다(시행규칙 제11조제3항).","근거":[{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제11조제1항","원문":"법 제20조제1항에 따라 중개사무소의 이전신고를 하려는 자는 별지 제12호서식의 중개사무소이전신고서에 다음 각 호의 서류를 첨부하여 등록관청(분사무소의 경우에는 주된 사무소의 소재지를 관할하는 등록관청을 말한다. 이하 이 조에서 같다)에 제출해야 한다. 1. 중개사무소등록증(분사무소의 경우에는 분사무소설치신고확인서를 말한다) 2. 건축물대장에 기재된 건물에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)하였음을 증명하는 서류. 다만, 건축물대장에 기재되지 아니한 건물에 중개사무소를 확보하였을 경우에는 건축물대장 기재가 지연되는 사유를 적은 서류도 함께 내야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제11조제2항","원문":"제1항에 따라 중개사무소의 이전신고를 받은 등록관청은 그 내용이 적합한 경우에는 중개사무소등록증 또는 분사무소설치신고확인서를 재교부해야 한다. 다만, 개업공인중개사가 등록관청의 관할지역 내로 이전한 경우에는 등록관청은 중개사무소등록증 또는 분사무소설치신고확인서에 변경사항을 적어 교부할 수 있다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제11조제3항","원문":"등록관청은 분사무소의 이전신고를 받은 때에는 지체 없이 그 분사무소의 이전 전 및 이전 후의 소재지를 관할하는 시장ㆍ군수 또는 구청장에게 이를 통보하여야 한다."},{"법령":"공인중개사법","조문":"법 제51조제3항제3호","원문":"다음 각 호의 어느 하나에 해당하는 자에게는 100만원 이하의 과태료를 부과한다. 제20조제1항을 위반하여 중개사무소의 이전신고를 하지 아니한 자"},{"법령":"공인중개사법","조문":"법 제20조제1항","원문":"개업공인중개사는 중개사무소를 이전한 때에는 이전한 날부터 10일 이내에 국토교통부령으로 정하는 바에 따라 등록관청에 이전사실을 신고하여야 한다. 다만, 중개사무소를 등록관청의 관할 지역 외의 지역으로 이전한 경우에는 이전 후의 중개사무소를 관할하는 시장ㆍ군수 또는 구청장(이하 이 조에서 \"이전후 등록관청\"이라 한다)에게 신고하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"관할 지역 밖으로 이전한 경우에는 등록증을 재교부해야 한다. 변경사항을 적어 교부할 수 있는 것은 관할 지역 내 이전의 경우다(시행규칙 제11조제2항 단서)."},{"번호":2,"판정":"틀림","설명":"건축물대장에 기재되지 않은 건물이면 기재 지연 사유서도 함께 내야 한다(시행규칙 제11조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"이전신고를 하지 않으면 100만원 이하의 과태료 대상이다(법 제51조제3항제3호)."},{"번호":4,"판정":"틀림","설명":"분사무소 이전신고는 주된 사무소의 소재지를 관할하는 등록관청에 한다(시행규칙 제11조제1항)."},{"번호":5,"판정":"옳음","설명":"분사무소 이전신고를 받은 등록관청은 이전 전·후 소재지 관할 시장·군수·구청장에게 지체 없이 통보한다(시행규칙 제11조제3항)."}],"개념":[{"종류":"흐름","제목":"중개사무소 이전신고","단계":[{"이름":"이전","설명":"중개사무소를 이전한 날부터 10일 이내에 등록관청에 신고(법 제20조제1항)"},{"이름":"관할 밖 이전","설명":"등록관청의 관할 지역 밖으로 이전하면 이전 후 중개사무소를 관할하는 등록관청에 신고(법 제20조제1항 단서)"},{"이름":"첨부서류","설명":"이전신고서, 중개사무소등록증(분사무소는 분사무소설치신고확인서), 사용권 확보 증명서류(시행규칙 제11조제1항)"},{"이름":"서류 송부","설명":"이전후 등록관청이 종전 등록관청에 서류 송부를 요청하면 종전 등록관청이 지체 없이 송부(법 제20조제2항)"},{"이름":"재교부","설명":"적합하면 등록증 또는 신고확인서를 재교부. 관할 내 이전이면 변경사항을 적어 교부 가능(시행규칙 제11조제2항)"},{"이름":"분사무소","설명":"분사무소 이전신고는 주된 사무소 소재지 등록관청에 하고, 등록관청은 이전 전·후 소재지 관할 시장·군수·구청장에게 지체 없이 통보(시행규칙 제11조제1항·제3항)"},{"이름":"처분·간판","설명":"이전 신고 전에 생긴 사유의 행정처분은 이전후 등록관청이 하고(법 제20조제3항), 이전 신고 후 간판은 지체 없이 철거(법 제21조의2)"}]},{"종류":"비교","제목":"중개사무소 이전: 관할 내와 관할 밖","왼쪽":{"이름":"등록관청 관할 지역 내 이전","항목":["신고처: 등록관청","신고기한: 이전한 날부터 10일","등록증: 변경사항을 적어 교부하거나 재교부(시행규칙 제11조제2항 단서)","서류 송부 절차 없음"]},"오른쪽":{"이름":"등록관청 관할 지역 밖 이전","항목":["신고처: 이전 후 중개사무소를 관할하는 등록관청(법 제20조제1항 단서)","신고기한: 이전한 날부터 10일","이전후 등록관청이 종전 등록관청에 서류 송부 요청(법 제20조제2항)","신고 전 사유의 행정처분은 이전후 등록관청이 함(법 제20조제3항)"]}}],"함정":"재교부와 변경사항 기재 교부의 구분은 이전 범위로 갈린다. 분사무소 이전신고 상대는 주된 사무소 관할 등록관청이다."},"31회-2차-014":{"한줄":"폐업신고 전 위반행위로 받은 처분의 효과는 폐업일이 아니라 처분일부터 1년간 승계되므로 ①이 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제40조제2항","원문":"제1항의 경우 폐업신고 전의 개업공인중개사에 대하여 제39조제1항 각 호, 제51조제1항 각 호, 같은 조 제2항 각 호 및 같은 조 제3항 각 호의 위반행위를 사유로 행한 행정처분의 효과는 그 처분일부터 1년간 다시 중개사무소의 개설등록을 한 자(이하 이 조에서 \"재등록 개업공인중개사\"라 한다)에게 승계된다."},{"법령":"공인중개사법","조문":"법 제34조제2항","원문":"소속공인중개사는 제15조제1항에 따른 고용 신고일 전 1년 이내에 시ㆍ도지사가 실시하는 실무교육을 받아야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 자는 그러하지 아니하다. 1. 고용관계 종료 신고 후 1년 이내에 고용 신고를 다시 하려는 자 2. 개업공인중개사로서 폐업신고를 한 후 1년 이내에 소속공인중개사로 고용 신고를 하려는 자"},{"법령":"공인중개사법","조문":"법 제30조제4항","원문":"제3항에 따라 공탁한 공탁금은 개업공인중개사가 폐업 또는 사망한 날부터 3년 이내에는 이를 회수할 수 없다."},{"법령":"공인중개사법 시행령","조문":"영 제18조제2항","원문":"법인인 개업공인중개사는 제1항에도 불구하고 법 제13조제3항에 따라 분사무소를 둔 경우에는 제1항에 따른 신고를 분사무소별로 할 수 있다. 이 경우 법 제13조제4항에 따른 신고확인서를 첨부(제1항제1호 및 제2호의 경우만 해당한다)해야 한다."},{"법령":"공인중개사법","조문":"법 제47조제1항","원문":"다음 각 호의 어느 하나에 해당하는 자는 해당 지방자치단체의 조례로 정하는 바에 따라 수수료를 납부하여야 한다. 다만, 공인중개사자격시험을 제4조제2항의 규정에 따라 국토교통부장관이 시행하는 경우 제1호에 해당하는 자는 국토교통부장관이 결정ㆍ공고하는 수수료를 납부하여야 한다. 1. 제4조에 따른 공인중개사자격시험에 응시하는 자 2. 제5조제3항에 따라 공인중개사자격증의 재교부를 신청하는 자 3. 제9조제1항에 따라 중개사무소의 개설등록을 신청하는 자 4. 제11조제2항에 따라 중개사무소등록증의 재교부를 신청하는 자 5. 제13조제3항에 따라 분사무소설치의 신고를 하는 자 6. 제13조제5항에 따라 분사무소설치신고확인서의 재교부를 신청하는 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"처분의 효과는 폐업일이 아니라 그 처분일부터 1년간 재등록 개업공인중개사에게 승계된다(법 제40조제2항)."},{"번호":2,"판정":"옳음","설명":"폐업신고 후 1년 이내에 소속공인중개사로 고용신고를 하는 경우에는 실무교육을 받지 않아도 된다(법 제34조제2항제2호)."},{"번호":3,"판정":"옳음","설명":"공탁금은 폐업 또는 사망한 날부터 3년 이내에는 회수할 수 없다(법 제30조제4항)."},{"번호":4,"판정":"옳음","설명":"분사무소는 분사무소별로 휴업 신고를 할 수 있다(영 제18조제2항)."},{"번호":5,"판정":"옳음","설명":"폐업신고는 법 제47조제1항이 정한 수수료 납부 대상이 아니다."}],"개념":[{"종류":"표","제목":"폐업 후 재등록과 행정처분(법 제40조)","머리":["구분","내용"],"행":[["지위 승계","폐업신고 후 다시 개설등록을 하면 폐업신고 전 개업공인중개사의 지위를 승계(제1항)"],["처분효과 승계","업무정지·과태료 등 처분의 효과는 처분일부터 1년간 재등록 개업공인중개사에게 승계(제2항)"],["폐업 전 위반행위 처분","재등록 개업공인중개사에 대해 폐업 전의 제38조·제39조 위반행위로 처분 가능(제3항)"],["처분 제외","폐업기간이 3년을 초과한 경우, 업무정지 사유인데 폐업기간이 1년을 초과한 경우(제3항 각 호)"],["고려사항","처분할 때 폐업기간과 폐업의 사유 등을 고려(제4항)"],["법인 대표자","법인의 대표자에게도 준용(제5항)"]]},{"종류":"표","제목":"폐업·휴업과 관련한 법적 효과","머리":["항목","내용","근거"],"행":[["교육 면제","폐업신고 후 1년 이내 소속공인중개사로 고용신고되면 실무교육 면제","법 제34조제2항제2호"],["공탁금","폐업 또는 사망한 날부터 3년 이내에는 회수 불가","법 제30조제4항"],["간판","폐업신고 후 지체 없이 철거","법 제21조의2제1항제2호"],["결격","업무정지처분을 받고 폐업신고를 한 자는 업무정지기간(폐업에도 진행)이 지나기 전까지 결격","법 제10조제1항제9호"],["분사무소","분사무소는 주된 사무소와 별도로 휴업·폐업 신고 가능","영 제18조제2항"],["수수료","폐업신고는 수수료 납부 대상으로 열거되지 않음","법 제47조제1항"]]}],"함정":"승계 기간의 기산점은 처분일이다. 폐업일부터 세지 않는다."},"31회-2차-030":{"한줄":"외국인도 중개보조원으로 고용할 수 있으므로 ㄱ만 옳다. 소속공인중개사는 직무교육이 아닌 실무교육을 받고, 고용 신고는 업무개시 전까지 해야 한다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"규칙 제8조제5항","원문":"이 경우 소속공인중개사 또는 중개보조원으로 외국인을 고용하는 경우에는 제4조제1항제6호가목의 서류를 첨부하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"규칙 제8조제3항","원문":"제1항에 따른 고용 신고를 받은 등록관청은 법 제10조제2항에 따른 결격사유 해당 여부와 법 제34조제2항 또는 제3항에 따른 교육 수료 여부를 확인하여야 한다."},{"법령":"공인중개사법","조문":"법 제34조제2항","원문":"소속공인중개사는 제15조제1항에 따른 고용 신고일 전 1년 이내에 시ㆍ도지사가 실시하는 실무교육을 받아야 한다."},{"법령":"공인중개사법 시행규칙","조문":"규칙 제8조제1항","원문":"법 제15조제1항에 따라 업무개시 전까지 등록관청에 신고(전자문서에 의한 신고를 포함한다)하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ만 옳은 보기이므로 이 조합이 맞다."},{"번호":2,"판정":"틀림","설명":"ㄴ이 틀린 보기라 ㄱ, ㄴ 조합이 맞지 않는다."},{"번호":3,"판정":"틀림","설명":"ㄷ이 틀린 보기라 ㄱ, ㄷ 조합이 맞지 않는다."},{"번호":4,"판정":"틀림","설명":"ㄴ, ㄷ 모두 틀린 보기다."},{"번호":5,"판정":"틀림","설명":"ㄴ, ㄷ이 틀린 보기라 세 보기를 모두 고르면 맞지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"외국인을 중개보조원으로 고용하는 경우를 전제로 첨부서류를 정하고 있다(규칙 제8조제5항)."},{"기호":"ㄴ","판정":"틀림","설명":"소속공인중개사에 대해 등록관청이 확인하는 것은 법 제34조제2항의 실무교육 수료 여부다(규칙 제8조제3항)."},{"기호":"ㄷ","판정":"틀림","설명":"고용 신고는 업무개시 전까지 해야 한다(규칙 제8조제1항). 업무개시 후 10일 이내가 아니다."}],"개념":[{"종류":"흐름","제목":"고용 신고 절차","단계":[{"이름":"교육","설명":"신고일 전 1년 이내에 소속공인중개사는 실무교육, 중개보조원은 직무교육을 받는다(법 제34조제2항·제3항)"},{"이름":"신고","설명":"업무개시 전까지 등록관청에 신고. 외국인을 고용하면 법 제10조제1항 각 호에 해당하지 않음을 증명하는 서류를 첨부(규칙 제8조제1항·제5항)"},{"이름":"등록관청 확인","설명":"결격사유 해당 여부와 교육 수료 여부를 확인(규칙 제8조제3항)"},{"이름":"자격 확인 요청","설명":"소속공인중개사는 자격증을 발급한 시·도지사에게 자격 확인을 요청(규칙 제8조제2항)"},{"이름":"협회 통보","설명":"고용·종료 신고를 받은 때 한국공인중개사협회에 통보. 매월 다음달 10일까지(영 제14조제3호, 규칙 제6조)"},{"이름":"종료 신고","설명":"고용관계 종료일부터 10일 이내에 신고(규칙 제8조제4항)"}]},{"종류":"표","제목":"소속공인중개사와 중개보조원 비교","머리":["구분","소속공인중개사","중개보조원"],"행":[["정의","개업공인중개사에 소속된 공인중개사로서 중개업무를 수행하거나 개업공인중개사의 중개업무를 보조하는 자(법 제2조제5호)","공인중개사가 아닌 자로서 현장안내·일반서무 등 단순한 업무를 보조하는 자(법 제2조제6호)"],["고용 신고","업무개시 전까지 등록관청에 신고, 전자문서 신고 포함(규칙 제8조제1항)","업무개시 전까지 등록관청에 신고, 전자문서 신고 포함(규칙 제8조제1항)"],["고용 전 교육","신고일 전 1년 이내 시·도지사의 실무교육(법 제34조제2항)","신고일 전 1년 이내 시·도지사 또는 등록관청의 직무교육(법 제34조제3항)"],["자격 확인","등록관청이 자격증을 발급한 시·도지사에게 자격 확인 요청(규칙 제8조제2항)","해당 없음(공인중개사가 아님)"],["고용관계 종료 신고","종료일부터 10일 이내(규칙 제8조제4항)","종료일부터 10일 이내(규칙 제8조제4항)"],["인장등록","등록 대상(법 제16조제1항)","등록 대상 아님"],["업무상 행위","고용한 개업공인중개사의 행위로 봄(법 제15조제2항)","고용한 개업공인중개사의 행위로 봄(법 제15조제2항)"]]}],"함정":"ㄴ은 소속공인중개사가 받는 교육이 실무교육인데 직무교육(중개보조원 교육)으로 적었다. ㄷ은 업무개시 전까지 신고해야 하는데 개시 후 10일로 적었다. 10일은 종료 신고 기한이다."},"31회-2차-020":{"한줄":"ㄱ, ㄴ, ㄹ, ㅁ은 법 제24조제5항의 지정취소 사유이고, ㄷ은 지정받은 날부터 6개월이 아니라 1년 이내에 설치·운영하지 않은 경우가 취소 사유라 해당하지 않는다.","근거":[{"법령":"공인중개사법","조문":"법 제24조제5항제1호","원문":"1. 거짓이나 그 밖의 부정한 방법으로 지정을 받은 경우"},{"법령":"공인중개사법","조문":"법 제24조제5항제2호","원문":"2. 제3항의 규정을 위반하여 운영규정의 승인 또는 변경승인을 받지 아니하거나 운영규정을 위반하여 부동산거래정보망을 운영한 경우"},{"법령":"공인중개사법","조문":"법 제24조제5항제3호","원문":"3. 제4항의 규정을 위반하여 정보를 공개한 경우"},{"법령":"공인중개사법","조문":"법 제24조제5항제4호","원문":"4. 정당한 사유 없이 지정받은 날부터 1년 이내에 부동산거래정보망을 설치ㆍ운영하지 아니한 경우"},{"법령":"공인중개사법","조문":"법 제24조제5항제5호","원문":"5. 개인인 거래정보사업자의 사망 또는 법인인 거래정보사업자의 해산 그 밖의 사유로 부동산거래정보망의 계속적인 운영이 불가능한 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄹ, ㅁ도 취소 사유라 ㄱ, ㄴ만 고른 조합은 부족하다."},{"번호":2,"판정":"틀림","설명":"ㄷ은 취소 사유가 아니고 ㄱ, ㄴ, ㅁ이 빠졌다."},{"번호":3,"판정":"틀림","설명":"ㄹ도 취소 사유라 ㄱ, ㄴ, ㅁ만 고른 조합은 부족하다."},{"번호":4,"판정":"옳음","설명":"ㄱ, ㄴ, ㄹ, ㅁ이 취소 사유이고 ㄷ만 해당하지 않아 이 조합이 맞다."},{"번호":5,"판정":"틀림","설명":"ㄷ이 취소 사유가 아니므로 다섯 보기를 모두 고르면 맞지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"운영규정 변경승인을 받지 않고 운영한 경우는 지정취소 사유다(법 제24조제5항제2호)."},{"기호":"ㄴ","판정":"옳음","설명":"공개를 의뢰받지 않은 정보를 공개한 경우는 제4항 위반으로 지정취소 사유다(법 제24조제5항제3호)."},{"기호":"ㄷ","판정":"틀림","설명":"지정받은 날부터 6개월이 아니라 1년 이내에 설치·운영하지 않은 경우가 사유다(법 제24조제5항제4호)."},{"기호":"ㄹ","판정":"옳음","설명":"개인인 거래정보사업자가 사망해 운영이 불가능한 경우는 지정취소 사유다(법 제24조제5항제5호)."},{"기호":"ㅁ","판정":"옳음","설명":"운영규정을 위반하여 운영한 경우는 지정취소 사유다(법 제24조제5항제2호)."}],"개념":[{"종류":"표","제목":"거래정보사업자 지정취소 사유(법 제24조제5항·제6항)","머리":["호","사유","청문"],"행":[["1","거짓이나 그 밖의 부정한 방법으로 지정을 받은 경우","실시"],["2","운영규정의 승인 또는 변경승인을 받지 않거나 운영규정을 위반하여 부동산거래정보망을 운영한 경우","실시"],["3","공개를 의뢰받은 정보에 한정하지 않고 공개하거나 의뢰받은 내용과 다르게, 또는 개업공인중개사에 따라 차별적으로 공개한 경우","실시"],["4","정당한 사유 없이 지정받은 날부터 1년 이내에 부동산거래정보망을 설치·운영하지 않은 경우","실시"],["5","개인인 거래정보사업자의 사망 또는 법인인 거래정보사업자의 해산 그 밖의 사유로 계속적인 운영이 불가능한 경우","청문 없음"]]}],"함정":"ㄷ은 6개월로 기간만 바꿔 놓았다. 설치·운영 기한은 지정받은 날부터 1년이다. ㄹ처럼 사망·해산으로 운영이 불가능한 경우도 취소 사유에 들어간다."},"31회-2차-023":{"한줄":"가입·이용신청한 개업공인중개사가 500명 이상이고 2개 이상의 시·도에서 각각 30인 이상이어야 하며, 공인중개사는 1명 이상 확보하므로 ④가 옳다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"규칙 제15조제2항제1호","원문":"1. 그 부동산거래정보망의 가입ㆍ이용신청을 한 개업공인중개사의 수가 5백명 이상이고 2개 이상의 특별시ㆍ광역시ㆍ도 및 특별자치도(이하 \"시ㆍ도\"라 한다)에서 각각 30인 이상의 개업공인중개사가 가입ㆍ이용신청을 하였을 것"},{"법령":"공인중개사법 시행규칙","조문":"규칙 제15조제2항제2호","원문":"2. 정보처리기사 1명 이상을 확보할 것"},{"법령":"공인중개사법 시행규칙","조문":"규칙 제15조제2항제3호","원문":"3. 공인중개사 1명 이상을 확보할 것"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ은 공인중개사가 아니라 개업공인중개사이고 ㄷ은 20이 아니라 30이다(규칙 제15조제2항제1호)."},{"번호":2,"판정":"틀림","설명":"ㄱ은 개업공인중개사, ㄷ은 30, ㄹ은 1이다(규칙 제15조제2항)."},{"번호":3,"판정":"틀림","설명":"ㄷ은 20이 아니라 30이고 ㄹ은 3이 아니라 1이다(규칙 제15조제2항)."},{"번호":4,"판정":"옳음","설명":"ㄱ 개업공인중개사, ㄴ 2, ㄷ 30, ㄹ 1이 규칙 제15조제2항과 같다."},{"번호":5,"판정":"틀림","설명":"ㄴ은 3이 아니라 2다(규칙 제15조제2항제1호)."}],"개념":[{"종류":"표","제목":"거래정보사업자 지정 요건(법 제24조제2항, 규칙 제15조제2항)","머리":["구분","요건","수치"],"행":[["사업자","전기통신사업법상 부가통신사업자","-"],["가입·이용신청","개업공인중개사 수","500명 이상, 2개 이상 시·도에서 각각 30인 이상"],["정보처리기사","확보","1명 이상"],["공인중개사","확보","1명 이상"],["컴퓨터설비","가입자 이용에 지장이 없는 용량·성능","국토교통부장관이 정함"]]}],"함정":"가입·이용신청을 한 주체가 개업공인중개사인 점, 시·도 수가 2개이고 각 30인 이상인 점, 공인중개사 확보 인원이 1명인 점을 선지마다 바꿔 놓았다."},"31회-2차-001":{"한줄":"확인·설명을 성실·정확하게 하지 않은 개업공인중개사는 법 제51조제2항제1호의6에 따라 500만원 이하의 과태료 대상이므로 ④가 옳다.","근거":[{"법령":"공인중개사법","조문":"법 제51조제2항제1호의6","원문":"1의6. 제25조제1항을 위반하여 성실ㆍ정확하게 중개대상물의 확인ㆍ설명을 하지 아니하거나 설명의 근거자료를 제시하지 아니한 자"},{"법령":"공인중개사법","조문":"법 제25조제1항","원문":"개업공인중개사는 중개를 의뢰받은 경우에는 중개가 완성되기 전에 다음 각 호의 사항을 확인하여 이를 해당 중개대상물에 관한 권리를 취득하고자 하는 중개의뢰인에게 성실ㆍ정확하게 설명하고"},{"법령":"공인중개사법","조문":"법 제2조제5호","원문":"\"소속공인중개사\"라 함은 개업공인중개사에 소속된 공인중개사(개업공인중개사인 법인의 사원 또는 임원으로서 공인중개사인 자를 포함한다)"},{"법령":"공인중개사법","조문":"법 제12조제2항","원문":"개업공인중개사등은 다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 될 수 없다."},{"법령":"공인중개사법","조문":"법 제6조","원문":"제35조제1항에 따라 공인중개사의 자격이 취소된 후 3년이 지나지 아니한 자는 공인중개사가 될 수 없다."},{"법령":"공인중개사법 시행령","조문":"영 제21조제1항제4호","원문":"4. 토지이용계획, 공법상의 거래규제 및 이용제한에 관한 사항"}],"선지":[{"번호":1,"판정":"틀림","설명":"확인·설명의무는 개업공인중개사의 의무다(법 제25조제1항). 중개보조원에게는 이 의무가 없다."},{"번호":2,"판정":"틀림","설명":"소속공인중개사에는 개업공인중개사인 법인의 사원·임원인 공인중개사가 포함되므로 소속 법인의 임원이 될 수 있다(법 제2조제5호). 법 제12조제2항이 막는 것은 다른 개업공인중개사의 소속이다."},{"번호":3,"판정":"틀림","설명":"공인중개사가 될 수 없는 사람은 자격이 취소된 후 3년이 지나지 않은 자이고 국적 제한은 없다(법 제6조)."},{"번호":4,"판정":"옳음","설명":"성실·정확한 확인·설명을 하지 않으면 500만원 이하의 과태료 대상이다(법 제51조제2항제1호의6)."},{"번호":5,"판정":"틀림","설명":"토지이용계획은 확인·설명 사항에 들어 있다(영 제21조제1항제4호)."}],"개념":[{"종류":"표","제목":"과태료 부과 사유 일부(법 제51조)","머리":["금액","사유","근거"],"행":[["500만원 이하","부당한 표시·광고(제18조의2제4항 각 호 위반)","제2항제1호"],["500만원 이하","중개보조원이라는 사실을 미리 알리지 않은 사람 및 소속 개업공인중개사(상당한 주의와 감독을 한 경우는 제외)","제2항제1호의4"],["500만원 이하","성실·정확하게 중개대상물의 확인·설명을 하지 않거나 설명의 근거자료를 제시하지 않은 자","제2항제1호의6"],["500만원 이하","연수교육을 정당한 사유 없이 받지 않은 자","제2항제5호의2"],["100만원 이하","중개사무소등록증 등을 게시하지 않은 자","제3항제1호"],["100만원 이하","손해배상책임에 관한 사항을 설명하지 않거나 관계 증서의 사본 또는 전자문서를 교부하지 않은 자","제3항제5호"],["100만원 이하","공인중개사자격증을 반납하지 않거나 반납할 수 없는 사유서를 제출하지 않은 자","제3항제6호"]]},{"종류":"표","제목":"중개대상물 확인·설명 사항(영 제21조제1항)","머리":["호","사항"],"행":[["1","종류·소재지·지번·지목·면적·용도·구조 및 건축연도 등 기본적인 사항"],["2","소유권·전세권·저당권·지상권 및 임차권 등 권리관계"],["3","거래예정금액·중개보수 및 실비의 금액과 그 산출내역"],["3의2","관리비 금액과 그 산출내역(주택 임대차 중개의 경우만)"],["4","토지이용계획, 공법상의 거래규제 및 이용제한에 관한 사항"],["5","수도·전기·가스·소방·열공급·승강기 및 배수 등 시설물의 상태"],["6","벽면·바닥면 및 도배의 상태"],["7","일조·소음·진동 등 환경조건"],["8","도로 및 대중교통수단과의 연계성, 시장·학교와의 근접성 등 입지조건"],["9","중개대상물에 대한 권리를 취득함에 따라 부담하여야 할 조세의 종류 및 세율"],["10~12","임대인의 정보 제시 의무와 보증금 중 일정액의 보호, 전입세대확인서, 민간임대주택 임대보증금 보증(주택 임대차 중개의 경우만)"]]}],"함정":"②는 소속공인중개사의 법인 임원 지위를 막는 규정이 있다고 오해하게 한다. 법 제12조제2항은 다른 개업공인중개사 밑으로 들어가는 것을 막을 뿐이다. ④의 확인·설명 위반은 과태료, 서명 및 날인 위반은 업무정지로 제재가 다르다."},"31회-2차-015":{"한줄":"서로 다른 둘 이상의 거래계약서를 작성한 경우 등록관청은 개설등록을 취소할 수 있을 뿐 취소해야 하는 것이 아니므로 ⑤가 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제38조제2항제7호","원문":"7. 제26조제3항의 규정을 위반하여 거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우"},{"법령":"공인중개사법","조문":"법 제38조제2항","원문":"등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 중개사무소의 개설등록을 취소할 수 있다."},{"법령":"공인중개사법","조문":"법 제26조제1항","원문":"개업공인중개사는 중개대상물에 관하여 중개가 완성된 때에는 대통령령으로 정하는 바에 따라 거래계약서를 작성하여 거래당사자에게 교부하고"},{"법령":"공인중개사법","조문":"법 제26조제2항","원문":"제25조제4항의 규정은 제1항에 따른 거래계약서의 작성에 관하여 이를 준용한다."},{"법령":"공인중개사법 시행령","조문":"영 제22조제1항제8호","원문":"8. 중개대상물확인ㆍ설명서 교부일자"},{"법령":"공인중개사법 시행령","조문":"영 제22조제2항","원문":"법 제26조제1항에서 \"대통령령이 정하는 기간\"이라 함은 5년을 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"거래계약서는 중개가 완성된 때 작성·교부한다(법 제26조제1항)."},{"번호":2,"판정":"옳음","설명":"거래계약서에는 개업공인중개사가 서명 및 날인한다(법 제26조제2항, 제25조제4항)."},{"번호":3,"판정":"옳음","설명":"확인·설명서 교부일자는 거래계약서 기재사항이다(영 제22조제1항제8호)."},{"번호":4,"판정":"옳음","설명":"거래계약서의 보존기간은 5년이다(영 제22조제2항)."},{"번호":5,"판정":"틀림","설명":"서로 다른 둘 이상의 거래계약서 작성은 임의적 등록취소 사유다(법 제38조제2항제7호). 취소하여야 하는 것은 아니다."}],"개념":[{"종류":"표","제목":"거래계약서 관련 위반과 제재","머리":["위반 행위","개업공인중개사","소속공인중개사"],"행":[["거래금액 등을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서 작성","개설등록 취소 가능(법 제38조제2항제7호)","자격정지(법 제36조제1항제6호)"],["거래계약서를 작성·교부하지 않거나 보존하지 않음","업무정지(법 제39조제1항제8호)","해당 규정 없음"],["거래계약서에 서명 및 날인을 하지 않음","업무정지(법 제39조제1항제9호)","자격정지(법 제36조제1항제5호)"]]},{"종류":"표","제목":"거래계약서 기재사항(영 제22조제1항)","머리":["호","기재사항"],"행":[["1","거래당사자의 인적 사항"],["2","물건의 표시"],["3","계약일"],["4","거래금액·계약금액 및 그 지급일자 등 지급에 관한 사항"],["5","물건의 인도일시"],["6","권리이전의 내용"],["7","계약의 조건이나 기한이 있는 경우에는 그 조건 또는 기한"],["8","중개대상물확인·설명서 교부일자"],["9","그 밖의 약정내용"]]}],"함정":"제38조제1항(취소하여야 한다)과 제2항(취소할 수 있다)의 구분이 쟁점이다. 거래계약서 허위 기재와 이중 작성은 제2항이라 임의적 취소 사유다."},"31회-2차-038":{"한줄":"권리관계(등기부 기재사항), 거래예정금액, 실제 권리관계 또는 공시되지 않은 물건의 권리 사항(ㄱ, ㄷ, ㅁ)은 네 서식 모두에 있고, 비선호시설과 환경조건은 일부 서식에만 있다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식","원문":"② 권리관계 … 등기부 … ⑧ 거래예정금액 등 … ⑩ 실제 권리관계 또는 공시되지 않은물건의 권리 사항"},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호의2서식","원문":"② 권리관계 … 등기부 … ⑥ 거래예정금액 등 … ⑧ 실제 권리관계 또는 공시되지 않은 물건의 권리 사항"},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호의3서식","원문":"② 권리관계 … 등기부 … ⑥ 거래예정금액 등 … ⑧ 실제 권리관계"},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호의4서식","원문":"② 권리관계 … 등기부 … ⑤ 거래예정금액 … ⑦ 실제 권리관계 또는"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄴ(비선호시설)은 [Ⅱ]와 [Ⅳ] 서식에 없다."},{"번호":2,"판정":"틀림","설명":"ㄴ(비선호시설)과 ㄹ(환경조건)은 일부 서식에만 있다."},{"번호":3,"판정":"옳음","설명":"ㄱ, ㄷ, ㅁ이 네 서식에 모두 있어 이 조합이 맞다."},{"번호":4,"판정":"틀림","설명":"ㄹ(환경조건)은 [Ⅰ] 주거용 서식에만 있다."},{"번호":5,"판정":"틀림","설명":"ㄴ, ㄹ은 네 서식에 공통으로 있지 않다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"권리관계의 등기부 기재사항은 [Ⅰ]~[Ⅳ] 서식에 모두 있다."},{"기호":"ㄴ","판정":"틀림","설명":"비선호시설(1km이내)은 [Ⅰ]과 [Ⅲ] 서식에만 있다."},{"기호":"ㄷ","판정":"옳음","설명":"거래예정금액은 네 서식 모두에 있다."},{"기호":"ㄹ","판정":"틀림","설명":"환경조건(일조량·소음·진동)은 [Ⅰ] 서식에만 있다."},{"기호":"ㅁ","판정":"옳음","설명":"실제 권리관계 또는 공시되지 않은 물건의 권리 사항은 네 서식의 세부 확인사항에 모두 있다."}],"개념":[{"종류":"표","제목":"확인·설명서 서식별 항목([Ⅰ]~[Ⅳ])","머리":["항목","[Ⅰ] 주거용","[Ⅱ] 비주거용","[Ⅲ] 토지","[Ⅳ] 입목·광업재단·공장재단"],"행":[["권리관계(등기부 기재사항)","있음","있음","있음","있음"],["거래예정금액 등","있음","있음","있음","있음"],["취득 시 부담할 조세의 종류 및 세율","있음","있음","있음","있음"],["실제 권리관계 또는 공시되지 않은 물건의 권리 사항(세부)","있음","있음","있음","있음"],["비선호시설(1km이내)","있음","없음","있음","없음"],["환경조건(일조량·소음·진동)","있음","없음","없음","없음"],["입지조건","있음","있음","있음","없음"]]}],"함정":"비선호시설은 주거용과 토지 서식에, 환경조건은 주거용 서식에만 있다. 네 서식 모두에 있는 항목은 권리관계, 취득 시 부담할 조세, 거래예정금액, 실제 권리관계다."},"31회-2차-016":{"한줄":"공제금으로 손해배상을 한 때에는 15일 이내에 다시 가입해야 하므로 30일이라고 한 ⑤가 틀리다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제26조제2항","원문":"개업공인중개사는 보증보험금ㆍ공제금 또는 공탁금으로 손해배상을 한 때에는 15일 이내에 보증보험 또는 공제에 다시 가입하거나 공탁금 중 부족하게 된 금액을 보전하여야 한다."},{"법령":"공인중개사법","조문":"법 제30조제3항","원문":"개업공인중개사는 업무를 개시하기 전에 제1항 및 제2항에 따른 손해배상책임을 보장하기 위하여 대통령령으로 정하는 바에 따라 보증보험 또는 제42조에 따른 공제에 가입하거나 공탁을 하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제25조제1항","원문":"제24조의 규정에 따라 보증을 설정한 개업공인중개사는 그 보증을 다른 보증으로 변경하고자 하는 경우에는 이미 설정한 보증의 효력이 있는 기간 중에 다른 보증을 설정하고 그 증명서류를 갖추어 등록관청에 신고하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제25조제2항","원문":"그 보증기간 만료일까지 다시 보증을 설정하고 그 증명서류를 갖추어 등록관청에 신고하여야 한다."},{"법령":"공인중개사법","조문":"법 제38조제2항제8호","원문":"8. 제30조제3항에 따른 손해배상책임을 보장하기 위한 조치를 이행하지 아니하고 업무를 개시한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"업무를 개시하기 전에 보증보험·공제 가입 또는 공탁을 해야 한다(법 제30조제3항)."},{"번호":2,"판정":"옳음","설명":"보증 변경은 이미 설정한 보증의 효력이 있는 기간 중에 다른 보증을 설정해서 한다(영 제25조제1항)."},{"번호":3,"판정":"옳음","설명":"보증기간이 만료되어 다시 설정하려면 만료일까지 설정한다(영 제25조제2항)."},{"번호":4,"판정":"옳음","설명":"보장 조치 없이 업무를 개시하면 등록관청은 개설등록을 취소할 수 있다(법 제38조제2항제8호)."},{"번호":5,"판정":"틀림","설명":"공제금으로 배상한 때의 재가입·보전 기한은 15일 이내다(영 제26조제2항). 30일이 아니다."}],"개념":[{"종류":"표","제목":"손해배상책임의 보장 정리","머리":["항목","내용","근거"],"행":[["배상 대상","중개행위로 고의·과실에 의한 재산상 손해, 중개사무소를 다른 사람의 중개행위 장소로 제공하여 입힌 재산상 손해","법 제30조제1항·제2항"],["보장 조치 시기","업무를 개시하기 전에 보증보험·공제 가입 또는 공탁","법 제30조제3항"],["설정 금액","법인 4억원 이상(분사무소마다 2억원 이상 추가), 법인이 아니면 2억원 이상, 다른 법률에 따라 중개업을 하는 자 2천만원 이상","영 제24조제1항·제3항"],["설정 신고","증명서류를 갖추어 등록관청에 신고. 보증기관이 직접 통보하면 신고 생략 가능","영 제24조제2항"],["보증 변경","이미 설정한 보증의 효력이 있는 기간 중에 다른 보증을 설정","영 제25조제1항"],["보증기간 만료","만료일까지 다시 보증을 설정","영 제25조제2항"],["보험금 지급 후","15일 이내에 보증보험 또는 공제에 다시 가입하거나 공탁금 부족액 보전","영 제26조제2항"],["공탁금 회수","폐업 또는 사망한 날부터 3년 이내에는 회수 불가","법 제30조제4항"],["중개 완성 시 설명","보장금액, 보증보험회사·공제사업자·공탁기관 및 소재지, 보장기간을 설명하고 증서 사본 교부 또는 전자문서 제공","법 제30조제5항"],["미이행 제재","조치 없이 업무를 개시하면 개설등록 취소 가능","법 제38조제2항제8호"]]},{"종류":"표","제목":"중개 실무에서 자주 비교되는 기한","머리":["항목","기한","근거"],"행":[["자격취소 후 자격증 반납","처분을 받은 날부터 7일 이내","규칙 제21조"],["고용관계 종료 신고","종료일부터 10일 이내","규칙 제8조제4항"],["거래정보사업자 운영규정 승인","지정받은 날부터 3개월 이내","법 제24조제3항"],["보험금 등으로 배상한 후 재가입·보전","15일 이내","영 제26조제2항"],["공탁금 회수 제한","폐업 또는 사망한 날부터 3년 이내 회수 불가","법 제30조제4항"],["확인·설명서 보존","3년","영 제21조제4항"],["거래계약서 보존","5년","영 제22조제2항"]]}],"함정":"보증 변경은 기존 보증의 효력이 있는 기간 중에, 만료 후 재설정은 만료일까지, 배상 후 재가입은 15일 이내다. 세 기한의 기산점이 서로 다르다."},"31회-2차-035":{"한줄":"개발제한 등 공법상 규제는 영 별표 1 신고사항에 없어 신고사항에 포함되지 않는다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제3조제1항","원문":"① 법 제3조제1항 각 호 외의 부분 본문에서 \"그 실제 거래가격 등 대통령령으로 정하는 사항\"이란 별표 1에서 정하는 사항을 말한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 별표 1 제3호 구분","원문":"법인 외의 자가 실제 거래가격이 6억원 이상인 주택을 매수하거나 투기과열지구 또는 조정대상지역에 소재하는 주택을 매수하는 경우(매수인 중 국가등이 포함되어 있는 경우는 제외한다)"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제2조제6항","원문":"⑥ 영 별표 1 제2호나목, 같은 표 제3호가목 전단, 같은 호 나목, 같은 표 제3호의2에 따른 사항을 신고해야 하는 경우에는 제1항부터 제4항까지의 규정에 따라 신고서를 제출할 때 매수인이 단독으로 서명 또는 날인한 별지 제1호의3서식의 주택취득자"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"별지 제1호서식 작성방법 6","원문":"6. ⑦ “계약대상 면적”란에는 실제 거래면적을 계산하여 적되, 건축물 면적은 집합건축물의 경우 전용면적을 적고, 그 밖의 건축물의 경우 연면적을 적습니다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"별지 제1호서식 작성방법 7","원문":"7. ⑧ “물건별 거래가격”란에는 각각의 부동산별 거래가격을 적습니다. 최초 공급계약(분양) 또는 전매계약(분양권, 입주권)의 경우 분양가격, 발코니 확장 등 선택비용 및 추가 지급액 등(프리미엄 등 분양가격을 초과 또는 미달하는 금액)을 각각 적습니다. 이 경우 각각의 비용에 부가가치세가 있는 경우 부가가치세를 포함한 금액으로 적습니다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제28조제3항","원문":"③ 제3조제1항부터 제4항까지 또는 제4조제2호를 위반하여 그 신고를 거짓으로 한 자에게는 해당 부동산등의 취득가액의 100분의 10 이하에 상당하는 금액의 과태료를 부과한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제26조제1항","원문":"① 부당하게 재물이나 재산상 이득을 취득하거나 제3자로 하여금 이를 취득하게 할 목적으로 제4조제4호 또는 제5호를 위반하여 거짓으로 제3조 또는 제3조의2에 따라 신고한 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공법상의 개발제한 등은 영 별표 1의 신고사항에 없다(영 제3조제1항, 별표 1)."},{"번호":2,"판정":"틀림","설명":"자금조달·입주계획서는 매수인이 단독으로 서명 또는 날인해 제출한다(규칙 제2조제6항). 투기과열지구 주택은 가격과 관계없이 제출 대상이다(영 별표 1 제3호)."},{"번호":3,"판정":"틀림","설명":"물건별 거래가격란에는 분양가격, 발코니 확장 등 선택비용, 추가 지급액을 각각 적는다. 선택비용도 적는 칸이다(서식 작성방법 7)."},{"번호":4,"판정":"틀림","설명":"집합건축물은 전용면적, 그 밖의 건축물은 연면적이다. 반대로 서술했다(서식 작성방법 6)."},{"번호":5,"판정":"틀림","설명":"실제 거래가격을 거짓으로 신고한 경우의 제재는 취득가액의 100분의 10 이하 과태료다(법 제28조제3항). 벌금형은 계약이 없는데 부당이득 목적으로 거짓 신고한 경우다(법 제26조제1항)."}],"개념":[{"종류":"표","제목":"주택 매수 시 자금조달·입주계획 신고 대상(영 별표 1 제3호·제3호의2)","머리":["구분","신고 여부","비고"],"행":[["투기과열지구 소재 주택","가격과 관계없이 신고","자금조달계획 증명서류 첨부"],["조정대상지역 소재 주택","가격과 관계없이 신고",""],["그 밖의 지역 주택","실제 거래가격 6억원 이상이면 신고","6억원 미만은 신고 대상 아님"],["매수인 중 국가등이 포함","제외","매도인이 국가등인 경우는 제외 사유 아님"],["토지거래허가구역 소재 주택","허가를 받아 매수하면 신고(제3호의2)","자금조달계획 증명서류 첨부"],["제출 서식","별지 제1호의3서식, 매수인이 단독으로 서명 또는 날인","규칙 제2조제6항"]]},{"종류":"표","제목":"거짓 신고의 제재(법 제26조·제28조)","머리":["행위","제재","근거"],"행":[["실제 거래가격을 거짓으로 신고","취득가액의 100분의 10 이하 과태료","법 제28조제3항"],["계약을 체결하지 않았는데 거짓으로 신고(제4조제4호)","3천만원 이하 과태료","법 제28조제1항제1호"],["위 거짓 신고 중 부당한 이득을 얻을 목적","3년 이하의 징역 또는 3천만원 이하의 벌금","법 제26조제1항"],["해제등이 없는데 거짓으로 해제등 신고(제4조제5호)","3천만원 이하 과태료(부당이득 목적이면 법 제26조제1항)","법 제28조제1항제2호"]]}],"함정":"④는 면적 기준을 서로 바꿔 써서 틀리고, ⑤는 과태료와 벌금의 구별이 요점이다. ②는 투기과열지구에서 금액 기준이 없고 서명 주체가 매수인 단독이라는 두 점을 놓치기 쉽다.","개정":"2023.4.18 법 제26조제1항이 신설되어 부당이득 목적의 거짓 신고(제4조제4호·제5호 위반)는 3년 이하의 징역 또는 3천만원 이하의 벌금이다. 선지 ⑤는 실제 거래가격 거짓 신고(과태료)로 한정해 틀린 문장으로 유지했다. 자금조달 대상은 투기과열지구·조정대상지역 주택 전부와 6억원 이상 주택이다(영 별표 1 제3호 <개정 2025.12.9>)."},"31회-2차-040":{"한줄":"신고관청은 권리 대상 부동산 소재지를 관할하는 시장·군수·구청장이고, 구가 없는 시의 시장, 특별자치시장, 특별자치도 행정시의 시장도 포함한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제3조제1항","원문":"① 거래당사자는 다음 각 호의 어느 하나에 해당하는 계약을 체결한 경우 그 실제 거래가격 등 대통령령으로 정하는 사항을 거래계약의 체결일부터 30일 이내에 그 권리의 대상인 부동산등(권리에 관한 계약의 경우에는 그 권리의 대상인 부동산을 말한다)의 소재지를 관할하는 시장(구가 설치되지 아니한 시의 시장 및 특별자치시장과 특별자치도 행정시의 시장을 말한다)ㆍ군수 또는 구청장(이하 \"신고관청\"이라 한다)에게 공동으로 신고하여야 한다. 다만, 거래당사자 중 일방이 국가, 지방자치단체, 대통령령으로 정하는 자의 경우(이하 \"국가등\"이라 한다)에는 국가등이 신고를 하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제3조제3항","원문":"③ 「공인중개사법」 제2조제4호에 따른 개업공인중개사(이하 \"개업공인중개사\"라 한다)가 같은 법 제26조제1항에 따라 거래계약서를 작성ㆍ교부한 경우에는 제1항에도 불구하고 해당 개업공인중개사가 같은 항에 따른 신고를 하여야 한다. 이 경우 공동으로 중개를 한 경우에는 해당 개업공인중개사가 공동으로 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제2조제2항","원문":"② 법 제3조제1항 단서에 따라 단독으로 부동산 거래계약을 신고하려는 국가, 지방자치단체 또는 「부동산 거래신고 등에 관한 법률 시행령」(이하 \"영\"이라 한다) 제3조제2항 각 호의 기관(이하 \"국가등\"이라 한다)은 부동산거래계약 신고서에 단독으로 서명 또는 날인하여 신고관청에 제출해야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제2조제4항","원문":"④ 법 제3조제3항에 따라 부동산 거래계약을 신고하려는 개업공인중개사(「공인중개사법」 제2조제4호에 따른 개업공인중개사를 말한다. 이하 같다)는 부동산거래계약 신고서에 서명 또는 날인한 후 이 조 제3항제1호 및 제2호의 서류를 첨부하여 신고관청에 제출해야 한다. 이 경우 법 제3조제3항 후단에 따라 신고하는 경우에는 해당 개업공인중개사가 공동으로 서명 또는 날인해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"신고 기한은 계약 체결일부터 30일이다. 3개월이 아니다(법 제3조제1항)."},{"번호":2,"판정":"틀림","설명":"한쪽이 국가등(매수인 국가)이면 국가가 신고한다. 매도인과 공동으로 신고하지 않는다(법 제3조제1항 단서, 규칙 제2조제2항)."},{"번호":3,"판정":"옳음","설명":"권리 대상 부동산 소재지 관할의 구가 설치되지 않은 시의 시장, 특별자치시장, 특별자치도 행정시의 시장이 신고관청이다(법 제3조제1항)."},{"번호":4,"판정":"틀림","설명":"개업공인중개사가 거래계약서를 작성·교부한 경우에는 해당 개업공인중개사가 신고해야 한다(법 제3조제3항). 거래당사자와 선택하는 구조가 아니다."},{"번호":5,"판정":"틀림","설명":"개업공인중개사는 신고서를 신고관청에 제출한다. 등록관청이 아니다(규칙 제2조제4항)."}],"개념":[{"종류":"표","제목":"신고 주체와 방법(법 제3조)","머리":["상황","신고 주체·방법","근거"],"행":[["거래당사자 직접거래","거래당사자가 공동으로 신고. 계약 체결일부터 30일 이내","법 제3조제1항"],["일방이 국가등","국가등이 신고하고 서명 또는 날인도 국가등이 단독으로 한다","법 제3조제1항 단서, 규칙 제2조제2항"],["국가등의 범위","국가, 지방자치단체, 공공기관, 지방직영기업·지방공사·지방공단","법 제3조제1항 단서, 영 제3조제2항"],["개업공인중개사가 거래계약서를 작성·교부","개업공인중개사가 신고. 공동중개이면 공동으로 신고","법 제3조제3항"],["일방이 신고 거부","다른 일방이 단독 신고. 거래계약서 사본, 계약금 지급 확인 서류, 단독신고사유서 첨부","법 제3조제2항·제4항, 규칙 제2조제3항"],["소속공인중개사","개업공인중개사의 위임을 받아 제출을 대행하고 신분증명서를 보여준다","규칙 제5조제2항"]]},{"종류":"흐름","제목":"부동산 거래신고 절차","단계":[{"이름":"신고서 작성","설명":"거래계약 체결일부터 30일 이내에 별지 제1호서식 작성. 직접거래는 당사자 공동 서명 또는 날인"},{"이름":"제출","설명":"권리 대상 부동산 소재지 신고관청(시장·군수·구청장, 구가 없는 시의 시장·특별자치시장·특별자치도 행정시 시장 포함)에 제출. 신분증명서 제시"},{"이름":"신고필증 발급","설명":"신고내용 확인 후 지체 없이 발급(법 제3조제5항). 규칙상 신고서가 제출된 때 별지 제2호서식으로 발급"},{"이름":"검인 간주","설명":"신고인이 신고필증을 발급받은 때 부동산등의 매수인은 부동산등기 특별조치법 제3조제1항의 검인을 받은 것으로 봄"},{"이름":"정정·변경·해제등","설명":"잘못 기재 시 정정 신청, 등기신청 전 변경신고, 해제등 확정일부터 30일 이내 해제등 신고"}]}],"함정":"신고관청(부동산 소재지)과 등록관청(중개사무소 소재지)은 다른 개념이다. 신고 의무자 구분에서 개업공인중개사는 '할 수 있다'가 아니라 '하여야 한다'이다."},"31회-2차-027":{"한줄":"국제연합은 영 제2조제1호의 국제기구로서 외국인등에 포함되고, 매매는 거래신고(30일), 상속은 6개월 취득신고이며, 상수원보호구역은 외국인등의 허가 지역이 아니다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제2조제1호","원문":"1. 국제연합과 그 산하기구ㆍ전문기구"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제8조제1항","원문":"① 외국인등이 대한민국 안의 부동산등을 취득하는 계약(제3조제1항 각 호에 따른 계약은 제외한다)을 체결하였을 때에는 계약체결일부터 60일 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제8조제2항","원문":"② 외국인등이 상속ㆍ경매, 그 밖에 대통령령으로 정하는 계약 외의 원인으로 대한민국 안의 부동산등을 취득한 때에는 부동산등을 취득한 날부터 6개월 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제9조제1항","원문":"① 제3조 및 제8조에도 불구하고 외국인등이 취득하려는 토지가 다음 각 호의 어느 하나에 해당하는 구역ㆍ지역 등에 있으면 토지를 취득하는 계약(이하 \"토지취득계약\"이라 한다)을 체결하기 전에 대통령령으로 정하는 바에 따라 신고관청으로부터 토지취득의 허가를 받아야 한다. 다만, 제11조에 따라 토지거래계약에 관한 허가를 받은 경우에는 그러하지 아니하다. … 3. 「자연환경보전법」 제2조제12호에 따른 생태ㆍ경관보전지역"}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ만 옳다. 국제연합과 그 산하기구는 외국인등이다(영 제2조제1호)."},{"번호":2,"판정":"틀림","설명":"ㄱ은 옳지만 ㄹ이 틀리다. 수도법상 상수원보호구역은 법 제9조제1항에 열거된 구역이 아니다."},{"번호":3,"판정":"틀림","설명":"ㄴ(매매는 거래신고 30일)과 ㄷ(상속은 6개월)이 모두 틀리고, 옳은 ㄱ이 빠져 있다."},{"번호":4,"판정":"틀림","설명":"ㄴ(매매는 30일 거래신고)과 ㄹ(상수원보호구역은 허가 지역이 아님)이 틀린 보기다."},{"번호":5,"판정":"틀림","설명":"ㄴ(매매는 30일 거래신고), ㄷ(상속은 6개월), ㄹ(허가 지역이 아님)이 모두 틀린 보기다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"국제연합과 그 산하기구는 외국인등에 포함된다(영 제2조제1호)."},{"기호":"ㄴ","판정":"틀림","설명":"매매계약은 법 제3조제1항에 따른 거래신고 대상이고 계약체결일부터 30일 이내에 신고한다. 60일 취득신고 대상이 아니다(법 제8조제1항 괄호)."},{"기호":"ㄷ","판정":"틀림","설명":"상속으로 취득한 때에는 취득한 날부터 6개월 이내에 신고한다(법 제8조제2항). 1년이 아니다."},{"기호":"ㄹ","판정":"틀림","설명":"상수원보호구역은 법 제9조제1항의 허가 대상 구역이 아니다."}],"개념":[{"종류":"표","제목":"외국인등의 부동산 취득·보유 신고(법 제8조, 영 제5조)","머리":["취득 원인","신고 기한","근거"],"행":[["매매·공급계약 등 법 제3조제1항 각 호의 계약","계약 체결일부터 30일 이내 거래신고(취득신고 대상 아님)","법 제3조, 제8조제1항 괄호"],["그 밖의 취득 계약(증여 등)","계약 체결일부터 60일 이내 취득신고","법 제8조제1항"],["상속·경매","취득한 날부터 6개월 이내","법 제8조제2항"],["환매권 행사, 법원의 확정판결, 법인의 합병, 건축물의 신축·증축·개축·재축","취득한 날부터 6개월 이내","법 제8조제2항, 영 제5조제2항"],["국민·국내 법인이 외국인등으로 변경되어 계속 보유","외국인등으로 변경된 날부터 6개월 이내 계속보유 신고","법 제8조제3항"]]},{"종류":"표","제목":"외국인등의 토지취득 허가(법 제9조, 영 제6조)","머리":["항목","내용"],"행":[["허가 지역","군사기지 및 군사시설 보호구역 등, 지정문화유산과 보호물·보호구역, 천연기념물등과 보호물·보호구역, 생태·경관보전지역, 야생생물 특별보호구역"],["허가 시기·허가권자","토지취득계약 체결 전에 신고관청의 허가"],["처리기간","군사기지 등 국방목적 구역·지역은 30일, 그 밖의 구역·지역은 15일(부득이하면 군사기지 등은 30일 범위에서 연장)"],["예외","법 제11조에 따른 토지거래계약 허가를 받은 경우"],["위반 효과","허가 없이 체결한 토지취득계약은 효력이 발생하지 않는다(법 제9조제3항)"]]}],"함정":"ㄴ은 매매이므로 취득신고가 아니라 거래신고(30일)다. ㄷ의 상속은 6개월이다. ㄹ의 허가 지역은 군사시설 보호구역, 지정문화유산, 천연기념물, 생태·경관보전지역, 야생생물 특별보호구역으로 한정된다."},"31회-2차-026":{"한줄":"허가받은 목적대로 이용하지 않고 방치해 이행명령을 이행하지 않으면 토지 취득가액의 100분의 10에 상당하는 이행강제금을 부과한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제18조제3항","원문":"③ 시장ㆍ군수 또는 구청장은 최초의 이행명령이 있었던 날을 기준으로 1년에 한 번씩 그 이행명령이 이행될 때까지 반복하여 제2항에 따른 이행강제금을 부과ㆍ징수할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제18조제5항","원문":"⑤ 시장ㆍ군수 또는 구청장은 제1항에 따른 이행명령을 받은 자가 그 명령을 이행하는 경우에는 새로운 이행강제금의 부과를 즉시 중지하되, 명령을 이행하기 전에 이미 부과된 이행강제금은 징수하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제18조제6항","원문":"⑥ 제2항에 따른 이행강제금의 부과처분에 불복하는 자는 시장ㆍ군수 또는 구청장에게 이의를 제기할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제16조제1항","원문":"① 법 제18조제1항 본문에 따른 이행명령은 문서로 하여야 하며, 이행기간은 3개월 이내로 정하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제16조제3항제1호","원문":"1. 토지거래계약허가를 받아 토지를 취득한 자가 당초의 목적대로 이용하지 아니하고 방치한 경우: 토지 취득가액의 100분의 10에 상당하는 금액"}],"선지":[{"번호":1,"판정":"틀림","설명":"이행명령은 문서로 한다(영 제16조제1항). 구두가 아니다."},{"번호":2,"판정":"옳음","설명":"방치한 경우 이행강제금은 취득가액의 100분의 10이다(영 제16조제3항제1호)."},{"번호":3,"판정":"틀림","설명":"불복하여 이의를 제기할 수 있다는 명문 규정이 있다(법 제18조제6항)."},{"번호":4,"판정":"틀림","설명":"이행명령을 이행하면 새 부과는 중지하지만 이미 부과된 이행강제금은 징수한다(법 제18조제5항)."},{"번호":5,"판정":"틀림","설명":"최초의 이행명령이 있었던 날을 기준으로 1년에 한 번씩 반복 부과한다(법 제18조제3항). 두 번이 아니다."}],"개념":[{"종류":"표","제목":"이행강제금 금액(법 제18조제2항, 영 제16조제3항)","머리":["위반 유형","금액(토지 취득가액 기준)"],"행":[["당초 목적대로 이용하지 않고 방치","100분의 10"],["직접 이용하지 않고 임대","100분의 7"],["허가관청의 승인 없이 이용목적 변경","100분의 5"],["위 세 가지에 해당하지 않는 경우","100분의 7"]]},{"종류":"흐름","제목":"이행명령과 이행강제금(법 제18조, 영 제16조)","단계":[{"이름":"이행명령","설명":"문서로 하고 이행기간은 3개월 이내로 정한다(영 제16조제1항)"},{"이름":"계고","설명":"이행기간 내 이행하지 않으면 이행강제금을 부과·징수한다는 뜻을 미리 문서로 계고(영 제16조제5항)"},{"이름":"부과","설명":"이행명령이 이행되지 않으면 이행강제금 부과. 최초 이행명령이 있었던 날을 기준으로 1년에 한 번씩 반복 부과(법 제18조제3항)"},{"이름":"이의제기","설명":"부과처분을 고지받은 날부터 30일 이내 시장·군수·구청장에게(영 제16조제7항, 법 제18조제6항)"},{"이름":"이행 시","설명":"새로운 이행강제금 부과는 즉시 중지, 이미 부과된 이행강제금은 징수(법 제18조제5항). 의무기간이 지나면 부과 불가(제4항)"}]}],"함정":"이행명령의 방식(문서, 3개월 이내)과 이행강제금 부과 횟수(1년에 한 번)를 바꿔 쓴 선지가 섞여 있다. 금액은 방치 100분의 10, 임대 100분의 7이다."},"31회-2차-028":{"한줄":"시·도지사가 허가구역을 지정하면 공고하고 그 내용을 국토교통부장관과 시장·군수·구청장에게 통지해야 한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제10조제1항","원문":"① 국토교통부장관 또는 시ㆍ도지사는 국토의 이용 및 관리에 관한 계획의 원활한 수립과 집행, 합리적인 토지 이용 등을 위하여 토지의 투기적인 거래가 성행하거나 지가(地價)가 급격히 상승하는 지역과 그러한 우려가 있는 지역으로서 대통령령으로 정하는 지역에 대해서는 다음 각 호의 구분에 따라 5년 이내의 기간을 정하여 제11조제1항에 따른 토지거래계약에 관한 허가구역(이하 \"허가구역\"이라 한다)으로 지정할 수 있다. 이 경우 국토교통부장관 또는 시ㆍ도지사는 대통령령으로 정하는 바에 따라 허가대상자(외국인등을 포함한다. 이하 이 조에서 같다), 허가대상 용도와 지목 등을 특정하여 허가구역을 지정할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제10조제2항","원문":"② 국토교통부장관 또는 시ㆍ도지사는 제1항에 따라 허가구역을 지정하려면 「국토의 계획 및 이용에 관한 법률」 제106조에 따른 중앙도시계획위원회(이하 \"중앙도시계획위원회\"라 한다) 또는 같은 법 제113조제1항에 따른 시ㆍ도도시계획위원회(이하 \"시ㆍ도도시계획위원회\"라 한다)의 심의를 거쳐야 한다. 다만, 지정기간이 끝나는 허가구역을 계속하여 다시 허가구역으로 지정하려면 중앙도시계획위원회 또는 시ㆍ도도시계획위원회의 심의 전에 미리 시ㆍ도지사(국토교통부장관이 허가구역을 지정하는 경우만 해당한다) 및 시장ㆍ군수 또는 구청장의 의견을 들어야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제10조제3항","원문":"③ 국토교통부장관 또는 시ㆍ도지사는 제1항에 따라 허가구역으로 지정한 때에는 지체 없이 허가대상자, 허가대상 용도와 지목 등 대통령령으로 정하는 사항을 공고하고, 그 공고 내용을 국토교통부장관은 시ㆍ도지사를 거쳐 시장ㆍ군수 또는 구청장에게 통지하고, 시ㆍ도지사는 국토교통부장관, 시장ㆍ군수 또는 구청장에게 통지하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제10조제5항","원문":"⑤ 허가구역의 지정은 제3항에 따라 허가구역의 지정을 공고한 날부터 5일 후에 그 효력이 발생한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제9조제1항제1호가목","원문":"가. 주거지역: 60제곱미터"}],"선지":[{"번호":1,"판정":"틀림","설명":"허가구역은 5년 이내의 기간을 정해 지정한다(법 제10조제1항). 7년이 아니다."},{"번호":2,"판정":"틀림","설명":"시·도지사가 지정하려면 시·도도시계획위원회의 심의를 거친다(법 제10조제2항). 인접 시·도지사의 의견을 듣는 규정은 없다."},{"번호":3,"판정":"옳음","설명":"시·도지사는 공고하고 그 내용을 국토교통부장관, 시장·군수·구청장에게 통지한다(법 제10조제3항)."},{"번호":4,"판정":"틀림","설명":"지정은 공고한 날부터 5일 후에 효력이 발생한다(법 제10조제5항). 3일이 아니다."},{"번호":5,"판정":"틀림","설명":"도시지역 주거지역의 허가 면제 면적은 60제곱미터이다(영 제9조제1항제1호가목). 600제곱미터가 아니다."}],"개념":[{"종류":"흐름","제목":"토지거래허가구역 지정 절차(법 제10조)","단계":[{"이름":"지정","설명":"국토교통부장관(둘 이상 시·도에 걸친 경우) 또는 시·도지사(같은 시·도 안의 일부지역). 5년 이내의 기간"},{"이름":"심의","설명":"중앙도시계획위원회 또는 시·도도시계획위원회의 심의. 재지정은 심의 전에 의견 청취"},{"이름":"공고·통지","설명":"지체 없이 공고하고 국토교통부장관은 시·도지사를 거쳐 시장·군수·구청장에게, 시·도지사는 국토교통부장관과 시장·군수·구청장에게 통지"},{"이름":"등기소 통지·공고","설명":"통지를 받은 시장·군수·구청장은 관할 등기소의 장에게 통지, 7일 이상 공고, 15일간 열람"},{"이름":"효력 발생","설명":"허가구역 지정을 공고한 날부터 5일 후"}]},{"종류":"표","제목":"허가 면제 면적(영 제9조제1항)","머리":["지역","기준 면적"],"행":[["도시지역 주거지역","60제곱미터"],["도시지역 상업지역","150제곱미터"],["도시지역 공업지역","150제곱미터"],["도시지역 녹지지역","200제곱미터"],["도시지역 중 용도지역 지정이 없는 구역","60제곱미터"],["도시지역 외의 지역","250제곱미터(농지 500제곱미터, 임야 1천제곱미터)"]]}],"함정":"지정 기간 5년, 효력 발생 5일, 면제 면적 주거지역 60제곱미터를 숫자만 바꿔 놓은 선지가 많다. 의견 청취는 지정기간이 끝나는 허가구역을 다시 지정할 때의 절차다."},"31회-2차-031":{"한줄":"계약명의신탁에서 매도인의 선의·악의는 계약 체결 당시를 기준으로 가리는 것이 판례이므로, 등기 이전 시에 비로소 알게 된 丙은 선의로 보아 X토지의 소유자는 甲이다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조제1항","원문":"명의신탁약정은 무효로 한다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조제2항","원문":"명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조제3항","원문":"제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"판례":"대법원 판례(매도인의 선의·악의 판단 시점)","요지":"계약명의신탁에서 매도인이 명의신탁약정을 알았는지는 매매계약을 체결할 당시를 기준으로 판단한다. 계약 체결 뒤 소유권이전등기 시에 비로소 안 경우는 선의로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"명의신탁약정은 매도인의 선의·악의와 관계없이 무효다(제4조제1항)."},{"번호":2,"판정":"틀림","설명":"매도인의 선의·악의는 계약 체결 당시를 기준으로 하므로, 등기할 때 비로소 안 丙은 선의다. 선의이면 甲이 소유권을 취득한다(제4조제2항 단서). 소유자는 丙이 아니다."},{"번호":3,"판정":"옳음","설명":"A와 甲의 약정이 무효이므로(제4조제1항) A는 甲에게 약정에 기해 소유권이전등기를 청구할 수 없다."},{"번호":4,"판정":"옳음","설명":"甲으로부터 X토지를 취득한 丁은 제4조제3항의 제3자로서 선의·악의와 관계없이 소유권을 취득한다."},{"번호":5,"판정":"옳음","설명":"丙이 약정을 알지 못했다면 수탁자 甲 명의의 물권변동은 유효하므로(제4조제2항 단서) 甲이 소유권을 취득한다."}],"개념":[{"종류":"비교","제목":"계약명의신탁에서 매도인이 선의일 때와 악의일 때","왼쪽":{"이름":"선의(계약 체결 당시 약정을 몰랐음)","항목":["수탁자 명의 등기와 물권변동 유효","수탁자가 소유권 취득","신탁자는 소유권이 없고 수탁자에게 대금 상당 부당이득반환 청구","수탁자로부터 취득한 제3자는 보호"]},"오른쪽":{"이름":"악의(계약 체결 당시 약정을 알았음)","항목":["수탁자 명의 등기와 물권변동 무효","매도인이 소유권 보유","수탁자는 소유권이 없음","수탁자로부터 취득한 제3자도 선의·악의 불문 보호(제4조제3항)"]}},{"종류":"표","제목":"명의신탁약정의 정의에서 제외되는 경우(제2조제1호)","머리":["목","내용"],"행":[["가","채무의 변제를 담보하기 위하여 채권자가 부동산에 관한 물권을 이전받거나 가등기하는 경우"],["나","부동산의 위치와 면적을 특정하여 2인 이상이 구분소유하기로 하는 약정을 하고 그 구분소유자의 공유로 등기하는 경우"],["다","「신탁법」 또는 「자본시장과 금융투자업에 관한 법률」에 따른 신탁재산인 사실을 등기한 경우"]]}],"함정":"②는 선의·악의의 기준 시점을 놓치게 만든다. 등기할 때 알았다는 것만으로 악의가 되지 않는다. ④·⑤는 선의일 때 수탁자가 소유권을 취득하고, 제3자는 선악 불문 보호된다는 두 규칙으로 풀린다."},"31회-2차-032":{"한줄":"보증금 10억원은 서울 기준 9억원을 넘는 환산보증금 초과 임대차이므로 확정일자를 받아도 우선변제권(제5조제2항)을 취득하지 못한다.","근거":[{"법령":"상가건물 임대차보호법","조문":"제2조제1항 단서","원문":"다만, 제14조의2에 따른 상가건물임대차위원회의 심의를 거쳐 대통령령으로 정하는 보증금액을 초과하는 임대차에 대하여는 그러하지 아니하다."},{"법령":"상가건물 임대차보호법","조문":"제2조제3항","원문":"제1항 단서에도 불구하고 제3조, 제10조제1항, 제2항, 제3항 본문, 제10조의2부터 제10조의9까지의 규정, 제11조의2 및 제19조는 제1항 단서에 따른 보증금액을 초과하는 임대차에 대하여도 적용한다."},{"법령":"상가건물 임대차보호법 시행령","조문":"시행령 제2조제1항제1호","원문":"다음 각 호의 구분에 의한 금액을 말한다. 1. 서울특별시 : 9억원"},{"법령":"상가건물 임대차보호법","조문":"제3조제1항","원문":"임대차는 그 등기가 없는 경우에도 임차인이 건물의 인도와 「부가가치세법」 제8조, 「소득세법」 제168조 또는 「법인세법」 제111조에 따른 사업자등록을 신청하면 그 다음 날부터 제3자에 대하여 효력이 생긴다."},{"법령":"상가건물 임대차보호법","조문":"제5조제2항","원문":"제3조제1항의 대항요건을 갖추고 관할 세무서장으로부터 임대차계약서상의 확정일자를 받은 임차인은 「민사집행법」에 따른 경매 또는 「국세징수법」에 따른 공매 시 임차건물(임대인 소유의 대지를 포함한다)의 환가대금에서 후순위권리자나 그 밖의 채권자보다 우선하여 보증금을 변제받을 권리가 있다."},{"법령":"상가건물 임대차보호법","조문":"제10조제1항 본문","원문":"임대인은 임차인이 임대차기간이 만료되기 6개월 전부터 1개월 전까지 사이에 계약갱신을 요구할 경우 정당한 사유 없이 거절하지 못한다. 다만, 다음 각 호의 어느 하나의 경우에는 그러하지 아니하다."},{"법령":"상가건물 임대차보호법","조문":"제10조제2항","원문":"임차인의 계약갱신요구권은 최초의 임대차기간을 포함한 전체 임대차기간이 10년을 초과하지 아니하는 범위에서만 행사할 수 있다."},{"법령":"상가건물 임대차보호법","조문":"제10조제3항","원문":"갱신되는 임대차는 전 임대차와 동일한 조건으로 다시 계약된 것으로 본다. 다만, 차임과 보증금은 제11조에 따른 범위에서 증감할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"사업자등록 신청일인 2020.3.10.의 다음 날 0시부터 대항력이 생긴다(제3조제1항). 제3조는 환산보증금 초과 임대차에도 적용된다(제2조제3항)."},{"번호":2,"판정":"틀림","설명":"제5조(우선변제권)는 환산보증금 초과 임대차에 적용되는 조문이 아니다(제2조제3항). 확정일자를 받은 3.13.에도 우선변제권을 취득하지 못한다."},{"번호":3,"판정":"옳음","설명":"임차인이 만료 6개월 전부터 1개월 전까지 갱신을 요구하면 정당한 사유 없이 거절하지 못한다(제10조제1항). 이 조항은 초과 임대차에도 적용된다."},{"번호":4,"판정":"옳음","설명":"갱신요구권은 최초 임대차기간을 포함한 전체 임대차기간이 10년을 넘지 않는 범위에서 행사할 수 있다(제10조제2항)."},{"번호":5,"판정":"옳음","설명":"갱신되는 임대차는 전 임대차와 동일한 조건으로 다시 계약된 것으로 본다(제10조제3항 본문)."}],"개념":[{"종류":"계산","제목":"환산보증금과 대항력 취득일","단계":[{"설명":"환산보증금 = 보증금 + 월차임 × 100","식":"10억원 + (0 × 100)","값":"10억원"},{"설명":"서울특별시 상한(시행령 제2조제1항제1호)과 비교","식":"10억원 > 9억원","값":"초과 임대차: 제5조 우선변제권 미적용"},{"설명":"대항력 = 인도 + 사업자등록 신청의 다음 날","식":"2020.3.10. + 1일","값":"2020.3.11."}]},{"종류":"표","제목":"환산보증금 이내와 초과의 적용 차이","머리":["규정","이내","초과"],"행":[["대항력(제3조)","적용","적용"],["우선변제권(제5조제2항)","적용","미적용"],["임차권등기명령(제6조)","적용","미적용"],["임대차기간 1년 의제(제9조)","적용","미적용"],["갱신요구권(제10조제1항~제3항 본문)","적용","적용"],["권리금(제10조의3~제10조의8)","적용","적용"],["차임·보증금 증감청구(제11조)","적용","제10조의2의 특례로 대체"],["최우선변제(제14조)","적용","미적용"]]}],"함정":"임차인이 확정일자를 받았다는 사실에 끌리면 ②가 옳아 보인다. 보증금이 서울 기준 9억원을 넘는 순간 우선변제권이 빠진다. 대항력·갱신요구권·권리금은 초과 임대차에도 적용되어 나머지 선지가 옳다."},"31회-2차-033":{"한줄":"임차권등기명령의 집행에 따른 임차권등기가 끝난 주택을 그 이후에 임차한 임차인 丁은 소액보증금의 최우선변제를 받을 권리가 없다(제3조의3제6항).","근거":[{"법령":"주택임대차보호법","조문":"제3조의3제2항","원문":"임차권등기명령의 신청서에는 다음 각 호의 사항을 적어야 하며, 신청의 이유와 임차권등기의 원인이 된 사실을 소명(疎明)하여야 한다. 1. 신청의 취지 및 이유 2. 임대차의 목적인 주택(임대차의 목적이 주택의 일부분인 경우에는 해당 부분의 도면을 첨부한다) 3. 임차권등기의 원인이 된 사실(임차인이 제3조제1항ㆍ제2항 또는 제3항에 따른 대항력을 취득하였거나 제3조의2제2항에 따른 우선변제권을 취득한 경우에는 그 사실) 4. 그 밖에 대법원규칙으로 정하는 사항"},{"법령":"주택임대차보호법","조문":"제3조의3제5항","원문":"임차인은 임차권등기명령의 집행에 따른 임차권등기를 마치면 제3조제1항ㆍ제2항 또는 제3항에 따른 대항력과 제3조의2제2항에 따른 우선변제권을 취득한다. 다만, 임차인이 임차권등기 이전에 이미 대항력이나 우선변제권을 취득한 경우에는 그 대항력이나 우선변제권은 그대로 유지되며, 임차권등기 이후에는 제3조제1항ㆍ제2항 또는 제3항의 대항요건을 상실하더라도 이미 취득한 대항력이나 우선변제권을 상실하지 아니한다."},{"법령":"주택임대차보호법","조문":"제3조의3제6항","원문":"임차권등기명령의 집행에 따른 임차권등기가 끝난 주택(임대차의 목적이 주택의 일부분인 경우에는 해당 부분으로 한정한다)을 그 이후에 임차한 임차인은 제8조에 따른 우선변제를 받을 권리가 없다."},{"법령":"주택임대차보호법","조문":"제3조의3제8항","원문":"임차인은 제1항에 따른 임차권등기명령의 신청과 그에 따른 임차권등기와 관련하여 든 비용을 임대인에게 청구할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"신청서에 신청의 취지 및 이유를 적고, 신청의 이유와 임차권등기의 원인이 된 사실을 소명해야 한다(제3조의3제2항)."},{"번호":2,"판정":"틀림","설명":"임차권등기명령의 신청과 그에 따른 임차권등기와 관련하여 든 비용을 모두 임대인에게 청구할 수 있다(제3조의3제8항)."},{"번호":3,"판정":"틀림","설명":"임차권등기를 마치면 대항력과 우선변제권을 취득하고, 이미 취득한 경우에는 그대로 유지한다(제3조의3제5항). 우선변제권도 유지된다."},{"번호":4,"판정":"틀림","설명":"임차권등기 이후에는 대항요건(주민등록)을 상실하더라도 이미 취득한 대항력이나 우선변제권을 상실하지 않는다(제3조의3제5항 단서)."},{"번호":5,"판정":"옳음","설명":"임차권등기가 끝난 주택을 그 이후에 임차한 임차인은 소액보증금의 우선변제(제8조)를 받을 권리가 없다(제3조의3제6항)."}],"개념":[{"종류":"표","제목":"임차권등기명령의 신청과 효과(제3조의3)","머리":["구분","내용"],"행":[["신청 요건","임대차가 끝난 후 보증금이 반환되지 않은 경우(제1항)"],["관할","임차주택 소재지의 지방법원·지방법원지원 또는 시·군 법원(제1항)"],["신청서","신청의 취지 및 이유, 목적 주택, 등기원인 사실, 소명(제2항)"],["기각 결정","임차인은 항고 가능(제4항)"],["등기 효과","대항력·우선변제권 취득 또는 유지. 등기 후 대항요건 상실해도 유지(제5항)"],["이후 임차인","소액보증금 우선변제 불가(제6항)"],["비용","신청과 등기 관련 비용을 임대인에게 청구 가능(제8항)"]]},{"종류":"비교","제목":"임차권등기 전에 이미 권리를 가진 임차인과 등기로 비로소 취득하는 임차인","왼쪽":{"이름":"등기 전에 이미 대항력·우선변제권을 가진 임차인","항목":["그 권리가 그대로 유지됨","등기 후 이사하거나 주민등록을 옮겨도 상실하지 않음"]},"오른쪽":{"이름":"대항력·우선변제권이 없던 임차인","항목":["임차권등기를 마치면 새로 취득함","취득 시기는 등기를 마친 때"]}}],"함정":"③은 대항력만 유지되고 우선변제권은 잃는다고 보게 만든다. 둘 다 유지된다. ⑤는 임차권등기가 끝난 주택의 후행 임차인에게 소액보증금 최우선변제가 인정되지 않는다는 규정이다."},"31회-2차-036":{"한줄":"경매개시결정의 기입등기로 압류의 효력이 생긴 뒤에 취득한 유치권으로는 매수인에게 대항할 수 없으므로, 매수인은 그 유치권으로 담보하는 채권을 변제할 책임이 없다.","근거":[{"법령":"민사집행법","조문":"민사집행법 제91조제5항","원문":"매수인은 유치권자(留置權者)에게 그 유치권(留置權)으로 담보하는 채권을 변제할 책임이 있다."},{"판례":"대법원 판례(압류 후 취득한 유치권)","요지":"경매개시결정의 기입등기가 마쳐져 압류의 효력이 생긴 뒤에 채무자가 점유를 이전하여 취득시킨 유치권은 경매절차의 매수인에게 대항할 수 없다."},{"법령":"민사집행법","조문":"민사집행법 제114조제2항","원문":"차순위매수신고는 그 신고액이 최고가매수신고액에서 그 보증액을 뺀 금액을 넘는 때에만 할 수 있다."},{"법령":"민사집행법","조문":"민사집행법 제135조","원문":"매수인은 매각대금을 다 낸 때에 매각의 목적인 권리를 취득한다."},{"법령":"민사집행법","조문":"민사집행법 제138조제4항","원문":"재매각절차에서는 전의 매수인은 매수신청을 할 수 없으며 매수신청의 보증을 돌려 줄 것을 요구하지 못한다."},{"법령":"민사집행법","조문":"민사집행법 제91조제2항","원문":"매각부동산 위의 모든 저당권은 매각으로 소멸된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"매수인이 변제할 책임을 지는 것은 매수인에게 대항할 수 있는 유치권이다(제91조제5항). 압류의 효력이 생긴 뒤에 취득한 유치권은 대항할 수 없어 변제 책임이 없다(판례)."},{"번호":2,"판정":"옳음","설명":"차순위매수신고는 신고액이 최고가매수신고액에서 보증액을 뺀 금액을 넘는 때에만 할 수 있다(제114조제2항)."},{"번호":3,"판정":"옳음","설명":"매수인은 매각대금을 다 낸 때에 매각의 목적인 권리를 취득한다(제135조)."},{"번호":4,"판정":"옳음","설명":"재매각절차에서 전의 매수인은 매수신청을 할 수 없고 매수신청의 보증을 돌려 줄 것을 요구하지 못한다(제138조제4항)."},{"번호":5,"판정":"옳음","설명":"후순위 저당권자가 경매를 신청해도 매각부동산 위의 모든 저당권은 매각으로 소멸된다(제91조제2항)."}],"개념":[{"종류":"비교","제목":"압류 전에 취득한 유치권과 압류 후에 취득한 유치권","왼쪽":{"이름":"압류의 효력 발생 전에 성립한 유치권","항목":["매수인에게 대항할 수 있음","매수인은 유치권으로 담보하는 채권을 변제할 책임이 있음(제91조제5항)","유치권자는 변제를 받을 때까지 목적물의 인도를 거절할 수 있음"]},"오른쪽":{"이름":"경매개시결정 기입등기 후에 취득한 유치권","항목":["압류의 처분금지 효력 때문에 매수인에게 대항할 수 없음(판례)","매수인에게 변제 책임이 없음","점유를 이전받았더라도 마찬가지"]}},{"종류":"표","제목":"재매각(제138조)","머리":["사항","내용"],"행":[["요건","매수인이 대금지급기한(또는 다시 정한 기한)까지 의무를 완전히 이행하지 않고 차순위매수신고인이 없을 것"],["명령","법원이 직권으로 재매각을 명함"],["매각조건","종전에 정한 최저매각가격, 그 밖의 매각조건 적용"],["재매각 취소","매수인이 재매각기일의 3일 이전까지 대금, 지연이자, 절차비용을 지급하면 절차를 취소"],["전의 매수인","매수신청 불가. 매수신청 보증의 반환 요구도 불가"]]}],"함정":"①은 유치권 자체가 매수인에게 인수된다는 제91조제5항을 그대로 읽으면 옳아 보인다. 이 조항의 유치권은 매수인에게 대항할 수 있는 유치권이고, 압류 후 취득한 유치권은 여기에 해당하지 않는다."}};